INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (1,1,NULL,'3CDB',2,'https://ngdc.cncb.ac.cn/3cdb/','GET','A database of manually curated of chromosome conformation capture data (3CDB).','Chromosome Conformation Capture Database','基于人工审编的染色体构象捕获数据的数据库（3CDB）','染色体构象捕获数据库',1,3,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (2,2,'gsa','GSA',1,'https://ngdc.cncb.ac.cn/gsa','GET','The Genome Sequence Archive (GSA) is a data repository for archiving raw sequence reads. It accepts data submissions from all over the world and provides free access to all publicly available data for global scientific communities.','Genome Sequence Archive',NULL,NULL,1,1,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (3,3,'dbcommons','Database Commons',1,'https://ngdc.cncb.ac.cn/databasecommons','GET','Database Commons provides users with easy access to a comprehensive collection of publicly available biological databases encompassing different data types and spanning diverse organisms.','a catalog of biological databases',NULL,NULL,1,1,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (4,4,'biocode','BioCode',1,'https://ngdc.cncb.ac.cn/biocode','GET','a repository archiving codes for bioinformatics tools','Biological Tool Codes','生物信息学工具代码归档数据库','生物信息代码工具归档库',1,1,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (5,5,'bioproject','BioProject',1,'https://ngdc.cncb.ac.cn/bioproject/','GET','The BioProject database serves as an organizational framework to provide access to metadata about research projects, ranging from genomic, transcriptomic, epigenomic and metagenomic sequencing efforts to genome-wide association studies and variation analyses. A BioProject record also contains a variety of indispensable information about submitter, grant and publication, with links to external resources relevant to the project.','Biological Project Library','','生物项目库',1,1,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (6,6,'biosample','BioSample',1,'http://ngdc.cncb.ac.cn/biosample/','GET','The BioSample database provides structured and indexed descriptive information on biological materials. A BioSample record clarifies context to the derived data, with reciprocal links to BioProject as well as other relevant database resources.','Biological Sample Library','','生物样本库',1,1,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (7,7,'hra','GSA-Human',1,'https://ngdc.cncb.ac.cn/gsa-human/','GET','a part of GSA in the National Genomics Data Center, is a data repository specialized for human genetic related data derived from biomedical researches. Aside from basic data archive services, GSA-Human features:','The Genome Sequence Archive for Human',NULL,NULL,1,1,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (8,8,'omix','OMIX',1,'https://ngdc.cncb.ac.cn/omix','GET','Omix collects the genomics data from transcriptome, epigenome, microarray,the functional genomics data such as lipidome, metabolome, proteome, and other types of scientific data related to research.','Open Archive for Miscellaneous Data',NULL,NULL,1,1,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (9,9,'nucbank_nuc2;nucbank_pro2;','GenBase',1,'https://ngdc.cncb.ac.cn/genbase/','GET','GenBase is a genetic sequence database that accepts user submissions and integrates data from INSDC.','Genetic Sequence Database',NULL,NULL,1,1,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (10,10,NULL,'SDAS',1,'https://ngdc.cncb.ac.cn/sdas/','GET','Scientific Data Archive System provides services such as plan submission, real-time query of data archiving and certificate issuance for National Key Research Project.','Scientific Data Archive System',NULL,NULL,1,1,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (11,11,NULL,'HGRIP',1,'https://ngdc.cncb.ac.cn/hgrip/','GET','Human Genetic Resource Information Management Backup Platform','Human Genetic Resource Information Management Backup Platform',NULL,NULL,1,1,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (12,12,'gvm','GVM',2,'https://ngdc.cncb.ac.cn/gvm','GET','The Genome Variation Map (GVM) is a public data repository of genome variations, including single nucleotide polymorphisms and small insertions and deletions, with particular focuses on human as well as cultivated plants and domesticated animals.','Genome Variation Map',NULL,NULL,1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (13,13,'gwas','GWAS Atlas',2,'https://ngdc.cncb.ac.cn/gwas/','GET','GWAS Atlas is a public and manually curated database of published genome-wide SNP-trait associations for plants and animals.','Genome-Wide SNP-trait Associations Atlas',NULL,NULL,1,3,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (14,14,'gwh','GWH',2,'https://ngdc.cncb.ac.cn/gwh/','GET','The Genome Warehouse (GWH) is a public repository housing genome-scale data for a wide range of species and delivering a series of web services for genome data submission, storage, release and sharing.','Genome Warehouse',NULL,NULL,1,1,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (15,16,NULL,'SR4R',2,'https://ngdc.cncb.ac.cn/sr4r','GET','The SnpReady for Rice (SR4R) database presents four reference panels of SNPs and tools to satisfy different aspects of population genetics, evolutionary analysis, association studies and genomic breeding research for the rice (Oryza sativa) community.','SnpReady for Rice',NULL,NULL,1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (16,17,NULL,'CompoDynamics',2,'https://ngdc.cncb.ac.cn/compodynamics/','GET','CompoDynamics is a comprehensive database for characterizing molecular characteristics of coding sequences (CDS). Taking advantage of the exponential growth of RefSeq data, CompoDynamics presents rich molecular properties for each CDS and genome, and provides a portal to compare these properties in different species, family domains and functional genes.','CompoDynamics: Sequence composition dynamics of genes and genomes',NULL,NULL,1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (17,18,NULL,'CGB',2,'https://ngdc.cncb.ac.cn/cgb/','GET','Coronavirus GenBrowser (CGB), based on a highly efficient analysis framework and a node-picking rendering strategy, enables easy analysis and visualization of SARS-CoV-2 genomic sequences with the transmission-related metadata.','Coronavirus GenBrowser','冠状病毒GenBrowser（CGB）基于高效的分析框架和节点拾取渲染策略，能够利用传播相关的元数据轻松分析和可视化SARS-CoV-2基因组序列。','冠状病毒可视化浏览器',12,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (18,19,NULL,'MTD',3,'https://ngdc.cncb.ac.cn/mtd/','GET','MTD is a mammalian transcriptomic database that is focused on mammalian transcriptomes, and the current version contains data from humans, mice, rats and pigs.','mammalian transcriptomic database',NULL,NULL,1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (19,20,'icg','ICG',3,'https://ngdc.cncb.ac.cn/icg','GET','ICG is a wiki-based knowledgebase of internal control genes (or reference genes) for RT-qPCR normalization in a variety of species. Based on community curation, ICG harnesses collective intelligence to integrate a comprehensive collection of internal control genes curated from a large volume of literatures and provides appropriate internal control genes corresponding to specific experimental conditions for both model and non-model organisms.','A knowledgebase of Internal Control Genes for RT-qPCR normalization',NULL,NULL,1,3,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (20,21,NULL,'RED',3,'https://ngdc.cncb.ac.cn/red','GET','Rice Expression Database (RED) is a repository of gene expression profiles derived entirely from RNA-Seq data analysis on tissues spanning an entire range of rice growth stages and covering a wide variety of biotic and abiotic treatments.','Rice Expression Database',NULL,NULL,1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (21,22,'nebulas','GEN',3,'https://ngdc.cncb.ac.cn/gen/','GET','Gene Expression Nebulas (GEN) is a data portal of gene expression profiles under various conditions derived entirely from RNA-Seq data analysis in multiple species.','Gene Expression Nebulas','Gene Expression Nebulas（GEN）是各种条件下的基因表达谱的数据门户，完全来自多个物种的RNA-seq数据分析。','基因表达数据库',1,1,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (22,23,NULL,'CancerSCEM',3,'https://ngdc.cncb.ac.cn/cancerscem','GET','A public database dedicating to collecting, analyzing, visualizing single-cell RNA-Seq data of human cancers. Multi-level analyses were performed to deeply explore the tumor microenvironment of different types of human cancers and a comprehensive online analyze platform was equipped in the database.','Cancer Single-cell Expression Map','致力于收集、分析和可视化人类癌症单细胞RNA-seq数据的公共数据库。对不同类型的人类肿瘤微环境进行了多层次分析，并在数据库中配备了全面的在线分析平台。','人类癌症单细胞数据库',1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (23,24,'lncrnawiki 2.0','LncRNAWiki',4,'https://ngdc.cncb.ac.cn/lncrnawiki','GET','LncRNAWiki, a knowledgebase of human lncRNAs, has been rapidly expanded by incorporating more experimentally validated lncRNAs. In LncRNAWiki 2.0, all contents are organized in a structured manner powered by MySQL/Java and curators (registered users) are able to submit/edit annotations based on the curation model that includes a wider range of annotation items. The new version incorporates a total of 2,512 lncRNAs and 106,242 associations for disease, function, drug, interacting partner, molecular signature','a wiki-based platform for community curation of human lncRNAs',NULL,NULL,1,3,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (24,25,'lncbook 2.0','LncBook',4,'http://ngdc.cncb.ac.cn/lncbook','GET','LncBook is devoted to the integration and multi-omics annotation of human lncRNAs. It provides a comprehensive and high-quality list of human lncRNAs, enriches these lncRNAs with essential multi-omics signatures, and identifies featured lncRNAs in diseases and diverse biological contexts. LncBook 2.0 accommodates a high-quality collection of 95 243 lncRNA genes and 323 950 transcripts and incorporates their abundant annotations at different omics levels.','a comprehensive database of human long non-coding RNAs',NULL,NULL,1,3,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (25,26,'lncexpdb','LncExpDB',4,'https://ngdc.cncb.ac.cn/lncexpdb/','GET','LncExpDB is a comprehensive database for lncRNA expression. It houses expression profiles of 101,293 high-quality human lncRNA genes derived from 1,977 samples of 337 biological conditions across nine biological contexts. Consequently, it estimates lncRNA genes'' expression reliability and capacities, identifies 25,191 featured genes, and further obtains 28,443,865 lncRNA-mRNA interactions. The lncRNA reference is derived from LncBook 2.0.','expression database of human long non-coding RNAs',NULL,NULL,1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (26,27,'methbank','MethBank',5,'https://ngdc.cncb.ac.cn/methbank','GET','MethBank is a database that integrates high-quality DNA methylomes across a variety of species and provides an interactive browser for visualization of large-scale methylation data.','Methylation Bank',NULL,NULL,1,1,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (27,28,'nucmap','NucMap',5,'http://ngdc.cncb.ac.cn/nucmap','GET','NucMap is a database of genome-wide nucleosome positioning map across species. It is dedicated to collecting, analyzing and storing nucleosome positioning data in all organisms. NucMap provides services on querying and visualizing nucleosome positioning information at single nucleotide resolution. Meanwhile, it also provides some enrichment analysis on interested genes or samples.','Nucleosome Positioning Map',NULL,NULL,1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (28,29,'EwasAtlas','EWAS Atlas',5,'http://ngdc.cncb.ac.cn/ewas','GET','A knowledgebase of epigenome-wide association studies','Epigenome-Wide Association Study Atlas',NULL,NULL,1,3,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (29,30,'EwasDataHub','EWAS Data Hub',5,'https://ngdc.cncb.ac.cn/ewas/datahub','GET','The current release of EWAS Data Hub integrates a comprehensive collection of DNA methylation array data from 75 344 samples and employs an effective normalization method to remove batch effects among different datasets. EWAS Data Hub provides reference DNA methylation profiles under different contexts, involving 81 tissues/cell types (that contain 25 brain parts and 25 blood cell types), six ancestry categories, and 67 diseases (including 39 cancers).','Epigenome-Wide Association Study data hub',NULL,NULL,1,1,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (30,31,NULL,'EpiCancer',5,'https://ngdc.cncb.ac.cn/epicancer/','GET','Epitranscriptomics in Cancers (EpiCancer) is a curated knowledgebase of functional regulation factors, targeted drugs, and multi-dimensional regulation information of both m6A regulators and m6A sites in cancers.','Epitranscriptomics in Cancers',NULL,NULL,1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (31,32,NULL,'EWAS Open Platform',5,'https://ngdc.cncb.ac.cn/ewas/','GET','EWAS Open Platform is a comprehensive analysis suite that integrates EWAS Atlas, EWAS Data Hub and EWAS Toolkit for epigenome-wide association studies.','',NULL,NULL,1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (32,33,NULL,'DSMNC',6,'https://dsmnc.ngdc.cncb.ac.cn/','GET','DSMNC is a database which provides most comprehensive catalogue of somatic SNVs occurring in single cells from various human and mouse normal tissues.','Somatic SNVs occurring in single cells from various human and mouse',NULL,NULL,1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (33,34,'celltaxonomy','Cell Taxonomy',6,'https://ngdc.cncb.ac.cn/celltaxonomy/','GET','Cell Taxonomy is a manually curated repository of cell types and associated markers encompassing a wide range of species, tissues and conditions. Cell Taxonomy presents a well-structured taxonomy for curated cell types and incorporates scRNA-seq datasets for millions of single cells to enable further exploration of cell types and markers. Multi-faceted characterization is provided including association analysis of cell types/markers/tissues, cellular component similarity estimation and quality assessment of','Cell Types and Markers','一种人工审编的细胞类型和相关标记的知识库，涵盖了广泛的物种、组织和条件。细胞分类学为精选的细胞类型提供了一个结构良好的分类学，并结合了数百万个单细胞的scRNA-seq数据集，以便进一步探索细胞类型和标记。提供了多方面的表征，包括细胞类型/标记/组织的关联分析，细胞成分相似性估计和质量评估','细胞类型分类知识库',1,3,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (34,35,'lsd','LSD',7,'https://ngdc.cncb.ac.cn/lsd','GET','The leaf senescence database is a comprehensive resource of senescence-associated genes and their corresponding mutants.','Leaf Senescence Database',NULL,NULL,1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (35,36,NULL,'RiceWiki',7,'https://ngdc.cncb.ac.cn/ricewiki/index.php/Main_Page','GET','RiceWiki, a project of IC4R (Information Commmons for Rice) as well as a component of ScienceWikis, is a wiki-based, publicly editable and open-content platform for community curation of rice genes, viz., a community-curated resource of rice knowledge','Community-curated resource of rice knowledge','','',12,3,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (36,37,'ic4r','IC4R',7,'http://ngdc.cncb.ac.cn/ic4r','GET','Information Commons for Rice (IC4R) is a rice knowledgebase based on an extensible and sustainable architecture that achieves data integration through community-contributed modules. IC4R is designed for scalability and sustainability, integrating data from remote resources through web APIs and featuring collaborative integration of rice data from multiple committed modules and low costs for database update and maintenance.','Information Commons for Rice','水稻信息共享平台（IC4R）是一个基于可扩展和可持续架构的水稻知识库，通过社区贡献的模块实现数据集成。IC4R专为可扩展性和可持续性而设计，通过Web API集成来自远程资源的数据，并具有协作集成来自多个已提交模块的RICE数据以及降低数据库更新和维护成本的特点。','水稻信息共享平台',1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (37,38,NULL,'SorGSD',7,'https://ngdc.cncb.ac.cn/sorgsd','GET','SorGSD is a comprehensive database of sorghum genomic variations (SNPs and INDELs) of 289 accessions, phenotypes, practical tools, resources and critical references','a sorghum genome SNP database',NULL,NULL,1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (38,39,NULL,'ScienceWikis',7,'https://ngdc.cncb.ac.cn/sciencewikis','GET','ScienceWikis is a catalog of biological knowledge wikis and wiki extensions, aiming to exploit the full potential of wiki technology to harness community intelligence in knowledge integration and curation.','Wikis for Community Annotations',NULL,NULL,1,3,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (39,40,NULL,'iDOG',7,'https://ngdc.cncb.ac.cn/idog','GET','the first integrated resource dedicated to domestic dogs and wild canids. It incorporates a variety of omics data, including genome sequences assemblies for dhole and wolf, genomic variations extracted from hundreds of dog/wolf whole genomes, phenotype/disease traits curated from dog research communities and public resources, gene expression profiles derived from published RNA-Seq data, gene ontology for functional annotation, homolog gene information for multiple organisms and disease-related literature.','Integrated resource dedicated to domestic dogs and wild canids',NULL,NULL,1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (40,41,NULL,'PED',7,'http://ngdc.cncb.ac.cn/ped','GET','a curated database of RNA editosome in plants that is dedicated to the curation, integration and standardization of plant editosome data.','Plant editosome database',NULL,NULL,1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (41,42,NULL,'PADS Arsenal',7,'https://ngdc.cncb.ac.cn/padsarsenal','GET','PADS (Prokaryotic Antiviral Defense System) Arsenal is a database of prokaryotic defense systems related genes, which archived genes that are associated with 18 distinctive categories of defense systems.','a database of prokaryotic defense systems related genes',NULL,NULL,1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (42,43,NULL,'iSheep',7,'https://ngdc.cncb.ac.cn/isheep/','GET','iSheep is a dedicated database for Ovis aries that provides open access to a complete collection of sheep genes, variants, genome-wide variant-trait associations and breeds.','iSheep',NULL,NULL,1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (43,44,'hgd','HGD',7,'https://ngdc.cncb.ac.cn/hgd','GET','A data portal of homologous genes across multiple species','Homologous gene database',NULL,NULL,1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (44,45,'tcod','TCOD',7,'https://ngdc.cncb.ac.cn/tcod','GET','TCOD, a multi-omics data platform for tropical crops, provides data service for selective breeding and trait improvement research of tropical crops. Data integrated in TCOD includes Genes, Genomes, Variants, Expressions, Cultivars and Literatures. In addition, TCOD offers online tools for performing genomic data visualization and analyses.','Tropical Crop Omics Database',NULL,NULL,1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (45,46,'edk','EDK',8,'https://ngdc.cncb.ac.cn/edk','GET','an integrated knowledgebase of RNA editome-disease associations manually curated from published literatures.','Editome Disease Knowledgebase',NULL,NULL,1,3,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (46,47,'rcov19','RCoV19',8,'https://ngdc.cncb.ac.cn/ncov','GET','RCoV19  (Previously known as 2019nCoVR) features comprehensive integration of genomic and proteomic sequences as well as their metadata information from the GISAID, NCBI, NMDC, CNGB and CNCB/NGDC. It also incorporates a wide range of relevant information including scientific literatures, news, and popular articles for science dissemination, and provides visualization functionalities for genome variation analysis results based on all collected 2019-nCoV strains.','Resource for Coronavirus 2019',NULL,NULL,1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (47,48,NULL,'Aging Atlas',8,'https://ngdc.cncb.ac.cn/aging/index','GET','Aging Atlas aims to compile large gene expression and regulation datasets created by a range of high-throughput omics technologies and serve as a valuable resource for a range of life science researchers. ','Aging Atlas','Aging Atlas旨在汇编由一系列高通量组学技术创建的大型基因表达和调控数据集，并作为一系列生命科学研究人员的宝贵资源。','衰老数据库',13,3,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (48,49,NULL,'CeDR',8,'https://ngdc.cncb.ac.cn/cedr','GET','CeDR represents an omnibus systematic exploration of tissue cell type specific drug response for human, mouse and cell lines. ','Cellular drug response atlas','CEDR代表了对人类、小鼠和细胞系的组织细胞类型特异性药物反应的综合系统探索。','细胞药物反应知识库',1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (49,50,'ascancer','ASCancer Atlas',8,'https://ngdc.cncb.ac.cn/ascancer','GET','ASCancer Atlas is a comprehensive knowledgebase of Alternative Splicing in human Cancers.',' Knowledgebase of Alternative Splicing in human Cancers.','人类癌症中可变剪接的综合知识库。','人类癌症可变剪切知识库',1,3,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (50,51,'brainbase','BrainBase',8,'https://ngdc.cncb.ac.cn/brainbase','GET','BrainBase integrates not only valuable knowledge associations curated from published literatures but also comprehensive molecular profiles, particularly for glioma, through multi-omics data analysis. Thus, it bears great promise to serve as a valuable knowledgebase for brain studies.','a curated knowledgebase for brain diseases','通过多组学数据分析，BrainBase不仅整合了来自已发表文献的有价值的知识关联，还整合了全面的分子图谱，特别是神经胶质瘤。因此，它很有希望成为大脑研究的一个有价值的知识库。','脑疾病知识库',1,3,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (51,52,NULL,'Regeneration Roadmap',8,'https://ngdc.cncb.ac.cn/regeneration/index','GET','Regeneration Roadmap aims to compile large datasets for gene expression and regulation created by a broad spectrum of high-throughput omics technologies. This one-stop service provides user-friendly functionalities to explore annotated regeneration-related changes in gene expression, as well as raw data downloads from these multi-omics studies.','',NULL,NULL,1,3,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (52,53,'braincatalog','Brain Catalog',8,'https://ngdc.cncb.ac.cn/braincatalog','GET','Brain Catalog is a comprehensive resource for genetic landscape of brain disorders and related phenotypes.','a One-Stop Shop for Brain-related Traits','大脑疾病和相关表型的遗传资源数据库。','脑疾病表型数据库',14,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (53,54,'twasatlas','TWAS Atlas',8,'https://ngdc.cncb.ac.cn/twas/','GET','Transcriptome-Wide Association Studies (TWAS) Atlas is a curated knowledgebase of transcriptome-wide association studies, integrating trait-associated transcriptome signals from TWAS publications and constructing TWAS knowledge graph to provide reliable and practical resource for researchers.','Transcriptome-Wide Association Studies (TWAS) Atlas',NULL,NULL,1,3,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (54,55,NULL,'MACdb',8,'https://ngdc.cncb.ac.cn/macdb/home','GET','MACdb is a comprehensive knowledgebase based totally on manual curation of cancer metabolic literature, providing high quality metabolite associations, online visualizing networks, and other effective tools for cancer or metabonomics researches. MACdb has curated 40,710 metabolite-cancer associations, covering 269 traits which were extracted from 1,127 studies reported in462 publications (17 cancer categories).  knowledge graph is implemented to comprehensively evaluate and visualize associations from metab','A curated knowledgebase for Metabolic Associations across human Cancers',NULL,NULL,1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (55,57,NULL,'NONCODE',4,'http://www.noncode.org/','GET','NONCODE is a comprehensive database of collection and annotation of ncRNAs (excluding tRNAs and rRNAs), especially lncRNAs in animals. NONCODEV6 is dedicated to providing the full scope of lncRNAs across plants and animals. The number of lncRNAs in NONCODEV6 has increased from 548,640 to 644,510 since the last update in 2017. The number of human lncRNAs has increased from 172,216 to 173,112. The number of mouse lncRNAs increased from 131,697 to 131,974. The number of plant lncRNAs is 9, 697.','non-coding RNA knowledge database',NULL,NULL,1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (56,58,NULL,'LncVar',4,'http://bioinfo.ibp.ac.cn/LncVar','GET','LncVar is a database of genetic variation associated with lncRNA genes in six species, and lncRNA genes are collected from the NONCODE V4. LncVar systematically integrated transcription factor binding sites and m6A modification sites of lncRNAs and provided comprehensive effects of SNPs on transcription and modification of lncRNAs.','a database of genetic variation associated with long non-coding genes',NULL,NULL,1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (57,59,NULL,'Dynamic-BM',3,'http://bioinfo.ibp.ac.cn/Dynamic-BM','GET','Dynamic-BM (Dynamic BodyMap) is a database for multiple species from time-series RNA-seq datasets. It specifically curates time-series RNA-seq data and provides dynamic gene expression profiles in more than 25 tissues of 5 species. Time-series RNA-seq data are well-organized in Dynamic-BM. The website provides users with convenient interfaces to explore the RNA-seq data and browse the dynamic gene expression patterns. Dynamic-BM also includes a knowledgebase of development-associated lncRNAs.','dynamic bodymap',NULL,NULL,1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (58,61,NULL,'SmProt',3,'http://bigdata.ibp.ac.cn/SmProt/','GET','SmProt incorporates 255 010 small proteins computationally or experimentally identified in 291 cell lines/tissues derived from eight popular species. The database provides a variety of data including basic information (sequence, location, gene name, organism, etc.) as well as specific information (experiment, function, disease type, etc.).','Small proteins database','','',12,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (59,62,'elmsg','eLMSG',7,'https://www.biosino.org/elmsg/','GET','a web database, which will integrate microbial systematics, genomics, and phenomics (polyphasic taxonomy related phenotypes)','an eLibrary of Microbial Systematics and Genomics',NULL,NULL,1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (60,63,'gtdb','GTDB',2,'https://www.biosino.org/gtdb/','GET','GTDB is an integrated repository of glycosyltransferases, which collects comprehensive information, including amino acid sequences, coding region sequences, available tertiary structures, protein classification families, catalytic reactions and metabolic pathways involved, from distinct well-known databases or predictions.','Integrated repository of glycosyltransferases',NULL,NULL,1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (61,64,NULL,'NPInter',4,'http://bigdata.ibp.ac.cn/npinter5/','GET','NPInter documents functional interactions between ncRNAs (except tRNAs and rRNAs) and biomolecules (proteins, RNAs and DNAs) by manual literature mining and high-throughput data processing. NPInter 5.0 integrates global RNA-DNA interactions from iMARGI, ChAR-seq and GRID-seq, and collects SARS-CoV-2 related RNA interactions. ncRNA interaction entries have been doubled from 1,100,618 to 2,596,695.','an integrated database of ncRNA interactions',NULL,NULL,1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (62,65,NULL,'TransCirc',4,'https://www.biosino.org/transcirc','GET','TransCirc is a specialized database that provide comprehensive evidences supporting the translation potential of circular RNAs (circRNAs). This database was generated by integrating various direct and indirect evidences to predict coding potential of each human circRNA and the putative translation products.','translation potential of circular RNAs  database',NULL,NULL,1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (63,66,NULL,'piRBase',4,'http://bigdata.ibp.ac.cn/piRBase','GET','piRBase is a manually curated resource of piRNAs, which focused on piRNA function analyses as well as piRNA annotation.','a manually curated resource of piRNAs',NULL,NULL,1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (64,67,'kgcov','KGCoV',8,'https://www.biosino.org/kgcov','GET','KGCoV is a knowledge graph of COVID-19 that integrates epidemiological data and virus genomic data to find the evolution trends of reconstruct infection paths of COVID-19.','Knowledge Graph of SARS-CoV-2',NULL,NULL,1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (65,68,NULL,'PGG.Han',2,'https://www.biosino.org/pgghan/index','GET','The Han Chinese Genomes Database (PGG.Han) serves as the central repository of the genomic data of the Han Chinese Genomes Project.','Han Chinese Genomes Database','','',12,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (66,69,NULL,'PGG.SNV',2,'https://pog.fudan.edu.cn/pggsnv/','GET','A database for understanding evolutionary and medical implications of human single nucleotide variations in diverse populations','Population Genomics and Genetics-SNV',NULL,NULL,1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (67,70,'openlb','OpenLB',9,'https://ngdc.cncb.ac.cn/openlb','GET','Open Library of Biosciences','Open Library of Bioscience',NULL,NULL,1,1,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (68,71,NULL,'Education',9,'https://ngdc.cncb.ac.cn/education','GET','a series of educational materials including courses, tutorials, and training documentation','NGDC Education',NULL,NULL,1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (69,72,NULL,'CROST',6,'https://ngdc.cncb.ac.cn/crost','GET','CROST, a comprehensive repository of spatial transcriptomics, offers single-sample analysis, interactive visualization, multi-omics integration for exploring cancer svg, and other powerful tools for spatial transcriptomics researches.','Comprehensive Repository of Spatial Transcriptomics','CROST是一个综合性的空间转录组数据资源库，提供多物种，多疾病和多技术平台的空间转录组数据的整合分析，并提供一站式数据分析平台。',NULL,1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (70,73,NULL,'OBIA',1,'https://ngdc.cncb.ac.cn/obia','GET','The Open Biomedical Imaging Archive is a repository for archiving biomedical imaging data and related clinical data. OBIA provides a reliable platform for biomedical imaging data management to support research activities throughout the world.','Open Biomedical Imaging Archive','开放生物医学成像档案是用于存档生物医学成像数据和相关临床数据的存储库。OBIA 为生物医学成像数据管理提供可靠的平台，以支持世界各地的研究活动。',NULL,1,1,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (71,74,NULL,'OPIA',1,'https://ngdc.cncb.ac.cn/opia/','GET','OPIA is an open repository of plant image data along with corresponding phenotypic trait data. To provide more data resources and image preprocessing services for image-based plant phenotype analysis and applications.','Open Plant Imge Archive','OPIA是一个开放的植物图像数据以及相应表型性状数据的存储库。为基于图像的植物表型分析及应用提供更多数据资源和图像预处理服务。',NULL,1,1,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (72,75,NULL,'BioKA',8,'https://ngdc.cncb.ac.cn/bioka/','GET','BioKA is a curated and integrated knowledgebase of biomarker encompassing multiple animal species, diseases/traits, and annotated resources. To provide comprehensive knowledge not only for human disease research but also for animal diseases and livestock breeding.','Biomarker Knowledgebase for Animals','BIOKA是一个精选和整合的生物标志物知识库，包括多种动物物种、疾病/性状和注释资源。不仅为人类疾病研究，而且为动物疾病和家畜育种提供综合知识。','生物标志物知识库',1,3,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (73,79,NULL,'HALL',8,'https://ngdc.cncb.ac.cn/hall/','GET','The HALL database aims to collect comprehensive and multi-dimensional datasets from diverse human cohorts, spanning a wide range of ages from young and old individuals to centenarians. The HALL also functions as an open-accessed knowledgebase, featuring meticulously curated information regarding aging- and longevity-associated genes, biomarkers, and biological age clocks.','Human Aging and Longevity Landscape','HALL是关于人类衰老和长寿的综合性数据库，旨在收集涵盖从婴幼儿、年轻人、老年人到百岁老人的各个年龄段的不同人群的多维组学知识和数据集。',NULL,1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (74,80,NULL,'TargetGene',2,'https://ngdc.cncb.ac.cn/targetgene/','GET','TargetGene is a comprehensive database of target genes for SNPs associated with complex traits in humans.','TargetGene','TargetGene是关于人类复杂性状相关SNP的靶基因数据库，通过在不同分子水平上链接SNP和靶基因，系统地鉴定出细胞类型特异性的SNP靶基因。',NULL,1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (75,81,NULL,'PlantPan',7,'https://ngdc.cncb.ac.cn/plantpan/','GET','PlantPan is a comprehensive database that encompasses pan-genome analysis results from 11 plant species, consisting of 195 genomes. It provides gene-based and graph-based pan-genome for each species, along with detailed gene functions, 13 types of genomic variations, and genome synteny.','PlantPan','PlantPan是一个综合数据库，包含11个植物物种，195个基因组的泛基因组分析结果。它为每个物种提供了基于基因和基于图谱的泛基因组，以及详细的基因功能、13种类型的基因组变异和基因组同源性等信息。',NULL,1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (76,82,NULL,'HervD Atlas',8,'https://ngdc.cncb.ac.cn/hervd/','GET','Human endogenous retrovirus Disease Atlas is a curated knowledgebase of HERV-Disease associations','Human endogenous retrovirus disease atlas','人类内源性逆转录病毒疾病图谱是HERV疾病关联的人工审编知识库',NULL,1,3,TRUE,'ENABLED','SYSTEM','SYSTEM');
