INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (89,101,NULL,'ChickenGTEx',3,'http://ngdc.cncb.ac.cn/chickengtex','GET','a comprehensive public catalogue of genetic regulatory variants associated with multiple types of transcriptomic phenotypes in distinct biological contexts (e.g., tissues, cell types, development periods, gender, environmental exposures, and genetic backgrounds) in chickens.','ChickenGTEx',NULL,NULL,1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (90,102,NULL,'CNS-GAP',8,'https://ngdc.cncb.ac.cn/cnsgap/index','GET','a landmark central nervous system (CNS) disease genomics program, molecularly characterized over 4028 primary diseases and matched normal samples spanning 10 CNS types, including glioma, pituitary tumor, chordoma, medulloblastoma, medulloblastoma, vascular malformation, ependymoma, germ cell tumor, brain metastasis, brain stem tumor, and neurofibroma. ','CNS Genome Atlas Project',NULL,NULL,1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
