INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (92,104,NULL,'scMethBank',5,'https://ngdc.cncb.ac.cn/methbank/scm/','GET','A database for single-cell methylation maps across multiple species.','single-cell methylation database','多物种单细胞甲基化数据库',NULL,1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (93,105,NULL,'iCTCF',8,'https://ngdc.cncb.ac.cn/ictcf/','GET','Since December, 2019, the outbreak of an unknown viral pneumonia has severely affected Wuhan, China. This virus was quickly identified and named by the World Health Organization (WHO) as severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), and the resulting viral pneumonia was referred to as coronavirus disease 2019 (COVID-19) pneumonia. By the end of March, 2020, nearly 200 countries and regions were affected with > 500,000 confirmed cases, which are still increasing. Such a severe situation under','CT images and clinical features for COVID-19',NULL,NULL,1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (94,106,NULL,'HMC',2,'https://ngdc.cncb.ac.cn/hmc','GET','a curated knowledgebase of human morphology','Human Morphology Catalog',NULL,NULL,1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
