INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (96,108,NULL,'dbDEMC',4,'https://www.biosino.org/dbDEMC/index','GET','dbDEMC (database of Differentially Expressed MiRNAs in human Cancers) is an integrated database that designed to store and display differentially expressed microRNAs (miRNAs) in cancers detected by high-throughput and low-throughput methods. ','database of Differentially Expressed MiRNAs in human Cancers',NULL,NULL,1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (97,109,NULL,'RDBSB',7,'https://www.biosino.org/rdbsb/','GET','Registry and databases of bioparts for synthetic biology','Registry and databases of bioparts for synthetic biology',NULL,NULL,1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (98,110,NULL,'ChickenSD',7,'https://ngdc.cncb.ac.cn/chickensd/','GET','A data container for the variation information of chicken (Gallus gallus) genome. The aim of this database is to construct an SNPs detector and online visualization tool for the chicken research communities on population, evolution, phenotype and life habit studies.','Chicken SNP Database',NULL,NULL,1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (99,111,'p10k','P10K',2,'https://ngdc.cncb.ac.cn/p10k','GET','The Protist 10,000 Genomes (P10K) Project is the first big international genome sequencing initiative to focus on the kingdom of Protista.','The Protist 10,000 Genomes','万种原生生物基因组（P10K）项目是第一个关注原生生物物种的大型国际基因组测序计划。','万种原生生物数据库',1,1,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (100,112,NULL,'scTWAS Atlas',8,'https://ngdc.cncb.ac.cn/sctwas/','GET','scTWAS Atlas catalogs and integrates transcriptome-wide associations at cellular level by literature curation and data analysis, as well as provides rich visualization and analysis tools to promote further research on TWAS associations at single-cell solutions.','Single-cell transcriptome-wide association studies atlas','scTWAS Atlas 通过文献整理和数据分析，收录并整合了细胞水平上的全转录组关联信息，同时提供丰富的可视化和分析工具，以推动单细胞分析中对TWAS关联的进一步研究。',NULL,1,3,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (101,113,NULL,'CVD Atlas',8,'https://ngdc.cncb.ac.cn/cvd/','GET','Cardiovascular Disease Atlas (CVD Atlas) is a comprehensive database of cardiovascular disease, incorporating manually curated gene-disease associations, multi-omics datasets analysis results, and prior knowledge from existing resources.','Cardiovascular disease atlas','CVD Atlas是一个综合性的心脑血管疾病数据库，整合了人工审编的基因-疾病关联、多组学数据分析结果，以及来自现有资源的先验知识。',NULL,1,3,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (102,114,'leukmeia','Leukemia',8,'https://ngdc.cncb.ac.cn/leukemia/','GET','Leukemia Atlas is an integrated, comprehensive database dedicated to the CNV analysis and study of hematological malignancies, with a current focus on acute myeloid leukemia (AML).','Leukemia Atlas','白血病图谱库是一个集成的综合数据库，致力于血液系统恶性肿瘤的拷贝数变异（CNV）分析与研究，目前主要关注急性髓系白血病（AML）。','白血病图谱库',1,1,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (103,127,NULL,'scMultiModalMap',6,'https://ngdc.cncb.ac.cn/scmultimodalmap/','GET','scMultiModalMap is an innovative database designed to equip researchers with tools for exploring, analyzing, and visualizing single-cell multimodal datasets. By leveraging high-resolution data from advanced technologies like CITE-seq and 10x Genomics Multiome, scMultiModalMap connects complex biological data with actionable insights. ','single-cell multimodal data map','SCMultimodalMap是一个创新的数据库，旨在为研究人员提供探索、分析和可视化单细胞多模式数据集的工具。通过利用来自Cite-Seq和10x Genomics Multiome等先进技术的高分辨率数据，SCMultimodalMap将复杂的生物数据与可操作的见解联系起来。','单细胞多模式数据库',12,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (104,128,'te-scale','TE-SCALE',3,'https://ngdc.cncb.ac.cn/te-scale/','GET','A database of transposable element (TE) expression at single-cell resolution, covering 1,317,803 cells across 20 cancer types based on a large volume of scRNA-seq datasets. Multi-layer analyses were performed to characterize TE activity in tumor microenvironments, identify tumor-specific TEs, and enable in-depth functional exploration.','Transposable Element Single-Cell Analysis for pan-cancer Landscape Exploration','单细胞分辨率的转座子表达数据库，基于大量scRNA-seq数据集，涵盖20种癌症类型的 1317803个细胞。进行多层分析来表征肿瘤微环境中的转座子活性，识别肿瘤特异性转座子，并实现深入的功能探索。','泛癌单细胞转座子表达数据库',19,1,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (105,129,NULL,'ResMicroDb',8,'https://resmicrodb.cncb.ac.cn/','GET','ResMicroDb, a comprehensive database and analysis platform for the human respiratory microbiome. ResMicroDb integrates 106,464 samples from 489 publications and 514 projects, covering 10 sample sites and 146 phenotypes.','Respiratory Microbiome Database','RESmicroDB，人类呼吸微生物组的综合数据库和分析平台。ResMicroDB整合了来自489个出版物和514个项目的106，464个样本，涵盖10个样本点和146个表型。','呼吸微生物组数据库',13,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (106,130,NULL,'DDS Atlas',1,'https://ngdc.cncb.ac.cn/ddsatlas/','GET','A Manually Curated DNA Data Storage Technologies Across the Entire Workflow','DNA Data Storage Atlas','基于人工审编的DNA数据存储技术数据库','DNA存储数据库',12,1,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (107,131,NULL,'ClinMAVE',2,'https://ngdc.cncb.ac.cn/clinmave','GET','A curated database of Multiplexed Assays of Variant Effect (MAVE) studies, providing variant-level functional annotations to support genetic variant interpretation, diagnostic decision-making, and exploration of genotype-phenotype relationships in diseases.','MAVE database for clinical application','变异效应多重分析（MAVE）研究的精选数据库，提供变异水平的功能注释，以支持遗传变异解释、诊断决策和探索疾病中的基因型-表型关系。','变异效应多重分析数据库',12,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (108,132,NULL,'CAVDdb',8,'https://ngdc.cncb.ac.cn/cavd/','GET','An integrated resource that provides public data services and analytical tools for calcific aortic valve disease research. The database currently offers comprehensive profiles of genes, proteins, metabolites, and methylation data, enabling multi-omics analysis. It features a genome browser for visualizing diverse omics data, along with two online analysis tools: GO and KEGG enrichment analyses.','Calcific Aortic Valve Disease database','钙化性主动脉瓣疾病数据库（CAVDDB）是为钙化性主动脉瓣疾病研究提供公共数据服务和分析工具的综合资源。该数据库目前提供了基因、蛋白质、代谢物和甲基化数据的全面概况，使多组学分析成为可能。它有一个基因组浏览器，用于可视化不同的组学数据，以及两个在线分析工具：GO和KEGG富集分析。','钙化性主动脉瓣疾病数据库',1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (109,133,NULL,'SCOD',7,'https://ngdc.cncb.ac.cn/scod/','GET','A comprehensive multi-omics data platform for sugarcane and its closely related species.','SugarcaneOmics','甘蔗及其近缘物种的综合多组学数据平台。','甘蔗多组学数据库',1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (110,134,'GlobalMGD','GlobalMGD',2,'https://mdc.im.ac.cn/microxiandao/genome','GET','The Global Microbial Genome Database systematically collects microbial genome data from around the world. After undergoing unified quality control and standardized integration, it currently contains over 510,000 high-quality genome assemblies. The platform supports advanced search options (e.g., keywords, NMDC ID, submitter name, etc.) as well as batch download of raw genome sequences.','Global Microbial Genome Database','全球微生物基因组数据库系统收集了来自全球的微生物基因组数据，经过统一的质量控制和标准化整合，目前已包含超过51万个高质量的基因组组装序列。平台支持高级检索（如关键字、NMDC编号、提交人姓名等）以及基因组原始序列的批量下载。','全球微生物基因组数据库',20,1,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (111,135,'RDFdb','RDFdb',1,'https://mdc.im.ac.cn/microxiandao/article','GET','The Biological Resource RDF Database is an RDF-based literature metadata repository for biological resources. It integrates scholarly articles related to microorganisms and other biological resources, enabling exact queries and advanced searches using fields such as PMID, PMC, title, publication year, journal, species, and strain. The platform presents a query and advanced search interface, delivering metadata retrieval services for literature in the biological resources domain.','Biological Resource RDF Database','生物资源RDF库是一个基于RDF（资源描述框架）技术构建的生物资源文献元数据库。该库整合了与微生物等生物资源相关的学术文献信息，支持通过PMID、PMC、标题、发表年份、期刊、物种、菌株等字段进行精确查询与高级检索。目前页面展示查询和高级检索功能界面，为用户提供生物资源领域文献的元数据检索服务。','生物资源RDF库',20,1,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (112,137,'DNAbcQS','DNAbcQS',1,'https://mdc.im.ac.cn/microxiandao/databaselist','GET','The Core DNA Barcode Database of Important Quarantine Species and Their Relatives is a professional reference database designed for entry-exit quarantine and invasive biological monitoring. It focuses on collecting DNA barcode sequences of key quarantine microorganisms and their closely related species. Each record associates a sequence with a clear taxonomic hierarchy (sample ID, species, family, class, etc.), delivering essential data support for precise species identification and risk early warning.','Core DNA Barcode Database of Important Quarantine Species and Their Related Species','重要检疫物种及其近缘种DNA条形码核心数据库是一个专门针对进出境检疫、入侵生物监测等领域的专业参考数据库。该库重点收录了重要检疫性微生物及其近缘种的DNA条形码序列，每条记录关联了样本ID、物种、科、纲等层级明确的分类等信息，为物种精准鉴定与风险预警提供核心数据支撑。','重要检疫物种及其近缘种DNA条形码核心数据库',20,1,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (113,138,'GMCdb','GMCdb',1,'https://mdc.im.ac.cn/microxiandao/microbialCultureCollectionbase','GET','The Global Microbial Culture Collection Database is a directory resource of microbial culture collections and their holdings from around the world. Each record contains registration number, institution abbreviation, institution full name, culture type, and total culture count, covering diverse microbial types including bacteria, fungi, yeasts, and viruses. The platform enables users to query and access global culture collection information.','Global Microbial Culture Collection Database','全球微生物菌种目录数据库是一个收录全球微生物保藏机构及其菌种资源的目录型数据库。每条记录关联了注册编号、机构缩写、机构全称、菌种类型及菌种总数等信息，涵盖细菌、真菌、酵母、病毒等多种微生物类型，支持对全球菌种保藏资源的查询与检索。','全球微生物菌种目录数据库',20,1,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (114,139,'MCdb','MCdb',1,'https://mdc.im.ac.cn/microxiandao/microbialCultureResourceDatabase','GET','The China Microbial Culture Resource Database is a reference repository of microbial culture resource information. Each record links key details such as culture accession number (CGMCC number), culture name, isolation source, optimal growth temperature, status, and application. Currently holding over 20,000 records, the database enables users to query and retrieve culture resource information.','China Microbial Culture Resource Database','中国微生物菌种资源数据库是一个收录微生物菌种资源信息的参考数据库。每条记录关联了菌种编号（如CGMCC编号）、菌种名称、分离来源、最适生长温度、状态及应用等关键信息。目前数据库包含超过2万条记录，支持菌种资源的查询与检索。','中国微生物菌种资源数据库',20,1,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (115,140,'DNAbcIMD','DNAbcIMD',1,'https://mdc.im.ac.cn/microxiandao/dnabarCop','GET','International Mirror Database of DNA Barcodes serves as a China-based mirror of global DNA barcode data. It synchronizes barcode sequences from authoritative international databases to offer domestic users reliable and rapid local access. The database currently holds more than 2.85 million records, each associated with standardized taxonomic details (sample ID, species, family, class), and supports sequence querying and downloading.','International Mirror Database of DNA Barcodes','DNA条形码国际镜像数据库是国际DNA条形码数据在中国的镜像站点。该库通过同步国际权威数据库的条形码数据，为国内用户提供稳定、快速的本地化访问服务。目前数据库包含超过285万条记录，每条数据关联了样本ID、物种、科、纲等标准化的分类信息，支持序列查询与下载。','DNA条形码国际镜像数据库',20,1,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (116,141,'PathAMR','PathAMR',1,'http://nmdc.cn/gcpathogen/drugresistance/','GET','The Pathogen Antimicrobial Resistance Gene Reference Database is an open-access resource for resistance genes in pathogenic bacteria. It annotates genes from NCBI genomes against CARD, Resfams, and AMRfinder. The database holds over 390,000 strain-level sequences with annotations covering gene name, ID, length, drug class, antibiotic, resistance mechanism, and source species. It supports retrieval by gene, species, drug class, or mechanism, and provides data download.','Pathogen Antimicrobial Resistance Gene Reference Database','病原菌耐药基因数据参考库聚焦病原细菌耐药基因，通过标准化注释流程对NCBI基因组数据进行耐药基因注释（CARD、Resfams、AMRfinder）。收录超39万条序列，涵盖基因名称、药物类型、耐药机制等注释，支持多条件检索及数据下载','病原菌耐药基因数据参考库',20,1,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (117,142,NULL,'iPangolin',2,'https://ngdc.cncb.ac.cn/ipangolin/','GET','iPangolin is the first integrated, multi-dimensional database dedicated to pangolins, the world’s most trafficked and critically endangered mammalian group. ','Multi-dimensional database dedicated to pangolins','iPangolin是首个专门针对穿山甲的综合型数据库。当前版本整合了全部9种穿山甲的参考基因组与全基因组变异数据集，甲片图像、头骨和颅内模型等表型信息，以及物种鉴定模型和地理溯源工具。','穿山甲综合数据库',1,1,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (118,143,NULL,'PWAS Atlas',8,'https://ngdc.cncb.ac.cn/pwas/','GET','PWAS Atlas (https://ngdc.cncb.ac.cn/pwas/) is a comprehensive knowledgebase that systematically integrates publicly available proteome-wide association study (PWAS) findings with large-scale standardized analyses. ','Proteome-wide association study database','PWAS Atlas是整合文献整理与标准化PWAS分析结果的综合知识库，收录蛋白质—性状关联数据，并提供知识图谱、检索、比较分析、可视化及数据下载功能。','全蛋白质组关联数据库',1,3,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (119,144,NULL,'π-OmicsKit',1,'https://ngdc.cncb.ac.cn/piomicskit/home','GET','π-OmicsKit  is an expert-curated resource for reproducible primary processing of omics data. It currently provides 80 ready-to-run kits covering DNA-, RNA- and protein-level measurements across bulk, single-cell, long-read and spatial assays. ','Expert-curated and AI-assisted omics processing kits','π-组学标准处理套件库（π-OmicsKit，https://ngdc.cncb.ac.cn/piomicskit/home）是一个由领域专家构建和审核的组学数据标准化处理资源，旨在实现可重复的原始数据处理。目前，该资源提供80个开箱即用的处理套件，覆盖DNA、RNA和蛋白质层面的测量，以及bulk、单细胞、长读长和空间等实验类型。','π-组学标准处理套件库',16,1,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (120,145,NULL,'SesbaniaOmics',7,'https://ngdc.cncb.ac.cn/sesbaniaomics','GET','SesbaniaOmics is a specialized multi-omics database for Sesbania plants, integrating genomic, transcriptomic, proteomic, epigenomic, and phenotypic data. This resource supports research on salt-tolerance mechanisms, enabling genetic improvement and molecular breeding of stress-resistant crops. By providing comprehensive biological data, SesbaniaOmics facilitates sustainable agriculture in saline-affected regions, addressing global soil salinization challenges.','Multi-omics database for Sesbania plants','SesbaniaOmics是一个专门针对田菁属植物的多组学综合数据库，整合了基因组、转录组、蛋白质组、表观基因组和表型数据。该资源支持耐盐机制研究，有助于耐逆作物的遗传改良和分子育种。通过提供全面的生物学数据，SesbaniaOmics 推动了盐碱影响地区的可持续农业发展，为应对全球土壤盐渍化挑战提供了支撑。','田菁多组学数据库',1,2,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,catalog_id,db_id,name,db_categories_id,db_url,http_method,db_en_description,db_en_title,db_zh_description,db_zh_title,organization_id,type_id,is_visible,status,create_by,update_by) VALUES (121,146,NULL,'iCellomics',1,'https://ngdc.cncb.ac.cn/icellomics/','GET','iCellOmics is an open-access, multi-omics resource for industrially relevant cell lines. Currently, iCellOmics integrates 6 data categories across 17 cell lines, including reference genome annotations, genomic variation, bulk and single-cell transcriptomics profiles, chromatin accessibility maps, and gene–phenotype relationships curated from the literature. ','Industrially relevant cell lines multi-omics integrated database','iCellOmics 是一个提供工业相关的多组学数据资源，包括基因组注释、变异、转录组学、染色质可及性及基因-表型关系，并配备在线分析工具。它整合了标准化分析结果与文献知识，旨在为工业细胞系研究提供用户友好的探索平台。','工业相关细胞系多组学数据库',1,1,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (1,'1','RNA-seq Analysis','Linux','For bulk RNA-seq data, GEN offers online services for differential expression analysis, weighted gene co-expression network analysis (WGCNA), functional enrichment analysis and gene regulatory network inference. To start ‘Bulk RNA-seq Data Analysis’, users should select bulk RNA-seq dataset of interest first.','RNA-seq Analysis','对于批量RNA-seq数据，GEN提供差异表达分析、加权基因共表达网络分析（WGCNA）、功能富集分析和基因调控网络推断的在线服务。要启动“批量RNA-seq数据分析”，用户应首先选择感兴趣的批量RNA-seq数据集。','RNA-Seq分析','https://ngdc.cncb.ac.cn/gen/analysis','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (2,'2','CASA','Windows,Linux,MacOS','Cancer Alternative Splicing Analysis','Cancer Alternative Splicing Analysis','癌症可变剪接分析','癌症可变剪接分析','https://ngdc.cncb.ac.cn/ascancer/tools','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (3,'4','ID conversion','Windows,Linux,MacOS','Upload a file containing gene IDs or enter gene IDs to obtain accession ID across different databases, including LncBook, NONCODE, GENCODE, LNCipedia, BIGtranscriptome, CHESS, RefLnc, MiTranscriptome, FANTOM, HGNC, Entrez, UCSC, RefSeq and lncRNAdb.','ID conversion of lncRNAs from different sources','上传包含基因ID的文件或输入基因ID以获取不同数据库的登录ID，包括LNCBook、NonCode、GenCode、LNCipedia、BigTranscriptome、Chess、ReFNC、MitRanscriptome、Fantom、HGNC、Entrez、UCSC、RefSeq和LNCRNADB。','lncRNA ID转换工具','https://ngdc.cncb.ac.cn/lncbook/tools/conversion','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (4,'5','lncbook-BLAST','Windows,Linux,MacOS','Upload fasta file or paste fasta sequence to find transcripts which have similar regions with input sequence.','lncbook-BLAST','上传FASTA文件或粘贴FASTA序列以查找与输入序列具有相似区域的转录本。','lncRNA序列比较','https://ngdc.cncb.ac.cn/lncbook/tools/blast','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (5,'6','Classification','Windows,Linux,MacOS','Classification of lncRNAs compared to genomic location of protein-coding genes','Classification','lncRNA的分类与蛋白质编码基因的基因组定位的比较','lncRNA分类','https://ngdc.cncb.ac.cn/lncbook/tools/classification','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (6,'7','Functional Prediction','Windows,Linux,MacOS','Gene ontology annotation based on review and co-expression partners','Functional Prediction (Based on curated interacting partners)','基于综述和共表达伙伴的基因本体标注','lncRNA功能预测','https://ngdc.cncb.ac.cn/lncrnawiki/tool','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (7,'8','LncBot','Windows,Linux,MacOS','Intelligent Chat System for Literature Knowledge in lncRNA Domain','Intelligent Chat System for Literature Knowledge in lncRNA Domain','面向lncRNA领域文献知识的智能聊天系统','面向lncRNA领域文献知识的智能对话机器人','https://ngdc.cncb.ac.cn/lncrnawiki/lncbot','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (8,'9','RiceYE','Windows,Linux,MacOS','an intelligent web tool for predicting individual rice yield per plant by deep convolutional neural networks. The training data for the prediction model was WGSR, a dataset containing 93 rice. It offers valuable insights to agricultural researchers, aiding their understanding of rice growth patterns and optimizing cultivation management.','Rice Yield Estimation','通过深度卷积神经网络预测单株水稻产量的智能网络工具。预测模型的训练数据是WGSR，一个包含93个水稻的数据集。它为农业研究人员提供了有价值的见解，帮助他们了解水稻生长模式和优化栽培管理。','单株水稻产量预测工具','https://ngdc.cncb.ac.cn/opia/tools/rice_yield_wgsr','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (9,'10','WheatHE','Windows,Linux,MacOS','We provide an online web tool for predicting the number of wheat heads, which has been pre-trained using the GWHD2020 dataset. Intelligent ear counting is important for efficient and accurate crop yield estimation, facilitating informed agricultural decision-making.','Wheat Head Estimation','我们提供了一个用于预测小麦穗数量的在线网络工具，该工具已使用GWHD2020数据集进行了预训练。智能计穗对于高效、准确的作物估产具有重要意义，为农业决策提供了依据。','智能计穗工具','https://ngdc.cncb.ac.cn/opia/tools/wheat_head_gwhd2020','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (10,'11','RiceVI','Windows,Linux,MacOS','An intelligent tool for identifying rice variety of per plant by deep convolutional neural networks. The training data for the prediction model was WGSR, a dataset containing 93 rice. It offers valuable insights to agricultural researchers, aiding their understanding of rice variety characters and optimizing cultivation management.','Rice Varieties Identification','一种基于深度卷积神经网络的水稻单株品种智能识别工具。预测模型的训练数据是WGSR，一个包含93个水稻的数据集。它为农业研究人员提供了有价值的见解，帮助他们理解水稻品种特性和优化栽培管理。','水稻单株品种智能识别','https://ngdc.cncb.ac.cn/opia/tools/identify_rice_varieties','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (11,'12','LeadSNPFinder','Windows,Linux,MacOS','LeadSNPFinder obtains a list of significantly-independent SNPs that are associated with one or multiple phenotypes of interest. Start by affording your own GWAS summary data, then setting the threshold of significance P-value and LD R2.','LeadSNP identification analysis','LeadSNPFinder获得与一个或多个感兴趣的表型相关的显著独立的SNP的列表。首先提供您自己的GWAS汇总数据，然后设置显著性P值和LD R2的阈值。','LeadSNP鉴定分析','https://ngdc.cncb.ac.cn/gwas/tools/leadSnpRun','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (12,'13','GeneFinder','Windows,Linux,MacOS','GeneFinder generates a list of genes that are associated with one or multiple phenotypes of interest. P-value reflects the significance of gene-level association for user defined phenotypes, which are calculated using theMAGMA (Multi-marker Analysis of GenoMic Annotation).','Trait association gene analysis','GeneFinder生成与一个或多个感兴趣的表型相关的基因列表。p值反映了用户定义的表型的基因水平关联的显著性，这是使用MAGMA（基因组注释的多标记分析）计算的。','表型关联基因分析','https://ngdc.cncb.ac.cn/gwas/tool/geneFinder','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (13,'14','easyGWAS','Windows,Linux,MacOS','easyGWAS provides three datasets as genotype, the SNP from WGS of 2,898 accessions, the SNP from GenoBaits Soy40K array, and genotype uploading by yourself. The MAF and missing rate filtration can be set as genotype quality control. EMMAX, GEMMA, or Plink can be chose for GWAS calculation. Other parameters such as PCA option and threshold setting are afforded. If you would like to upload genotype by yourself, the block-gzipped vcf file lower than 300 Mb is accepted.','Soybean GWAS analysis','EasyGWAS提供了三个数据集：基因型、来自2898份材料的WGS的SNP、来自Genobaits SOY40K阵列的SNP和自己上传的基因型。可以将MAF和缺失率过滤设置为基因型质量控制。可以选择EMMAX、Gemma或PLINK进行GWAS计算。提供诸如PCA选项和阈值设置的其他参数。如果你想自己上传基因型，可以接受低于300 MB的块压缩VCF文件。','大豆GWAS分析','https://ngdc.cncb.ac.cn/soyomics/tools/gwas/run','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (14,'15','ExpPattern','Windows,Linux,MacOS','Soybean Gene Expression Pattern Analysis','Soybean Gene Expression Pattern Analysis','大豆基因表达模式分析','大豆基因表达模式分析','https://ngdc.cncb.ac.cn/soyomics/expression_tool/','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (15,'16','HapSnap','Windows,Linux,MacOS','HapSnap supports haplotype analysis with the SNP/INDEL data of the 2,898 soybeans and 115 phenotypes. Firstly, the target region can be identified as “chromosome:start-end”, or as the “gene ID” + “up/down-stream length”. Secondly, the variation types can be freely combined to make up the haplotypes. Thirdly, the missing rate, minor allele frequency and heterozygous rate can be set as the filtration criteria. After haplotypes are defined, the haplotype frequency, haplotype vs. genotype, linkage disequilibrium will be calculated','Soybean haplotype analysis','HAPSNAP支持使用2，898个大豆和115个表型的SNP/InDel数据进行单倍型分析。首先，可以将目标区域标识为“染色体：开始-结束”，或者标识为“基因ID ”+“上游/下游长度”。其次，变异类型可以自由组合组成单倍型。第三，可以将缺失率、次要等位基因频率和杂合子率作为筛选标准。定义单倍型后，将计算单倍型频率、单倍型与基因型、连锁不平衡','大豆单倍型分析','https://ngdc.cncb.ac.cn/soyomics/haplotype/','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (16,'18','SeqFetch','Windows,Linux,MacOS','Use the SeqFetch to freely extract any sequence from the genomes, including mRNA, CDS, proteins, or any regions, etc.','Soybean Genome Sequence Extraction','使用SeqFetch从基因组中自由提取任何序列，包括mRNA、CDs、蛋白质或任何区域等。','大豆基因组序列提取工具','https://ngdc.cncb.ac.cn/soyomics/seqFetch/run','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (17,'19','BarcodeBLAST','Windows,Linux,MacOS','Species identification','BarcodeBLAST','物种鉴定','物种鉴定','https://ngdc.cncb.ac.cn/cgir/tool/barcode/','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (18,'20','BarcodeFinder','Windows,Linux,MacOS','Barcode sequence identification','Barcode sequence identification','条形码序列识别','条形码序列识别','https://ngdc.cncb.ac.cn/cgir/tool/barcodeFinder/','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (19,'21','VersionMap','Windows,Linux,MacOS','VersionMap is used to convert genomic data between different genome assembly versions.','Convert genomic data between different genome assembly versions','VersionMap用于在不同的基因组组装版本之间转换基因组数据。','基因组组装版本转换','https://ngdc.cncb.ac.cn/gvmhp/','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (20,'24','Editing site identification','Windows,Linux,MacOS','With the development of high-throughput sequencing technology, more and more RNA editing sites are detected based on RNA-seq sequences. To help users determine the interested editing sites, we developed "Editing Site Identification". Besides EDK, it also contains two data sources, namely REDIportal and DARNED, to expand RNA editing sites in normal or case condition. "Editing Site Identification" provides an important function to determine whether user-uploaded sites are RNA editing sites and offers basic information of these sites. Additionally, it will also indicate the link between the site and diseases in EDK.','Editing site identification','随着高通量测序技术的发展，越来越多的RNA编辑位点被基于RNA-seq序列进行检测。为了帮助用户确定感兴趣的编辑位点，我们开发了“编辑位点识别”。除了EDK，它还包含两个数据源，即RediPortal和DarNed，以扩展正常或病例条件下的RNA编辑位点。“编辑位点识别”提供了一个重要的功能来确定用户上传的位点是否是RNA编辑位点，并提供这些位点的基本信息。此外，它还将表明该网站与EDK疾病之间的联系。','编辑位点识别','https://ngdc.cncb.ac.cn/edk/tool/editing/identifier','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (21,'25','EDK-DP','Windows,Linux,MacOS','an algorithm tool based on hypergeometric test method. "Disease Prediction" provides a list of predictive associations according to the differential RNA editing sites (including hit ratio, average risk score, and max risk score), which helps users to assess the strength of the relationship between a cluster of interested editing sites and specific diseases. Additionally, it also provides associations between these sites and diseases based on literature curation.','Disease prediction','基于超几何测试方法的算法工具“疾病预测”。“疾病预测”根据差异RNA编辑位点（包括命中率、平均风险评分和最大风险评分）提供预测关联列表，帮助用户评估一组感兴趣的编辑位点与特定疾病之间的关系强度。此外，它还提供了这些网站与疾病之间的联系，基于文献管理。','疾病预测','https://ngdc.cncb.ac.cn/edk/tool/disease/predictor','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (22,'26','GDNC','Windows,Linux,MacOS','Explore the associations between an edited gene and diseases, or some certain edited genes and diseases. The edge width represents the number of differential editing sites on this gene. Blue represents associations from integrative analysis. Green represents associations from literature curation. Orange represents associations from both integrative analysis and literature curation.  ','Gene-disease network construction','探索编辑基因与疾病之间的联系，或者某些特定的编辑基因与疾病之间的联系。边缘宽度表示该基因上的差异编辑位点的数目。蓝色代表来自综合分析的关联。绿色代表文学策展协会。橙色代表来自综合分析和文献策展的关联。','基因-疾病网络构','https://ngdc.cncb.ac.cn/edk/tool/gene/network','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (23,'27','CDA','Windows,Linux,MacOS','Cross-Disease Analysis provides disease-specific and disease-common differential edited genes, as well as disease-specific and disease-common differential editing sites among some certain diseases. Meanwhilet, it also provides detailed information on these edited genes and editing sites. It supports up to five disease options.  ','Cross-disease analysis','提供疾病特异性和疾病共性差异编辑基因，以及某些疾病之间的疾病特异性和疾病共性差异编辑位点。同时，它还提供了关于这些编辑基因和编辑位点的详细信息。它支持多达五种疾病选项。','跨疾病分析','https://ngdc.cncb.ac.cn/edk/tool/crossdisease','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (24,'28','Editing site annotation','Windows,Linux,MacOS','Based on featured annotations, including cis-RNA editing QTL associations, editing-RNA binding protein associations, and editing-RNA secondary structure associations.','Editing site annotation','基于特征注释的“编辑位点注释”，包括cis-RNA编辑QTL关联、编辑-RNA结合蛋白关联和编辑-RNA二级结构关联。','编辑位点注释','https://ngdc.cncb.ac.cn/edk/tool/site/annotation','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (25,'29','Bulk RNA-seq Data Analysis','Windows,Linux,MacOS','Bulk RNA-seq Data Analysis','Bulk RNA-seq Data Analysis','Bulk RNA-seq数据分析','Bulk RNA-seq数据分析','https://ngdc.cncb.ac.cn/gen/online/tools/','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (26,'30','scRNA-SeqDA','Windows,Linux,MacOS','For scRNA-seq data, users can perform multiple analyses including quality control, data normalization, scaling and regression, dimensional reduction, graph-based clustering, identification of marker genes for cell clusters, gene enrichment analysis for cell markers, cell trajectory inference, and cell type annotation. To start ‘Single-cell RNA-seq Data Analysis’, users should select single-cell RNA-seq dataset of interest first. network inference. To start ‘Bulk RNA-seq Data Analysis’, users should select bulk RNA-seq dataset of interest first.','Single-cell RNA-seq Data Analysis','对于scRNA-seq数据，用户可以执行多种分析，包括质量控制、数据标准化、缩放和回归、降维、基于图的聚类、细胞簇的标记基因识别、细胞标记的基因富集分析、细胞轨迹推断和细胞类型注释。要启动“单细胞RNA-seq数据分析”，用户应首先选择感兴趣的单细胞RNA-seq数据集。网络推理。要启动“批量RNA-seq数据分析”，用户应首先选择感兴趣的批量RNA-seq数据集。','单细胞RNA-Seq数据分析','https://ngdc.cncb.ac.cn/gen/online/tools_cerobro/','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (27,'31','Visualization of scRNA-seq Data Analysis Results','Windows,Linux,MacOS','Interactive investigation and inspection of single-cell transcriptomic profiles incorporated in GEN through visualization of single-cell RNA-seq data analysis results.','Visualization of scRNA-seq Data Analysis Results','通过单细胞RNA-seq数据分析结果的可视化，对GEN中整合的单细胞转录谱进行交互式研究和检查。','scRNA-seq数据分析结果可视化','https://ngdc.cncb.ac.cn/gen/online/visualization4sc/','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (28,'32','Age Predictor','Windows,Linux,MacOS','Age Predictor is an online tool to estimate methylation age of the sample by three machine learning methods (SVM, Random Forest and Elastic Net). Users can input the idat file, processed data or sample ID of GEO datasets to obtain the prediction results.','Age Predictor','Age Predictor是一个在线工具，通过三种机器学习方法（SVM、随机森林和弹性网络）来估计样本的甲基化年龄。用户可以输入IDAT文件、处理后的数据或GEO数据集的样本ID来获得预测结果。','甲基化年龄预测','https://ngdc.cncb.ac.cn/methbank/tools/age/predictor','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (29,'33','DMR Toolkit','Linux','DMR toolkit is a pipline package for differentally methylated regions (DMRs) identification, annotation and enrichment for multiple species','DMR Toolkit','DMR Toolkit是一个用于多个物种的不同甲基化区域（DMR）鉴定、注释和富集的Pipline软件包','基化区域（DMR）鉴定、注释和富集的软件包','https://ngdc.cncb.ac.cn/methbank/tools/dmr/toolkit','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (30,'34','BS-RNA','Linux','Hence, we have developed a specialized tool BS-RNA. Its annotation result is in BED (.bed) format, including locations, sequence context types (CG/CHG/CHH, H = A, T, or C), reference sequencing depths, cytosine sequencing depths, and methylation levels of covered cytosine sites on both Watson and Crick strands. BS-RNA supports both paired-end and single-end sequencing short reads from a directional bisulfite library. Evaluation results of the rates of uniquely mapped reads, rates of correctly mapped reads, and running time for simulated data and actual data indicate that BS-RNA can provide fast and accurate mapping of RNA bisulfite sequencing reads. Comparison between annotated cytosine methylation used BS-RNA and published research also shows that BS-RNA is an effective annotation tool for RNA bisulfite sequencing data.','an efficient mapping and annotation tool for RNA bisulfite sequencing data','我们开发了一种专门的工具BS-RNA用于处理RNA亚硫酸氢盐测序数据。其注释结果为BED（.bed）格式，包括位置、序列背景类型（CG/CHG/CHH，H=A、T或C）、参考测序深度、胞嘧啶测序深度以及Watson和Crick链上覆盖的胞嘧啶位点的甲基化水平。BS-RNA支持来自定向亚硫酸氢盐文库的成对末端和单端测序短读数。对模拟数据和实际数据的唯一映射读数率、正确映射读数率和运行时间的评估结果表明，BS-RNA可以提供快速准确的RNA亚硫酸氢盐测序读数图。使用BS-RNA的注释的胞嘧啶甲基化与已发表的研究的比较也表明BS-RNA是RNA亚硫酸氢盐测序数据的有效注释工具。','RNA亚硫酸氢盐测序数据分析工具','https://ngdc.cncb.ac.cn/bsrna/','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (31,'35','GMQN','Windows,Linux,MacOS','Correcting Batch Effects -GMQN is an online analysis tool for batch effect correction, allowing users to integrate data directly from multiple sources.Users can obtain methylation levels after noise reduction not only by uploading original methylated and unmethylated signal value files but also by entering the project id in NCBI GEO database.The method of this tool is based on Gaussian Mixture Quantile Normalization (GMQN) [PMID=35069703].','Correcting Batch Effects-GMQN','GMQN（Correcting Batch Effects-GMQN）是一款用于批量效应校正的在线分析工具，允许用户直接整合来自多个来源的数据。用户不仅可以通过上传原始的甲基化和未甲基化信号值文件，还可以通过在NCBI GEO数据库中输入项目ID来获得降噪后的甲基化水平。该工具的方法基于高斯混合分位数标准化（GMQN）[PMID=35069703]。','批量效应校正','https://ngdc.cncb.ac.cn/ewas/toolkitGmqn','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (32,'36','EWAS Network Visualization','Windows,Linux,MacOS','Visualization of epigenetic knowledge graph','EWAS Network Visualization','表观遗传知识图的可视化','EWAS网络可视化','https://ngdc.cncb.ac.cn/ewas/network','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (33,'37','Enrichment & Annotation','Windows,Linux,MacOS','Visualization of chromosome position enrichment, functional enrichment, expression correlation, transcription factor enrichment, and other analyses related to methylation site sets','Enrichment & Annotation','染色体位置富集、功能富集、表达相关性、转录因子富集和其他与甲基化位点集相关的分析的可视化','富集和注释','https://ngdc.cncb.ac.cn/ewas/toolkit','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (34,'38','Enrichment analysis in nucleosome occupancy','Windows,Linux,MacOS','Enrichment analysis of nucleosome occupancy in designated regions of the genome for multiple samples','Enrichment analysis in nucleosome occupancy','多样本基因组指定区域核小体占位的富集分析','核小体占位的富集分析','https://ngdc.cncb.ac.cn/nucmap/enrichment-analysis','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (35,'39','CAIN','Windows,Linux,MacOS','Compare the displacement and occupancy differences of 2Kb upstream and downstream of the transcription start site between two samples','Comparative analysis in nucleosomes','比较两个样本在转录起始位点上游和下游2kb的位移和占位差异。','核小体比较分析','https://ngdc.cncb.ac.cn/nucmap/comparative-analysis','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (36,'40','IDMP','Linux','IDMP is a tool to identify the differentially methylated promoters between two samples via Fisher''s exact test with FDR correction. It is written in Perl and is executed from the command line in LINUX system.','Identification of differentially methylated promoters','IDMP是一种通过FDR校正的Fisher精确检验来鉴定两个样品之间差异甲基化启动子的工具。它是用Perl编写的，在Linux系统中从命令行执行。','差异甲基化启动子鉴定','https://ngdc.cncb.ac.cn/methbank/tools/idmp','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (37,'41','DMR Annotation','Windows,Linux,MacOS','Differentially methylated regions (DMRs) enrichment and pathway analysis','DMR Annotation','差异甲基化区域（DMRs）富集和通路分析','差异甲基化区域（DMRs）富集和通路分析','https://ngdc.cncb.ac.cn/methbank/scm/tool/annotation','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (38,'42','Lollipop Plotter','Windows,Linux,MacOS','A web tool for Lollipop-style plot for single cell methylation patterns','Lollipop Plotter','用于单细胞甲基化模式的棒棒糖式绘图的网络工具','单细胞甲基化模式的棒棒糖图','https://ngdc.cncb.ac.cn/methbank/scm/plotDot','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (39,'44','VENAS','Windows,Linux,MacOS','VENAS2 is an updated Viral genome Evolution Network Analysis System.Comprehensive analyses of viral genomes can provide a global picture of SARS-CoV-2 transmission and help to predict the oncoming trends of the pandemic. However, the rapid accumulation of SARS-CoV-2 genomes presents an unprecedented data size and complexity that has exceeded the capacity of existing methods in constructing evolution network through virus genotyping.','Viral genome Evolution Network Analysis System','VENAS2是一个最新的病毒基因组进化网络分析系统，对病毒基因组的全面分析可以提供SARS-CoV-2传播的全局图像，并有助于预测即将到来的大流行趋势。然而，SARS-CoV-2基因组的快速积累呈现出前所未有的数据规模和复杂性，已经超出了通过病毒基因分型构建进化网络的现有方法的能力。','病毒基因组的综合分析','https://www.biosino.org/ipac/venas/main1','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (40,'45','Fastq-to-Variants','Windows,Linux,MacOS','  ‘Fastq-to-Variants’ can align raw NGS sequencing data to the reference genome of 2019nCoV, identify 2019nCoV genetic sequences from the sequencing sample(s), analyze the degree of genomic coverage, sequencing depth, sequencing error rates, detect and annotate the SNPs or Indels.','Fastq-to-Variants','“ FastQ-to-Variants ”可以将原始NGS测序数据与2019NCoV的参考基因组进行比对，从测序样本中识别2019NCoV基因序列，分析基因组覆盖程度、测序深度、测序错误率，检测并注释SNP或INDEL。','新冠病毒序列变异注释','https://ngdc.cncb.ac.cn/ncov/online/tool/variation','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (41,'46','COVID-19 genome variation annotation','Windows,Linux,MacOS','Functional annotation of mutation sites, displaying changes in the gene, code, and amino acids where the mutation site is located, and the degree of impact on gene function.','COVID-19 genome variation annotation','突变位点的功能注释，显示突变位点所在基因、编码和氨基酸的变化，以及对基因功能的影响程度。','新冠基因组变异注释','https://ngdc.cncb.ac.cn/ncov/online/tool/annotation','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (42,'47','COVID-19 haplotype analysis','Windows,Linux,MacOS','Construct a monolithic network using the Minimum Tree Graph based Monomorphic Network Construction Method (McAN).','COVID-19 haplotype analysis','使用基于最小树图的单态网络构建方法（MCAN）构建单片网络。','新冠病毒单体性网络','https://ngdc.cncb.ac.cn/ncov/online/tool/haplotype','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (43,'48','Pangolin COVID-19 Lineage Assigner','Windows,Linux,MacOS','Use Pangolin software to perform Pango lineage prediction on the sequence.','Pangolin COVID-19 Lineage Assigner','使用Pangolin软件对序列进行Pango谱系预测。','Pango谱系预测','https://ngdc.cncb.ac.cn/ncov/online/tool/lineage-assigner','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (44,'49','Monkeypox virus genome variation identification','Windows,Linux,MacOS','Detecting SNP/indel mutation sites; Functional annotation of variant sites; Annotate 190 gene machine protein products of monkeypox genome;','Monkeypox virus genome variation identification','检测SNP/InDel突变位点；变异位点的功能注释；猴痘基因组190个基因机器蛋白产物的注释','猴痘基因组变异识别','https://ngdc.cncb.ac.cn/gwh/poxvirus/online/tools','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (45,'50','Monkeypox virus genome variation annotation','Windows,Linux,MacOS','Functional annotation of mutation sites, displaying changes in the gene, code, and amino acids where the mutation site is located, and the degree of impact on gene function.','Monkeypox virus genome variation annotation','突变位点的功能注释，显示突变位点所在基因、编码和氨基酸的变化，以及对基因功能的影响程度。','猴痘病毒基因组变异注释','https://ngdc.cncb.ac.cn/gwh/poxvirus/online/tool/annotation','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (46,'51','CTC','Windows,Linux,MacOS','Comparison of Two Cell Types','Cell Type Comparator','两种细胞类型的比较','细胞类型比较','https://ngdc.cncb.ac.cn/celltaxonomy/ctc','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (47,'52','CTP','Windows,Linux,MacOS','Predicting cell types based on gene lists','Cell Type Predictor','基于基因列表的细胞类型预测','细胞类型预测','https://ngdc.cncb.ac.cn/celltaxonomy/ctp','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (48,'53','Homolog Finder','Windows,Linux,MacOS','The Homolog Finder facilitates quick homologous gene searches via gene ID and function, while also enabling flexible cross-species genome selection for efficient identification of orthologous and paralogous genes within chosen genomes. Once you click on the small square in the heatmap, a list of homologous genes between the two selected genomes is displayed.','Search for homologous genes among different tropical crops','Homolog Finder通过基因ID和功能促进了快速的同源基因搜索，同时还实现了灵活的跨物种基因组选择，以有效鉴定所选基因组中的直向同源和旁系同源基因。一旦你点击热图中的小方块，就会显示两个选定基因组之间的同源基因列表。','同源基因搜索','https://ngdc.cncb.ac.cn/tcod/homolog','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (49,'54','CTA','Windows,Linux,MacOS','Cross-stages analysis aim to reveal the developmental hematopoiesis in each species  To achieve a balance between retaining original analysis results of each dataset and enabling systematic data integration, we have developed two strategies for cross-dataset analysis: integrative strategy and non-integrative strategy. 1.Non-integrative sstrategy: Researchers can use individual scRNA-seq datasets, which preserve the original analysis results of each dataset, alongside stage-specific atlases we constructed with systematic and manual cell annotations. This allows for cross-dataset comparison without the need for data integration. 2.Integrative strategy: Researchers can utilize constructed cross-stage references for each species, which involve systematic data integration, to perform direct cross-dataset comparisons.','Cross-stages analysis','跨阶段分析旨在揭示每个物种的发育造血。为了在保留每个数据集的原始分析结果和实现系统数据集成之间取得平衡，我们开发了两种跨数据集分析策略：集成策略和非集成策略。1.非整合S策略：研究人员可以使用单独的scRNA-seq数据集，该数据集保留了每个数据集的原始分析结果，以及我们使用系统和手动细胞注释构建的特定阶段图谱。这允许在不需要数据集成的情况下进行跨数据集比较。2.整合策略：研究人员可以利用为每个物种构建的跨阶段参考，这涉及到系统的数据整合，以进行直接的跨数据集比较。','造血干细胞跨时期分析','https://ngdc.cncb.ac.cn/hematlas/featured/organs/','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (50,'55','Cross-species analysis','Windows,Linux,MacOS','Cross-species analysis aim to reveal the evolutionary conservation & difference of hematopoiesis.','Cross-species analysis','跨物种分析旨在揭示造血系统的进化保守性和差异性。','造血细胞的跨物种分析','https://ngdc.cncb.ac.cn/hematlas/featured/species/','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (51,'56','CMA','Windows,Linux,MacOS','The cross-model analysis provides potential clues to engineering hematopoietic system in vitro by comparison with in vivo omics data.','Cross-model analysis','通过与体内组学数据的比较，交叉模型分析为体外构建造血系统提供了潜在的线索。','体内/体外造血细胞的比较分析','https://ngdc.cncb.ac.cn/hematlas/featured/invitro/','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (52,'57','ncRNA-eQTL','Windows,Linux,MacOS','Pathogen identification platform','Pathogen identification platform','病原鉴定平台','病原鉴定','https://www.biosino.org/ipac/ipp/main','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (53,'58','SpeciesComparator','Windows,Linux,MacOS','Comparison of molecular compositions across different species','Comparison of molecular compositions across different species','不同物种间分子组成的比较','物种间分子组成比较','https://ngdc.cncb.ac.cn/compodynamics/tools/speciescompare','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (54,'59','IC','Windows,Linux,MacOS','Image cropping can determine the target object within a small range, thereby reducing computational damage. This tool supports batch cropping of images.','Image Cropping','图像裁剪可以在小范围内确定目标对象，从而减少计算损伤。此工具支持批量裁剪图像。','图像裁剪','https://ngdc.cncb.ac.cn/opia/tools/cropping','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (55,'60','IR','Windows,Linux,MacOS','Image resizing can adjust the size of a single image or compressed image package to the target size. This tool supports batch resizing of images.','Image Resizing','图像大小调整可以将单个图像或压缩图像包的大小调整为目标大小。此工具支持批量调整图像大小。','图像大小调整','https://ngdc.cncb.ac.cn/opia/tools/resizing','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (56,'61','IF','Windows,Linux,MacOS','Image flipping is one of the data augmentation methods used to increase the diversity of the dataset. This tool supports batch flipping of images.','Image Flipping','图像翻转是用于增加数据集多样性的数据增强方法之一。此工具支持批量翻转图像。','图像翻转','https://ngdc.cncb.ac.cn/opia/tools/flipping','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (57,'62','ID','Windows,Linux,MacOS','Image denoising automatically calculates the type of noise in the image and selects the appropriate denoising algorithm for denoising.','Image Denoising','图像去噪自动计算图像中噪声的类型并选择合适的去噪算法进行去噪。','图像去噪','https://ngdc.cncb.ac.cn/opia/tools/denoising','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (58,'63','IP','Windows,Linux,MacOS','Data partitioning divides the original dataset into training set and testing set according to the label category and training set ratio.','Image Partitioning','数据划分根据标签类别和训练集比例将原始数据集划分为训练集和测试集。','图像分区','https://ngdc.cncb.ac.cn/opia/tools/partitioning','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (59,'64','BLAST','Windows,Linux,MacOS','The Basic Local Alignment Search Tool (BLAST) finds regions of local similarity between sequences','Basic Local Alignment Search Tool ','基本局部比对搜索工具（BLAST）查找序列之间具有局部相似性的区域','序列比对','https://ngdc.cncb.ac.cn/blast/home','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (60,'65','MIA','Windows,Linux,MacOS','MIA is a one-stop platform for multi-omics integrative analysis, committing to clustering and identifying feature genes by supervised and unsupervised learning algorithms. Based on input data from single or multiple omics, it is capable for disease subtyping/classification, feature gene identification, differential analysis between normal and disease samples, tissue/cell clustering, etc.','Multi-omics Integrative Analysis','MIA是一个多组学综合分析的一站式平台，致力于通过有监督和无监督学习算法对特征基因进行聚类和识别。基于来自单个或多个组学的输入数据，它能够进行疾病分型/分类、特征基因鉴定、正常和疾病样本之间的差异分析、组织/细胞聚类等。','一种基于精确聚类和特征选择的多组学综合分析机器学习算法','https://ngdc.cncb.ac.cn/mia','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (61,'66','Genome Tracing','Windows,Linux,MacOS','Calculate the most closely related sequence according to SARS-CoV-2 genome or mutation data','SARS-CoV-2 Genome Tracing','根据新冠病毒基因组或突变数据计算最密切相关的序列','新冠病毒基因组溯源','https://ngdc.cncb.ac.cn/ncov/online/tool/genome-tracing/','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (62,'67','Denovo Assembly','Windows,Linux,MacOS','The original data of the second generation sequencing were spliced, and the COVID-19 sequences contained in the sample assembly results were detected.','Denovo Assembly','对第二代测序的原始数据进行拼接，检测样品组装结果中包含的新冠肺炎序列。','新冠病毒拼接','https://ngdc.cncb.ac.cn/ncov/online/tool/denovo-assembly','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (63,'68','Genome Annotation','Windows,Linux,MacOS','This web server supports accurate genome annotation for SARS-CoV-2 in three aspects based on the software VADR (Alejandro et al. 2020):','Gene annotation of COVID-19 sequence.','该网络服务器在三个方面支持SARS-CoV-2的精确基因组注释，基于软件VADR（Alejandro et al.2020）','新冠病毒基因组注释','https://ngdc.cncb.ac.cn/ncov/online/tool/genome-annotation','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (64,'69','SeqQC','Windows,Linux,MacOS','Use FastQC and MultiQC programs to evaluate the sequence quality of files in FASTQ and BAM formats.','SeqQC','使用FastQC和MultiQC程序评估FastQ和BAM格式文件的序列质量。','新冠病毒序列质量评估',NULL,'GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (65,'70','Evolutionary tree','Windows,Linux,MacOS','Build Phylogenetic Tree using maximum likelihood method by IQ-TREE or RAxML for the submitted sequences. The default workflow: ① Input: the submitted SARS-CoV-2 genome sequences; ② Trim Method: excluding the 5’ and 3’ untranslated regions based on SARS-CoV-2 reference genome (NC_045512.2); ③ Substitution Model: Use ModelFinder in IQ-TREE (Use GTRGAMMA in RAxML); ④ Unused Bootstrap test. Customizable parameters: Input sequence type; Trim Method (refseq, TrimAl, None); Software (IQ-TREE or RAxML); Substitution Model; bootstrap (IQ-TREE can also choose UFBoot - Ultrafast Bootstrap Approximation)','Evolutionary tree','通过IQ-Tree或RAXML对提交的序列使用最大似然法构建系统发育树。默认工作流程：①输入：提交的SARS-CoV-2基因组序列；②TRIM方法：基于SARS-CoV-2参考基因组排除5 ''和3 ''非翻译区（NC_045512 2）；③替换模型：在IQ-Tree中使用ModelFinder（在RAXML中使用GTRGamma）；④未使用的引导测试。可自定义参数：输入序列类型；修剪法（RefSeq、TriMal、None）；软件（IQ-Tree或RAXML）；替代模型；Bootstrap（IQ-Tree也可以选择ufboot-超快Bootstrap近似值）','新冠病毒系统进化树','https://ngdc.cncb.ac.cn/ncov/online/tool/tree','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (66,'71','GEA','Windows,Linux,MacOS','The Pango Lineage Assigner supports Pango lineage assigned for submitted SARS-CoV-2 genome sequences based on the software Pangolin. The Phylogenetic Placement can display the placement of the sequence confirmed as SARS-CoV-2 within the global reference tree. And support users to customize the fields displayed in the reference tree.','Genealogy and Evolutionary Analysis','Pango谱系指定器支持基于Pangolin软件为提交的SARS-CoV-2基因组序列指定的Pango谱系。系统发生位置可以显示确认为SARS-CoV-2的序列在全局参考树中的位置。支持用户自定义参照树中显示的字段。','新冠病毒谱系与进化分析','https://ngdc.cncb.ac.cn/ncov/online/tool/lineage-tree','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (67,'72','LUTLSRS','Windows,Linux,MacOS','The present invention provides a model for secondary typing of lung adenocarcinoma based on TLS as well as prognostic survival prediction, wherein a total of 17 genes are captured in said model, and all patients are assessed for risk by secondary typing through the combined analysis of single-cell RNA-seq, Bulk RNA-seq, and clinical data, wherein the progression of a patient''s disease can be scored through the contribution of a few genes, as well as predicting the survival rate of 1 to 5 years.','A model for secondary typing of lung adenocarcinoma based on TLS as well as prognostic survival prediction','本发明提供了一种基于TLS以及预后生存预测的肺腺癌二次分型模型，其中在所述模型中总共捕获了17个基因，并且通过对单细胞RNA-seq、批量RNA-seq和临床数据的组合分析进行二次分型来评估所有患者的风险，其中可以通过几个基因的贡献来对患者的疾病进展进行评分，以及预测1-5年的生存率。','肺腺癌二级分型模型及预后生存预测','https://cryconnor.shinyapps.io/LUTLSRS/','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (68,'73','Bar','Windows,Linux,MacOS','Draw a bar plot for the given dataset','Bar','为给定的数据集绘制条形图','柱状图','https://ngdc.cncb.ac.cn/bit/bar','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (69,'74','Box','Windows,Linux,MacOS','Draw a box plot for the given dataset','Box','为给定的数据集绘制箱形图','箱线图','https://ngdc.cncb.ac.cn/bit/box','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (70,'75','Comutation','Windows,Linux,MacOS','Draw a comutation plot for the given dataset','Comutation','绘制给定数据集的转换图','转换图','https://ngdc.cncb.ac.cn/bit/comutation','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (71,'76','Dot','Windows,Linux,MacOS','Draw a dot plot for the given dataset','Dot Plot','为给定的数据集绘制一个点图','散点图','https://ngdc.cncb.ac.cn/bit/dot','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
