INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (75,'80','Lollipop','Windows,Linux,MacOS','Draw a lollipop for the given dataset','Lollipop','为给定的数据集绘制棒棒糖','棒棒糖图','https://ngdc.cncb.ac.cn/bit/lollipop','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (76,'81','MafSummary','Windows,Linux,MacOS','Draw a MAF summary for the given dataset','Mutation Annotation Format  summary','突变注释格式绘制给定数据集的MAF摘要','变异注释可视化','https://ngdc.cncb.ac.cn/bit/mafsummary','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (77,'82','Oncoprint','Windows,Linux,MacOS','Draw a oncoprint for the given dataset','Oncoprint','为给定的数据集绘制OncoPrint','OncoPrint','https://ngdc.cncb.ac.cn/bit/oncoprint','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (78,'83','Survival','Windows,Linux,MacOS','Draw a survival plot for the given dataset','Survival Plot','绘制给定数据集的生存图','生存图','https://ngdc.cncb.ac.cn/bit/survival','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (79,'84','Maftitv','Windows,Linux,MacOS','Draw a MAF titv for the given dataset','MAF TITV','为给定数据集绘制MAF TITV','MAF TITV','https://ngdc.cncb.ac.cn/bit/maftitv','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (80,'85','Upset','Windows,Linux,MacOS','Draw an upset for the given dataset','Upset Plot','为给定的数据集绘制翻转图','翻转图','https://ngdc.cncb.ac.cn/bit/upset','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (81,'86','Venn','Windows,Linux,MacOS','Draw a venn plot for the given dataset','Venn Plot','为给定的数据集绘制维恩图','维恩图','https://ngdc.cncb.ac.cn/bit/venn','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (82,'87','Needle','Windows,Linux,MacOS','Needleman-Wunsch global alignment of two sequences','Needleman-Wunsch global alignment ','两个序列的Needleman-Wunsch全局比对','Needleman-Wunsch全局比对','https://ngdc.cncb.ac.cn/bit/needle','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (83,'88','Water','Windows,Linux,MacOS','Water uses the Smith-Waterman algorithm (modified for speed enhancments) to calculate the local alignment of a sequence to one or more other sequences. The gap insertion penalty, gap extension penalty and substitution matrix used to calculate the alignments are specified. The output is a standard EMBOSS alignment file.','Smith-Waterman local alignment of sequences','Water 使用Smith-Waterman算法（针对速度增强进行了修改）来计算序列与一个或多个其他序列的局部比对。指定了用于计算比对的空位插入罚分、空位延伸罚分和替换矩阵。输出为标准的浮雕对齐文件。','Smith-Waterman 局部比对工具','https://ngdc.cncb.ac.cn/bit/water','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (84,'89','Dotmatcher','Windows,Linux,MacOS','Draw a threshold dotplot of two sequence','Dotmatcher','绘制两个序列的阈值点图','阈值点图','https://ngdc.cncb.ac.cn/bit/dotmatcher','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (85,'90','Dotpath','Windows,Linux,MacOS','Draw a non-overlapping wordmatch dotplot of two sequences','Dotpath','绘制两个序列的非重叠字匹配点图','非重叠字匹配点图','https://ngdc.cncb.ac.cn/bit/dotpath','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (86,'91','Dottup','Windows,Linux,MacOS','Display a wordmatch dotplot of two sequences','Dottup','显示两个序列的字匹配点图','字匹配点图','https://ngdc.cncb.ac.cn/bit/dottup','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (87,'92','Polydot','Windows,Linux,MacOS','polydot generates a dotplot for each of an all-against-all comparison of a set of sequences. The dotplots are rendered on a single diagram. The dotplot is an intuitive graphical representation of the regions of similarity between two sequences. All positions from the first input sequence are compared with all positions from the second input sequence searching for exact matches between sequence regions ("words"). The two sequences are the axes of the rectangular dotplot. Wherever there is "similarity" between a word from each sequences a dot is plotted. The wordsize is specified by the user. Optionally, information on the sequence and location of all the exact matching regions may be written to file as a feature file.','Draw dotplots for all-against-all comparison of a sequence set','Polydot为一组序列的所有对所有比较中的每一个生成一个点图。点图呈现在单个图表上。点图是两个序列之间相似区域的直观图形表示。将来自第一输入序列的所有位置与来自第二输入序列的所有位置进行比较，以搜索序列区域（“词”）之间的精确匹配。这两个序列是矩形点图的轴。只要每个序列中的单词之间存在“相似性”，就会绘制一个点。字长由用户指定。可选地，可以将关于所有精确匹配区域的序列和位置的信息作为特征文件写入文件。','序列比较散点图','https://ngdc.cncb.ac.cn/bit/polydot','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (88,'93','Manhattan','Windows,Linux,MacOS','A Manhattan plot is used to display data with a large number of data-points, many of non-zero amplitude, and with a distribution of higher-magnitude values. The plot is commonly used in genome-wide association studies (GWAS) to display significant SNPs.','Manhattan Plot','曼哈顿图用于显示具有大量数据点、许多非零振幅以及具有较高幅度值分布的数据。该图通常用于全基因组关联研究（GWAS），以显示显著的SNPs。','曼哈顿图','https://ngdc.cncb.ac.cn/bit/manhattan','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (89,'94','Q-Q','Windows,Linux,MacOS','A Q–Q plot (quantile-quantile plot) is a probability plot, which is a graphical method for comparing two probability distributions by plotting their quantiles against each other.','Draw a QQ plot for the given dataset','Q–Q图（分位数-分位数图）是一种概率图，它是一种通过绘制两个概率分布的分位数来比较两个概率分布的图形方法。','分位数-分位数图',NULL,'GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (90,'95','CIRI3-Web','Windows,Linux,MacOS','CIRI3 is a comprehensive analysis package for the detection and quantification of circRNAs in RNA-Seq data','CIRI3-Web','CIRI3是一个全面的分析软件包，用于检测和定量RNA-seq数据中的circRNAs','circRNAs定量分析','https://ngdc.cncb.ac.cn/bit/ciri3','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (91,'96','PM-Adiversity','Windows,Linux,MacOS','Calculate biodiversity indices (such as Shannon, Simpson, and Chao1). Based on the analysis results, generate textual outputs containing diversity indices and PDF outputs of box plots of the diversity indices. This also includes performing statistical tests on the data (such as the Wilcoxon test and the Kruskal-Wallis test), and visualizing the analysis of correlations between variables.','Alpha diversity index calculation and plotting','计算生物多样性指数（如Shannon、Simpson和Chao1）。基于分析结果，生成包含多样性指数的文本输出和多样性指数的箱形图的PDF输出。这还包括对数据进行统计检验（如Wilcoxon检验和Kruskal-Wallis检验），以及对变量之间的相关性进行可视化分析。','计算生物多样性指数','https://ngdc.cncb.ac.cn/bit/pmAdiversity','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (92,'97','CIRI-deep','Windows,Linux,MacOS','Predict differentially spliced circRNAs.','CIRI-deep','预测差异剪接的circRNAs。','差异剪接预测','https://ngdc.cncb.ac.cn/bit/ciriDeep','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (93,'98','PM-Bdiversity','Windows,Linux,MacOS','Conduct ANOVA and ANOSIM statistical tests on each group of metadata, and record the results in log files and summary tables. Generate box plots or scatter plots of distance matrices based on categorical or continuous metadata. Perform corresponding statistical tests such as t-test and Wilcoxon test.','Beta diversity PERMANOVA and ANOSIM tests and plotting using distance matrices','对每组元数据进行ANOVA和ANOSIM统计检验，并将结果记录在日志文件和汇总表中。基于分类或连续元数据生成距离矩阵的箱形图或散点图。进行相应的统计检验，如t检验和Wilcoxon检验。','Beta多样性Permanova和ANOSIM测试以及使用距离矩阵绘图','https://ngdc.cncb.ac.cn/bit/pmBdiversity','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (94,'99','PM-Distribution','Windows,Linux,MacOS','Use ggplot2 to plot the relative abundance bar plot of the samples and save the graph as a PDF file. If a metadata file is provided, additional facet plots classified by metadata are generated and saved.','Plot relative abundance bar graph','使用ggplot2绘制样品的相对丰度条形图，并将图形保存为PDF文件。如果提供了元数据文件，则会生成并保存按元数据分类的其他分面图。','丰度条形图','https://ngdc.cncb.ac.cn/bit/pmDistribution','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (95,'100','PM-Hcluster','Windows,Linux,MacOS','Cluster distance data using a hierarchical clustering method (average linkage is the default). Draw a hierarchical clustering dendrogram in a PDF file and add rectangular boxes to highlight the clustering results based on the specified number of groups','Hierarchical clustering by distance matrix','使用层次聚类方法对距离数据进行聚类（默认为平均链接）。在PDF文件中绘制层次聚类树状图，并添加矩形框以根据指定的组数突出显示聚类结果','基于距离矩阵的层次聚类','https://ngdc.cncb.ac.cn/bit/pmHcluster','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (96,'101','PM-Heatmap','Windows,Linux,MacOS','Cluster the rows and columns of the heat map using a hierarchical clustering method (default is average linkage method). Draw a heat map of the distance matrix and save it as a PDF file. The heat map displays the clustering results.','Distance matrix heatmap','使用层次聚类方法（默认为平均链接方法）对热图的行和列进行聚类。绘制距离矩阵的热图并将其保存为PDF文件。热图显示聚类结果。','距离矩阵热图','https://ngdc.cncb.ac.cn/bit/pmHeatmap','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (97,'102','PM-Marker-Corr','Windows,Linux,MacOS','Calculate the correlation coefficient and P value between the feature table and the numerical data in the metadata. The calculated correlation coefficient and adjusted P-value are then saved to a file and the features are sorted by correlation strength. For each metadata variable, a scatterplot PDF containing significantly correlated features is generated. The graph shows the correlation coefficient, P value, and fitted regression line.','Candidate biomarker selection by regression','计算特征表与元数据中数值型数据的相关系数和P值。然后将计算的相关系数和调整的p值保存到文件中，并按相关强度对特征进行排序。对于每个元数据变量，生成包含显著相关特征的散点图PDF。该图显示了相关系数、P值和拟合的回归线。','生物标志物选择','https://ngdc.cncb.ac.cn/bit/pmMarkerCorr','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (98,'103','PM-Marker-Test','Windows,Linux,MacOS','Based on the classification information in the metadata, perform statistical tests between groups, including analysis of variance, T-test, Wilcoxon test, etc., and perform P-value correction. Draw box plots for variables with significant differences and display them by group to visualize the distribution differences of the data. Generate detailed log files recording the analysis process and results, including input parameters and statistical summaries.','Candidate biomarker selection by rank sum test','基于元数据中的分类信息，进行组间统计检验，包括方差分析、t检验、Wilcoxon检验等，并进行P值校正。为差异显著的变量绘制箱形图，并分组显示，以直观显示数据的分布差异。生成详细的日志文件，记录分析过程和结果，包括输入参数和统计摘要。','秩和检验选择候选生物标志物','https://ngdc.cncb.ac.cn/bit/pmMarkerTest','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (99,'104','PM-Marker-RFscore','Windows,Linux,MacOS','A random forest model is run on each categorical variable in the metadata, feature importance is calculated and the model error rate is evaluated. Use ggplot2 to generate a feature importance plot for each categorical variable and save it as a PDF file. Outputs feature importance data to a text file, which includes the error rate of the random forest model and the average reduced accuracy of the feature.','Ranking biomarkers by random forest importance scoring','在元数据中的每个分类变量上运行随机森林模型，计算特征重要性并评估模型错误率。使用ggplot2为每个分类变量生成特征重要性图，并将其保存为PDF文件。将特征重要性数据输出到文本文件，其中包括随机森林模型的错误率和特征的平均降低精度。','生物标志物排序','https://ngdc.cncb.ac.cn/bit/pmMarkerRFscore','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (100,'105','PM-Network','Windows,Linux,MacOS','Read the distance matrix file and construct an undirected graph based on the set threshold and positive and negative edge parameters. Then set the color and weight of the edges in the graph. Positive edges are green, negative edges are red, and based on the absolute value of the correlation coefficient Determine the edge weight. Calculate and visualize various statistical indicators of the network, such as the number of nodes, number of connected components, number of positive and negative edges, network density, diameter, radius and centralization index. The network is laid out using the Fruchterman-Reingold algorithm, and the statistical summary information of the network is used as the title of the figure. Export the network diagram to a PDF file, and indicate the colors of the positive and negative edges in the legend.','Co-occurrence network mapping using correlations among community members','读取距离矩阵文件，根据设定的阈值和正负边参数构造无向图。然后设置图形中边的颜色和权重。正边缘为绿色，负边缘为红色，并基于相关系数的绝对值确定边缘权重。计算并可视化网络的各种统计指标，如节点数、连通分量数、正负边数、网络密度、直径、半径和中心化指数等。使用Fruchterman-Reingold算法对网络进行布局，并将网络的统计摘要信息作为图的标题。将网络图导出为PDF文件，并在图例中指出正负边的颜色。','网络关系图','https://ngdc.cncb.ac.cn/bit/pmNetwork','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (101,'106','PM-Pca','Windows,Linux,MacOS','Use the functions in the vegan package to process the distance matrix, perform principal component analysis, and calculate the scores of the first three principal components. Based on the classification information in the metadata, draw a PCA plot for each categorical variable, and use ggplot2 to generate scatter plots including PC1 vs PC2, PC1 vs PC3, and PC2 vs PC3.','Principal component analysis (PCA) and plot','使用Vegan包中的函数处理距离矩阵，执行主成分分析，并计算前三个主成分的得分。根据元数据中的分类信息，为每个分类变量绘制PCA图，并使用ggplot2生成包括PC1 vs PC2、PC1 vs PC3和PC2 vs PC3的散点图。','主成分分析画图','https://ngdc.cncb.ac.cn/bit/pmPca','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (102,'107','PM-Pcoa','Windows,Linux,MacOS','Use the functions in the vegan package to process the distance matrix and perform PCoA to calculate the principal coordinates of the sample. Based on the classification information in the metadata, draw a PCoA plot for each categorical variable, and use ggplot2 to generate scatter plots of PC1 vs PC2, PC1 vs PC3, and PC2 vs PC3.','Principal coordinate analysis and plotting','使用Vegan包中的函数处理距离矩阵并执行PCoA以计算样本的主坐标。根据元数据中的分类信息，为每个分类变量绘制PCoA图，并使用ggplot2生成PC1 vs PC2、PC1 vs PC3和PC2 vs PC3的散点图。','主坐标分析绘图','https://ngdc.cncb.ac.cn/bit/pmPcoa','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (103,'108','EditingFactorDetector','Windows,Linux,MacOS','EditingFactorDetector is used to identify plant candidate RNA editing factors, including PPR, MORF, ORRM, and OZ, and their subcellular localization.','EditingFactorDetector','EditingFactorDetector用于鉴定植物候选RNA编辑因子，包括PPR、MORF、ORRM和OZ，以及它们的亚细胞定位。','鉴定植物候选RNA编辑因子','https://ngdc.cncb.ac.cn/bit/ppr','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (104,'109','MRAS','Windows,Linux,MacOS','MRAS is designed to identify the critical splicing factors whose altered expression drives extensive splicing abnormalities.','Master Regulator of Alternative Splicing','MRAS通过整合RBP与事件的互作信息和多种富集分析的方法实现关键剪接因子的推断。','选择性剪接的关键调节因子识别软件','https://ngdc.cncb.ac.cn/bit/mras','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (105,'110','FunGen','Windows,Linux,MacOS',' FunGen (Fungal Gene) is a reference-free tool to construct accurate transcripts using long-read metatranscriptomic data through read clustering and error correction. It is consists of two main stages: (1) clustering error-prone long reads that are potentially from the same gene and (2) performing error correction within each cluster.  ','a reference-free tool to construct accurate transcripts using long-read metatranscriptomic data through read clustering and error correction.','FUNGEN（真菌基因）是一种无需参考文献的工具，通过阅读聚类和纠错，使用长阅读元转录组数据构建准确的转录本。它由两个主要阶段组成：（1）对可能来自同一基因的易出错的长读数进行聚类；（2）在每个聚类内执行纠错。','基于长读长宏转录组数据的真核微生物聚类校正工具','https://ngdc.cncb.ac.cn/bit/fungen','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (106,'111','SCSES','Windows,Linux,MacOS',' Alternative splicing (AS) significantly contributes to cellular transcriptomic heterogeneity, and single-cell RNA-Seq is commonly employed to delineate this heterogeneity. However, due to high dropout rates, inevitable noise, and limited coverage, accurately characterizing splicing changes at single-cell level remains challenging. To address this, we present a computational framework called SCSES (Single-Cell Splicing EStimation) to improve the AS profiles, which imputes the junction count matrix and fills in missing AS alternations by sharing information across similar cells or events with data diffusion.','Estimation of alternative splicing intensity at single cell levels','可变剪接（AS）对细胞转录组的异质性有显著贡献，单细胞RNA-Seq通常用于描述这种异质性。然而，由于高丢失率、不可避免的噪声和有限的覆盖范围，在单细胞水平上准确表征剪接变化仍然具有挑战性。为了解决这个问题，我们提出了一个称为SCSES（单细胞剪接估计）的计算框架来改进AS轮廓，它通过数据扩散在相似的细胞或事件之间共享信息来估算连接计数矩阵并填补缺失的AS交替。','单细胞可变剪接识别与定量分析','https://ngdc.cncb.ac.cn/bit/scses','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (107,'112','GOT','Windows,Linux,MacOS','GOT is a tool to infer vector field for time-series single cell data','Graph-constrained Optimal Transport','GOT基于图约束最优传输理论与向量场学习方法，能够从单细胞数据中推断细胞演化向量场，识别分化路径与命运趋势','单细胞轨迹推断分析','https://ngdc.cncb.ac.cn/bit/got','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (108,'113','SpaMI','Windows,Linux,MacOS','SpaMI is a tool used for spatial multi-omics data integration.','Spatial multi-omics data integration','SPAMI综合考虑各组织学数据异质性，使整合后的数据能够揭示更全面的生物学特征。','基于图神经网络的空间多组学数据整合软件','https://ngdc.cncb.ac.cn/bit/spami','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (109,'114','FGOT','Windows,Linux,MacOS','FGOT is an interpretable integration tool for single-cell and spatial multi-omics data.','Feature Guided Optimal Transport','FGOT采用先验特征图约束最优传输方法，实现细胞状态特异或空间特异的转录调控关系识别。','基于最优传输的多组学数据整合','https://ngdc.cncb.ac.cn/bit/fgot','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (110,'115','TACOS','Windows,Linux,MacOS','TACOS is an integration tool for multiple spatial transcriptomics data.','Community-enhanced integration','TACOS能够对齐来自不同平台的切片不同发育时刻共有的组织区域，同时识别出发育时期特异的区域。','基于增强图空间组学数据整合软件','https://ngdc.cncb.ac.cn/bit/tacos','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (111,'125','KaKs_Calculator','Windows,Linux,MacOS','KaKs_Calculator is capable for calculating selective pressure on both coding and non-coding sequences. For coding sequences, it integrates several methods to calculate nonsynonymous Ka and synonymous Ks substitution rates; particularly, it adopts model selection and model averaging to include as many features as needed for accurately capturing evolutionary information in protein-coding sequences. Similar to the Ka/Ks ratio for coding sequences, selection on non-coding sequences can be quantified as non-coding nucleotide substitution rate Kn normalized by synonymous substitution rate of adjacent coding sequences.','KaKs_Calculator','KAKS_计算器能够计算编码和非编码序列上的选择压力。对于编码序列，综合了几种计算非同义Ka和同义KS替换率的方法；特别地，它采用模型选择和模型平均来包含尽可能多的特征，以准确地捕获蛋白质编码序列中的进化信息。类似于编码序列的Ka/KS比率，对非编码序列的选择可以量化为由相邻编码序列的同义替换率标准化的非编码核苷酸替换率Kn。','选择压力计算工具','https://ngdc.cncb.ac.cn/biocode/tool/BT000001','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (112,'126','CAT','Windows,Linux,MacOS',' a toolkit for molecular sequence composition analysis that includes a novel measure of codon usage bias, Codon Deviation Coefficient, CDC. Unlike previous measures, CDC effectively accounts for background nucleotide composition in estimating codon usage bias and utilizes a bootstrap assessment of the statistical significance of codon usage bias.','Composition Analysis Toolkit','一种用于分子序列组成分析的工具包，其包括密码子使用偏性、密码子偏离系数、CDC的新测量。与以前的方法不同，CDC在估计密码子使用偏性时有效地考虑了背景核苷酸组成，并利用Bootstrap评估密码子使用偏性的统计显著性。','序列组成分析工具集','https://ngdc.cncb.ac.cn/biocode/tool/BT000002','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (113,'127','ParaAT','Windows,Linux,MacOS','a parallel tool that parallelly constructs protein-coding DNA alignments for a large number of homologs. ParaAT is well suited for large-scale data analysis in the high-throughput era, providing good scalability and exhibiting high parallel efficiency for computationally demanding tasks','Parallel Alignment and back-Translation','一种并行构建大量同源物的蛋白质编码DNA比对的并行工具。ParaAT非常适合高吞吐量时代的大规模数据分析，提供良好的可扩展性，并为计算要求高的任务提供高并行效率','并行比对工具','https://ngdc.cncb.ac.cn/biocode/tool/BT000003','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (114,'128','LGC','Windows,Linux,MacOS','LGC characterizes and identifies lncRNAs based on the relationship between ORF (open reading frame) Length and GC content. LGC is able to accurately distinguish lncRNAs from protein-coding RNAs in a cross-species manner without species-specific adjustments, and is robustly effective in discriminating lncRNAs from protein-coding RNAs across species that range from plants to mammals.','Characterization and identification of long non-coding RNAs based on feature relationship','LGC基于ORF（开放阅读框）长度和GC含量之间的关系来表征和鉴定lncRNA。LGC能够以跨物种的方式准确区分lncRNA和编码蛋白质的RNA，而无需物种特异性调整，并且在区分从植物到哺乳动物的跨物种的lncRNA和编码蛋白质的RNA方面非常有效。','lncRNA识别','https://ngdc.cncb.ac.cn/lgc','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (115,'129','WBSA','Windows,Linux,MacOS','WBSA not only focuses on CpG methylation, but also allows CHG and CHH analysis. BWA is incorporated as its mapping software. WBSA can be applied to DNA methylation researches for animals and plants and it provides advanced analysis for both WGBS and RRBS. It can also identify differently methylated regions (DMRs) in different strings. WBSA includes six modules: Home, WGBS, RRBS, DMR, Documents and Downloads, and provides the executable package for downloads and local installation.','Web Service for Bisulfite Sequencing Data Analysis','WBSA不仅关注CpG甲基化，还允许CHG和CHH分析。BWA被合并为其绘图软件。WBSA可应用于动物和植物的DNA甲基化研究，并为WGBs和RRBs提供先进的分析方法。它还可以识别不同字符串中的不同甲基化区域（DMR）。WBSA包括Home、WGBS、RRBS、DMR、Documents和Downloads六个模块，并提供可执行包供下载和本地安装。','用于亚硫酸氢盐测序数据分析的Web服务','https://ngdc.cncb.ac.cn/biocode/tool/BT000010','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (116,'130','ISVASE','Linux','ISVASE is a tool for specifically identifying sequence variants associated with splicing events (SVASE) by using RNA-seq data. ','identifying sequence variants associated with splicing events','ISVASE是一种通过使用RNA-seq数据来特异性识别与剪接事件相关的序列变异（SVASE）的工具。','序列变异与关联剪切事件识别','https://ngdc.cncb.ac.cn/biocode/tool/BT004208','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (117,'131','BS-RNA','Linux','BS-RNA supports both paired-end and single-end sequencing short reads from a directional bisulfite library. Evaluation results of the rates of uniquely mapped reads, rates of correctly mapped reads, and running time for simulated data and actual data indicate that BS-RNA can provide fast and accurate mapping of RNA bisulfite sequencing reads. Comparison between annotated cytosine methylation used BS-RNA and published research also shows that BS-RNA is an effective annotation tool for RNA bisulfite sequencing data.','An efficient mapping and annotation tool for RNA Bisulfite Sequencing data','BS-RNA支持来自定向亚硫酸氢盐文库的成对末端和单端测序短读数。对模拟数据和实际数据的唯一映射读数率、正确映射读数率和运行时间的评估结果表明，BS-RNA可以提供快速准确的RNA亚硫酸氢盐测序读数图。使用BS-RNA的注释的胞嘧啶甲基化与已发表的研究的比较也表明BS-RNA是RNA亚硫酸氢盐测序数据的有效注释工具。','RNA亚硫酸氢盐测序数据分析','https://ngdc.cncb.ac.cn/biocode/tool/BT000009','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (118,'134','PGAP','Linux','PGAP is a pan-genomes analysis pipeline developed with Perl. It could perform five analytic functions with only one command, including cluster analysis of functional genes, pan-genome profile analysis, genetic variation analysis of functional genes, species evolution analysis and function enrichment analysis of gene clusters.','Pan-Genome Analysis Pipeline','PGAP是使用Perl开发的泛基因组分析流水线。该软件只需一个命令就可以完成功能基因的聚类分析、全基因组图谱分析、功能基因的遗传变异分析、物种进化分析和基因簇的功能富集分析。','泛基因组分析流程','https://ngdc.cncb.ac.cn/biocode/tool/BT000005','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (119,'137','VirusMuT','Windows,Linux','VirusMuT was developed to estimate mutation rate and TMRCA for virus ','estimating mutation rate and TMRCA for virus','VirusMut用于预估病毒的突变率和TMRCA','估计病毒的突变率和TMRCA','http://chenlab.big.ac.cn/software/software.html','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (120,'138','STRsensor','Linux','STRsensor (v1.2.0) is a method that can achieve high performance in both whole genome sequencing (WGS) data and multiplex deep sequencing data in STR allele-typing. The benchmark shows that STRsensor can obtain 99.64% detection ratio and 99.9% accuracy in 687 multiplex deep sequencing samples, while 100% detection ratio and 99.37% accuracy in a simulated 30 low-coverage WGS data.','Short Tandem Repeats (STR) Detection','StrSensor（V1.2.0）是一种可以在STR等位基因分型中的全基因组测序（WGS）数据和多重深度测序数据中实现高性能的方法。基准测试表明，StrSensor在687个多重深度测序样本中可以获得99.64%的检测率和99.9%的准确率，而在模拟的30个低覆盖率WGS数据中可以获得100%的检测率和99.37%的准确率。','短串联重复序列检测','https://ngdc.cncb.ac.cn/biocode/tool/BT007090','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (121,'141','scCapsNet','Windows,Linux,MacOS','Here we propose an interpretable deep-learning architecture using capsule networks(called scCapsNet). A capsule structure (a neuron vector representing a set of properties of a specific object) captures hierarchical relations. By utilizing competitive single-cell-type recognition, the scCapsNet model is able to perform feature selection to identify groups of genes encoding different subcellular types. The RNA expression signatures, which enable subcellular-type recognition, are effectively integrated into the parameter matrices of scCapsNet. ','An interpretable deep-learning architecture of capsule networks for identifying cell-type gene expression programs from single-cell RNA-sequencing data','我们提出了一种使用胶囊网络（称为SCCAPSNet）的可解释深度学习架构。胶囊结构（表示特定对象的一组属性的神经元向量）捕获层次关系。通过利用竞争性单细胞类型识别，SCCAPSNET模型能够执行特征选择以识别编码不同亚细胞类型的基因组。能够进行亚细胞类型识别的RNA表达信号被有效地整合到SCCAPSNET的参数矩阵中。','识别细胞类型基因表达程序的胶囊网络的可解释深度学习架构','https://ngdc.cncb.ac.cn/biocode/tool/BT007156','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (122,'142','MultiCapsNet','Windows,Linux,MacOS','MultiCapsNet is a deep learning model built on CapsNet and scCapsNet, which possesses the merits of both easier data integration and higher model interpretability. By performing the labeled variant call dataset analysis, MultiCapsNet shows a similar performance with the previous feed forward neural network model with much less parameters. Furthermore, MultiCapsNet provides importance scores for each data source directly without an extra importance determination step required by the previous model.','An interpretable deep learning classifier integrate data from multiple sources','MulticapsNet是基于CapsNet和ScCapsNet构建的深度学习模型，具有数据集成简单、模型可解释性高等优点。通过执行标记变量调用数据集分析，MulticapsNet显示出与先前的前馈神经网络模型相似的性能，但参数要少得多。此外，MultiCapsNet直接为每个数据源提供重要性分数，而不需要先前模型所需的额外重要性确定步骤。','可解释深度学习分类器集成来自多个来源的数据','https://ngdc.cncb.ac.cn/biocode/tool/BT007158','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (123,'144','Phylogenetic tree','Linux','The pipeline for the phylogenetic analyses for klebsiella pneumoniae based on whole genome sequencing data.','Phylogenetic tree for klebsiella pneumoniae','基于全基因组测序数据的肺炎克雷伯菌系统发育分析流程。','肺炎克雷伯菌系统发育进化树','https://ngdc.cncb.ac.cn/biocode/tool/BT007276','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (124,'145','TSomVar','Linux','Somatic variants act as key players during cancer occurrence and development, thus an accurate and robust method to identify them is the foundation in the cutting-edge cancer genome research. However, due to low accessibility and high individual-/sample-specificity of the somatic variants in tumor samples, the detection is, to date, still crammed with challenges, particularly when there are no paired normal samples as control. To solve this burning issue, we developed a tumor-only somatic and germline variant identification method (TSomVar), using the random forest algorithm established on sample-specific variant datasets derived from genotype imputation, reads-mapping level annotation and functional annotation.','a tumor-only somatic variant detection method','体细胞变异在癌症的发生和发展过程中起着关键作用，因此准确、可靠地鉴定体细胞变异是前沿癌症基因组研究的基础。然而，由于肿瘤样本中体细胞变异体的低可及性和高个体/样本特异性，迄今为止，检测仍然充满挑战，特别是当没有配对的正常样本作为对照时。为了解决这个棘手的问题，我们开发了一种仅有肿瘤的体细胞和种系变异识别方法（TSOMVAR），该方法使用随机森林算法，建立在来自基因型估算、Reads-Mapping水平注释和功能注释的样本特异性变异数据集上。','一种仅有肿瘤的体细胞变异检测方法','https://ngdc.cncb.ac.cn/biocode/tool/BT007299','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (125,'146','McAN','Linux','McAN is a tool for haplotype network construction for sequences. The web service of McAN will be found here https://ngdc.cncb.ac.cn/ncov/online/tool/haplotype. The haplotype network of SARS-CoV-2 constructed by McAN will be found here https://ngdc.cncb.ac.cn/ncov/haplotype/','a fast minimum-cost arborescence based haplotype network construction algorithm','MCAN是构建序列单倍型网络的工具。在这里可以找到MCAN的网络服务https：//ngdc.cncb.ac.cn/ncov/online/tool/haplotype.在这里可以找到由MCAN构建的SARS-CoV-2的单倍型网络https：//ngdc.cncb.ac.cn/ncov/haplotype/','基于树状图的快速最小代价单体型网络构造算法','https://ngdc.cncb.ac.cn/biocode/tool/BT007301','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (126,'148','fastQTLmapping','Linux','FastQTLmapping is a computationally efficient, exact, and generic solver for exhaustive multiple regression analysis involving extraordinarily large numbers of dependent and explanatory variables with covariates, which is particularly helpful in QTL-like analysis. FastQTLmapping can afford omics data containing tens of thousands of individuals and billions of molecular loci.','fast molQTL mapping tools','FastQTLMapping是一种计算高效、精确和通用的求解器，用于涉及大量因变量和解释变量以及协变量的穷举多元回归分析，这在类QTL分析中特别有用。FastQTLmapping可以提供包含数万个个体和数十亿个分子位点的组学数据。','快速MolQTL比对工具','https://ngdc.cncb.ac.cn/biocode/tool/BT007346','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (127,'149','MOWAS','Linux','MOWAS can exhaustively test potential epistasis between trillions of SNP pairs based on linear regression,Y~β1SNP1+β2SNP2+β3SNP1SNP2+covariates, where Y represents case-control status but is treated as a continuous variable to reduce logistic regression computational burden, and SNPs were coded as minor allele number plus one.  We test whether ß1 is significantly different from zero.  MOWAS was run in a heterogeneous supercomputing environment. ','Multi-Omics Wide Association Study','基于线性回归，MOWAS可以穷尽地检验数万亿个SNP对之间的潜在上位性，Y~β1SNP1+β2SNP2+β3SNP1SNP2+协变量，其中Y代表病例对照状态，但被视为连续变量以减少逻辑回归计算负担，SNP被编码为次要等位基因数加1。我们测试ß1是否与零有显著差异。MOWAS在异构超级计算环境中运行。','多组学关联分析','https://ngdc.cncb.ac.cn/biocode/tool/BT007349','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (128,'150','C-GWAS','Linux','C-GWAS is a powerful method for combining GWAS summary statistics of multiple potentially related traits and detect SNPs with multi-trait effects.C-GWAS begins with GWASs summary as inputs and outputs a single vector of combined p-values testing if the null is deviated. For each SNP, the null is the absence of any effect on all traits, and the alternative is that its effect deviates from 0 for at least one trait. C-GWAS integrates two different statistical methods with complementary statistical features to ensure the optimal power under various and complex scenarios while keeping a stable study-wide type-I error rate. The first method is called iterative effect based inverse covariance weighting (i-EbICoW) and the second method is called truncated Wald test (TWT).C-GWAS controls the study-wide type-I error rate in an empirical manner via simulations and adjust the resultant p-values in such a way that they are directly comparable with those from traditional GWAS of a single trait.','a method for combining GWAS summary statistics of multiple potentially correlated traits','C-GWAS是一种结合多个潜在相关性状的GWAS汇总统计和检测具有多性状效应的SNPs的强大方法。C-GWAS以GWASS汇总作为输入，如果零值偏离，则输出组合p值的单个向量。对于每个SNP，无效是指对所有性状没有任何影响，另一种情况是其影响至少对一个性状偏离0。C-GWAS集成了两种具有互补统计特征的不同统计方法，以确保在各种复杂场景下的最佳功效，同时保持稳定的研究范围内的I型错误率。第一种方法称为基于迭代效应的逆协方差加权（I-EBICOW），第二种方法称为截断Wald检验（TWT）。C-GWAS通过模拟以经验方式控制研究范围内的I型错误率，并调整得到的p值，使其直接与单个性状的传统GWAS的p值进行比较。','C-GWAS','https://github.com/Fun-Gene/CGWAS','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (129,'151','GSA_STAT_reads_classification','Linux','This package is the pipeline using STAT tools for GSA database to analyze the raw sequence of short reads. We build the local K-mer database which uses Refseq(2023-03 217) and Taxonomy (20230315) . We also revise the script to show the real statistics percentage of "unidentified reads", input of .fastq.gz format file, and optimized the steps of matching species information from hits information.','GSA_STAT_reads_classification','这个包是使用Stat Tools for GSA数据库来分析短读取的原始序列的流程。我们使用RefSeq（2023-03 217）和Taxonomy（20230315）建立了本地K-mer数据库。我们还修改了脚本以显示“未识别读取”的真实统计百分比，输入.fastq.GZ格式文件，并优化了从HITS信息匹配物种信息的步骤。','GSA_STAT_读取_分类','https://ngdc.cncb.ac.cn/biocode/tool/BT007358','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (130,'152','GMQN','Windows,Linux,MacOS','The Illumina HumanMethylation BeadChip is one of the most cost-effective methods to quantify DNA methylation levels at single-base resolution across the human genome, which makes it a routine platform for epigenome-wide association studies. It has accumulated tens of thousands of DNA methylation array samples in public databases, providing great support for data integration and further analysis. However, the majority of public DNA methylation data are deposited as processed data without background probes which are widely used in data normalization. Here, we present Gaussian mixture quantile normalization (GMQN), a reference based method for correcting batch effects as well as probe bias in the HumanMethylation BeadChip. Availability and implementation: https://github.com/MengweiLi-project/gmqn.','A Reference-Based Method for Correcting Batch Effects and Probe Bias in HumanMethylation BeadChip','Illumina人类甲基化微珠芯片是在人类基因组中以单碱基分辨率量化DNA甲基化水平的最具成本效益的方法之一，这使其成为表观基因组关联研究的常规平台。在公共数据库中积累了数以万计的DNA甲基化阵列样本，为数据整合和进一步分析提供了极大的支持。然而，大多数公开的DNA甲基化数据是作为处理过的数据存放的，而没有广泛用于数据标准化的背景探针。在这里，我们提出了高斯混合分位数标准化（GMQN），这是一种基于参考的方法，用于校正人甲基化微珠芯片中的批次效应和探针偏差。可用性和实施：https：//github.com/MengweiLi-project/gmqn.。','一种基于参考的方法校正人甲基化微珠芯片中的批次效应和探针偏差','https://ngdc.cncb.ac.cn/biocode/tool/BT007369','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (131,'153','scCopyATAC','Linux','scCopyATAC, a computational method to detect CNVs and delineat clonal substructure from single cell ATAC sequencing data without normal reference. scCopyATAC has two main steps: strongscCopyATAC-PRE/strong, strongscCopyATAC-CNV/strong. scCopyATAC-PRE preprocesses single cell ATAC sequencing data and computes the raw CNV signals matrix. And do clustering for single cell by chromotin accessibility, which is a paperation for next step detecting diploid baseline. Then scCopyATAC-CNV detect potential diploid baseline by gaussian mixture model and redefine raw CNV signals get the final CNV value. scCopyATAC using stand cellranger output as input.','A computational method for delineating copy number and clonal substructure from tumor single-cell ATAC-seq data without normal reference','SCCOPYATAC，一种在没有正常参考的情况下，从单细胞ATAC测序数据中检测CNVs和描绘克隆亚结构的计算方法。SCCOPYATAC有两个主要步骤：SCCOPYATAC-PRE和SCCOPYATAC-CNV。SCCOPYATAC-PRE预处理单细胞ATAC测序数据并计算原始CNV信号矩阵。并利用染色质可及性对单个细胞进行聚类，为下一步检测二倍体基线打下基础。然后，SCCOPYATAC-CNV通过高斯混合模型检测潜在的二倍体基线，并对原始CNV信号进行重新定义，得到最终的CNV值。SCCOPYATAC使用Stand CellRanger输出作为输入。','一种从肿瘤单细胞ATAC-Seq数据中描绘拷贝数和克隆亚结构的计算方法','https://ngdc.cncb.ac.cn/biocode/tool/BT007370','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (132,'155','HiRisk-Detector','Windows,Linux,MacOS','HiRisk-Detector is a tool for early detecting high-risk variants of SARS-CoV-2.','Machine learning detection of SARS-CoV-2 high-risk variants','HiRisk-Detector是一种早期检测SARS-CoV-2高风险变异体的工具。','SARS-CoV-2高危变异株的机器学习检测','https://ngdc.cncb.ac.cn/biocode/tool/BT007386','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (133,'156','piplineForQC','Linux','A toolkit for short reads filtering','A toolkit for short reads filtering','短读过滤工具包','短Reads过滤工具包','https://ngdc.cncb.ac.cn/biocode/tool/BT007415','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (134,'157','inClust','Linux','Single-cell transcriptomics data come from different donors, locations, or stimulated conditions and are influenced by these factors. Computational models must integrate this influence to decompose complex data and enable downstream applications. Most models only focus on data integration, and a few data decomposition methods are limited to specific tasks and not suitable for all situations. Here, we introduce inClust (integrated clustering), a flexible deep generative framework for data integration and decomposition that can handle various tasks in supervised, semi-supervised, or unsupervised mode.','integrated clustering','单细胞转录组学数据来自不同的供体、位置或刺激条件，并受到这些因素的影响。计算模型必须整合这种影响，以分解复杂的数据并支持下游应用。大多数模型只关注数据集成，少数数据分解方法仅限于特定任务，并不适用于所有情况。在这里，我们介绍了INCLUST（集成聚类），这是一个用于数据集成和分解的灵活的深度生成框架，可以在监督、半监督或无监督模式下处理各种任务。','集成聚类','https://ngdc.cncb.ac.cn/biocode/tool/BT007454','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (135,'158','T2T-YAO WES','Linux','The analysis pipeline using T2T-YAO as the reference genome.','T2T-YAO WES analysis pipeline','使用T2T-Yao作为参考基因组的分析流水线。','使用T2T-Yao作为参考基因组的分析流程','https://ngdc.cncb.ac.cn/biocode/tool/BT007544','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (136,'159','VISTA','Windows,Linux,MacOS','VISTA VIrus Sequence-based Taxonomy Assignment is a fast and easy-to-use tool for analysing pairwise distance distribution and taxonomic classification for viral genomes within virus families. It takes a FASTA file of DNA sequences as input and calculates pairwise distances between input virus sequences and existing genomes within the family. For each input genome, you will be presented with a list of pairwise distances, from the lowest to the highest. VISTA will compare the minimum distance with demarcation thresholds of the relevant virus family to determine the taxonomic assignment of the input virus.','Virus Sequence-based Taxonomy Assignment','Vista Virus Sequence-Based Taxonomy Assignment是一种快速易用的工具，用于分析病毒家族内病毒基因组的成对距离分布和分类学分类。它将DNA序列的FASTA文件作为输入，并计算输入病毒序列和家族内现有基因组之间的成对距离。对于每个输入基因组，您将看到一个从最低到最高的成对距离列表。Vista将最小距离与相关病毒家族的分界阈值进行比较，以确定输入病毒的分类分配。','基于病毒序列的分类','https://ngdc.cncb.ac.cn/vista/','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (137,'160','CIRI3','Linux','CIRI3 is a comprehensive analysis package for the detection and quantification of circRNAs in RNA-Seq data, while providing differential expression analysis of circRNAs at multiple levels.','circular RNA identifier','CIRI3是一个全面的分析软件包，用于检测和定量RNA-seq数据中的circRNAs，同时提供多个水平的circRNAs差异表达分析。','环形RNA鉴定','https://ngdc.cncb.ac.cn/biocode/tool/BT007594','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (138,'161','SCSES','Linux','Alternative splicing AS significantly contributes to cellular transcriptomic heterogeneity, and single-cell RNA-Seq is commonly employed to delineate this heterogeneity. However, due to high dropout rates, inevitable noise, and limited coverage, accurately characterizing splicing changes at single-cell level remains challenging. To address this, we present a computational framework called SCSES Single-Cell Splicing EStimation to improve the AS profiles, which imputes the junction count matrix and fills in missing AS alternations by sharing information across similar cells or events with data diffusion.','Single Cell Splicing Estimation','SCSES软件采用跨细胞和跨剪接事件的信息扩散算法，整合三种推断策略，实现了单细胞水平剪接图谱的准确推断。','单细胞可变剪接识别与定量分析','https://ngdc.cncb.ac.cn/biocode/tool/BT007615','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (139,'162','DET','Windows,Linux,MacOS','Extract divergently paired gene pairs DPGs from gff3 files and filter them based on the transcription direction and distance of genes.','DPG_Extraction_Tool','从GFF3文件中提取差异配对的基因对DPG，并根据基因的转录方向和距离对其进行筛选。','DPG提取工具','https://ngdc.cncb.ac.cn/biocode/tool/BT007623','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (140,'163','HaploNet-PathoLin','Linux','Create classification rules for pathogenic lineages and divide lineages into pathogenic sequences.','HaploNet-PathoLin','创建致病谱系的分类规则，并将谱系划分为致病序列。','致病谱系分类','https://ngdc.cncb.ac.cn/biocode/tool/BT007695','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (141,'164','CTAP','Linux','Comparative transcriptomic analysis pipeline for macrophages infected with avirulent and virulent Mycobacterium tuberculosis','Comparative transcriptomic analysis pipeline','无毒力和有毒力结核分枝杆菌感染巨噬细胞的比较转录组分析','比较转录组分析','https://ngdc.cncb.ac.cn/biocode/tool/BT007697','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (142,'165','HBMRS','Windows,Linux','This pipleine was developed to predict the risk score of healthy blood genetic and microbiome data.','Healthy Blood Microbiome Risk Score','开发该l流程是为了预测健康血液遗传和微生物组数据的风险评分。','健康血液微生物组风险评分','https://ngdc.cncb.ac.cn/biocode/tool/BT007702','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (143,'166','PGAP2','Windows,Linux,MacOS','a comprehensive pan-genome analysis pipeline for prokaryotic genomes','Pan-genome analysis pipeline 2','原核生物基因组的综合全基因组分析流水线','泛基因组分析流水线','https://ngdc.cncb.ac.cn/biocode/tool/BT007758','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (144,'167','CCLHunter','Windows,Linux,MacOS','Cancer cell lines are essential in cancer research, yet accurate authentication of these cell lines can be challenging, particularly for consanguineous cell lines with close genetic similarities. We introduce a new Cancer Cell Line Hunter CCLHunter method to tackle this challenge. This approach utilizes the information of single nucleotide polymorphisms, expression profiles, and kindred topology to authenticate 1,389 human cancer cell lines accurately.','Cancer cell line hunter','癌细胞系在癌症研究中是必不可少的，但这些细胞系的准确鉴定可能具有挑战性，特别是对于具有密切遗传相似性的近亲细胞系。我们介绍了一种新的癌细胞系Hunter CCL-Hunter方法来应对这一挑战。该方法利用单核苷酸多态性、表达谱和家族拓扑结构等信息，准确鉴定了1，389个人类癌细胞系。','肿瘤细胞系鉴定工具','https://ngdc.cncb.ac.cn/cclhunter/home','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (145,'168','RefRGim','Linux','RefRGim is an intelligent genotype imputation reference reconstruction method with convolutional neural networks based on genetic similarity of individuals from input data and current references. RefRGim has been pre-trained with single nucleotide polymorphism data of individuals in 1000 Genomes Project, which are from 26 different populations across the world. A population was delimited as a haplotype group.','RefRGim','ReFRGIM是一种使用卷积神经网络的智能基因型填补参考重建方法，该方法基于输入数据和当前参考中个体的遗传相似性。REFRGIM已经用1000基因组计划中的个体的单核苷酸多态性数据进行了预训练，这些数据来自世界各地的26个不同人群。一个群体被界定为一个单倍型组。','RefRGim','https://ngdc.cncb.ac.cn/biocode/tool/BT007766','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (146,'169','chip-seq_pipeline','Linux','Histone modification signal analysis pipeline','Histone modification signal analysis pipeline','组蛋白修饰信号分析流水线','组蛋白修饰信号分析','https://ngdc.cncb.ac.cn/biocode/tool/BT007776','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (147,'170','scm6A-processing','Linux','We employ RNA multiplex-labeling methods and SMART witching mechanism at the 5 end of RNA template technology to improve the method to profile the m6A genome widely from single cells, named single-cell m6A-seq scm6A-seq. scm6A-seq sequence the gene expression level with m6A information, making a robust tool to classify cell types more accurately. The code is used for pre-processing scm6A-seq data and used in the linux system.','scm6A processing pipeline','我们利用RNA多重标记方法和RNA模板5端的智能转换机制，改进了从单细胞中广泛分析m6A基因组的方法，命名为单细胞m6A-Seq SCm6A-Seq。SCM6A-SEQ序列基因表达水平与M6A信息，使强大的工具更准确地分类细胞类型。该代码用于对SCM6A-SEQ数据进行预处理，并在Linux系统中使用。','scm6A-processing','https://ngdc.cncb.ac.cn/biocode/tool/BT007790','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (148,'171','FIPRESCI_Tools','Linux','FIPRESCI_Tools, a computational pipeline for processing sequencing data generated from FIPRESCI scRNA-seq technology. This pipeline includes mapping, gene expression quantification, quality control, normalization, clustering, annotation and visualization.','Data analysis pipeline tools of FIPRESCI','FIPRESCI_工具，用于处理由FIPRESCI scRNA-seq技术生成的测序数据的计算流水线。该流程包括基因定位、基因表达定量、质量控制、标准化、聚类、注释和可视化。','FIPRESCI的数据分析流水线工具','https://ngdc.cncb.ac.cn/biocode/tool/BT007793','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (149,'172','ME Pipeline','Linux','ME pipeline are built for analysis of mouse embryo organ genesis multi-omics scRNA and scRNA-seq. This pipeline includes processing sequencing fastq file, mapping and quantifiying gene expression and chromatin accessibility. And downstream analysis: cell type annotation, trajectory analysis and integration with mouse embryo spatial transcriptome.','Mouse Embryo scRNA-seq scATAC-seq analysis Pipeline','建立了用于分析小鼠胚胎器官发生多组学scRNA和scRNA-seq的ME流水线。该流水线包括处理测序FASTQ文件，绘制和定量基因表达和染色质可及性。以及下游分析：细胞类型注释、轨迹分析以及与小鼠胚胎空间转录组的整合。','鼠胚胎scRNA-Seq SCATAC-Seq分析流水线','https://ngdc.cncb.ac.cn/biocode/tool/BT007800','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (150,'173','OpenLB-API','Windows,Linux,MacOS','an open API system for biomedical literature abstracts.','OpenLB-API','生物医学文献摘要的开放式API系统。','生物医学文献摘要API','https://ngdc.cncb.ac.cn/openlb/doc-api','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (151,'174','fqPack','Linux','Compression tool for raw FASTQ sequencing data','fastq pack','原始FASTQ测序数据的压缩工具','序列压缩工具','https://ngdc.cncb.ac.cn/biocode/tool/BT007810','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (152,'175','StreamCompute','Linux','Stream computing tool for public available genome sequencing data.','Stream Compute','公开基因组测序数据的流计算工具。','流计算工具','https://ngdc.cncb.ac.cn/biocode/tool/BT007811','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (153,'176','GENtools-bulk','Windows,Linux,MacOS','GEN offers online services for differential expression analysis, weighted gene co-expression network analysis WGCNA, functional enrichment analysis and gene regulatory network inference. To start ‘Bulk RNA-seq Data Analysis’, users should select bulk RNA-seq dataset of interest first.','Bulk RNA-seq Data Analysis','GEN为差异表达分析、加权基因共表达网络分析、WGCNA、功能富集分析和基因调控网络推断提供在线服务。要启动“批量RNA-seq数据分析”，用户应首先选择感兴趣的批量RNA-seq数据集。','Bulk RNA-Seq数据分析','https://ngdc.cncb.ac.cn/gen/online/tools/','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (154,'177','SARS-G2V','Linux','Identifying Mutations Based on the Genomic Sequence of SARS-CoV-2','Genome_to_variants_SARS-CoV-2','基于SARS-CoV-2基因组序列的突变鉴定','基于SARS-CoV-2基因组序列的突变鉴定','https://ngdc.cncb.ac.cn/biocode/tool/BT007884','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (155,'178','SARS-Anno','Linux','Variant annotation for SARS-CoV-2','Variant_annotation_SARS-CoV-2','SARS-CoV-2的变异注释','新冠病毒变异注释','https://ngdc.cncb.ac.cn/biocode/tool/BT007885','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (156,'179','Monkeypox-G2V','Linux','Identifying Mutations Based on the Genomic Sequence of Monkeypox Virus','Monkeypox_Genome_Variants','基于猴痘病毒基因组序列的突变鉴定','基于猴痘病毒基因组序列的突变鉴定','https://ngdc.cncb.ac.cn/biocode/tool/BT007887','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (157,'180','Monkeypox-Anno','Linux','Variant annotation for Monkeypox Virus','Monkeypox Variants Annotation','猴痘病毒的变异注释','猴痘病毒变异注释','https://ngdc.cncb.ac.cn/biocode/tool/BT007888','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (158,'181','HaploThread','Windows,Linux,MacOS','HaploThread, a user-friendly GUI desktop software designed for haplotype network construction and visualization. HaploThread is written in C++ using the Qt library, integrating network visualization and multiple multi-threaded haplotype construction algorithms such as McAN and fastHaN includes MSN, MJN and TCS based on plugin mechanisms. It offers a straightforward approach to constructing and visualizing haplotype networks from large sample sets, and to extending functionality with plugins, facilitating the analysis of genetic variations and their evolutionary relationships. HaploThread is an open-source software released under the GNU General Public License GPL.','A Scalable Integrated Desktop Platform for Constructing and Visualizing Haplotype Networks for Large-sample Sequences','HaploThread是一款用户友好的GUI桌面软件，专为单倍型网络构建和可视化而设计。HaploThread是使用Qt库用C++编写的，集成了网络可视化和多个多线程单倍型构建算法，如MCAN和FASTHAN，包括基于插件机制的MSN、MJN和TCS。它提供了一种直接的方法来从大样本集中构建和可视化单倍型网络，并通过插件扩展功能，促进遗传变异及其进化关系的分析。HaploThread是在GNU通用公共许可证GPL下发布的开源软件。','大样本序列单倍型网络的可扩展集成桌面平台','https://ngdc.cncb.ac.cn/biocode/tool/BT007948','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (159,'182','MRAS','Windows,Linux,MacOS','MRAS Master Regulator analysis of Alternative Splicing is designed to identify the critical splicing factors whose altered expression drives the extensive splicing abnormalities, particularly in the biological scenario of lacking spliceosomal mutations or other known manipulations causing splicing disorders.','Master regulator analysis of splicing','选择性剪接的MRAS主调节分析旨在识别关键剪接因子，其改变的表达驱动广泛的剪接异常，特别是在缺乏剪接体突变或其他已知操作导致剪接紊乱的生物学场景中。','选择性剪接的关键调节因子识别软件','https://ngdc.cncb.ac.cn/biocode/tool/BT007960','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (160,'183','GOT','Linux','We applied GOT to accurately reconstruct the phylogenetic tree of mouse embryogenesis, identify key regulators in β-cell differentiation, and uncover immune evasion mechanisms in lung cancer progression. Overall, GOT provides an interpretable and unified solution for accurate vector field reconstruction from both longitudinal and snapshot single-cell data.','Graph-constrained Optimal Transport','GOT基于图约束最优传输理论与向量场学习方法，能够从单细胞数据中推断细胞演化向量场，识别分化路径与命运趋势。','单细胞轨迹推断分析软件','https://ngdc.cncb.ac.cn/biocode/tool/BT007981','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (161,'184','OmniExtract','Windows,Linux','an LLM-based automatic extraction tool specifically designed for information extraction tasks from literature and documents','OmniExtract','基于LLM的自动提取工具，专为从文献和文档中提取信息而设计','基于LLM的自动提取工具','https://ngdc.cncb.ac.cn/biocode/tool/BT007992','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (162,'185','scVar','Linux','scVar is a comprehensive workflow for the detection and functional characterization of single-nucleotide variants (SNVs) from 10X Genomic scRNA-seq data. (https://github.com/WeiZhaoLuck/scVar)','a comprehensive workflow for the detection and functional characterization of SNVs','SCVAR是一个全面的工作流程，用于从10x基因组scRNA-seq数据中检测和功能表征单核苷酸变体（SNVs）。（https：//github.com/WeiZhaoLuck/scVar）','从10x基因组scRNA-seq数据中检测和功能鉴定单核苷酸变异体（SNVs）的综合工作流程','https://ngdc.cncb.ac.cn/biocode/tool/BT008000','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (163,'186','Dingent','Windows,Linux,MacOS','A lightweight, user-friendly LLM Agent framework focused on simplifying data retrieval application development.','Dingent','一个轻量级、用户友好的LLM代理框架，专注于简化数据检索应用程序开发。','LLM代理框架','https://ngdc.cncb.ac.cn/biocode/tool/BT008001','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (164,'189','OpenLB API','Windows,Linux,MacOS','Provide publication retrieval API services','Open Library of Biosciences APIs','提供文献检索API服务','生命科学文献API','https://ngdc.cncb.ac.cn/openlb/doc-api','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (165,'190','BIG Search','Windows,Linux,MacOS','BIG Search provides one-step data search service for a variety of data resources for life science research. It features cross-domain search and facilitates users to gain access to a wide range of biological data, not only from CNCB resources but also partner resources throughout the world.','Biological big data cross-domain search platform','BIG Search为生命科学研究提供多种数据资源的一站式数据搜索服务。它以跨域搜索为特色，方便用户访问广泛的生物数据，不仅来自CNCB资源，还来自世界各地的合作伙伴资源。','生物大数据跨域检索','https://ngdc.cncb.ac.cn/search','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO online_tool(id,bt_id,name,platform,bt_en_description,bt_en_title,bt_zh_description,bt_zh_title,bt_url,http_method,is_visible,status,create_by,update_by) VALUES (166,'191','CNCBCloud','Windows,Linux,MacOS','National Bioinformatics Cloud is dedicated to serving the field of bioinformatics, focusing on bioinformatics analysis scenarios to help professionals achieve repeatable analysis pipelines, reproducible research results, traceable operations, and sustainable knowledge accumulation and sharing.','National Bioinformatics Cloud','国家生物信息云致力于服务生物信息学领域，旨在通过聚焦于生物信息分析的应用场景，协助专业人员实现分析流程的可重复性、研究结果的可复现性、操作过程的可追溯性以及知识的可沉淀和传播。','国家生物信息云平台','https://cloud.cncb.ac.cn/','GET',TRUE,'ENABLED','SYSTEM','SYSTEM');
