INSERT INTO publication_database (publication_id,database_id,resource_accession,relation_kind,verification_status,evidence_url) VALUES (3,22,'PMID:24810581','CATALOG_ENTRY','OBSERVED','https://ngdc.cncb.ac.cn/icg/api/json/publication/24810581');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (122,'ampsphere','AMPSphere','https://ampsphere.big-data-biology.org/','GET','Just as the ecosphere is the worldwide sum of all ecosystems, the AMPsphere comprises the complexity of prokaryotic AMPs assembled in one dataset. To date, we analyzed the 86k high-quality genomes in proGenomes2, and over 63k metagenomes from ENA, NCBI and JGI. After redundancy removal, we produced a collection of AMPs from the global microbiome, containing 863,498 distinct sequences, clustered into 10,715 AMP families with at least 7 sequences each.','AMPsphere comprises the complexity of prokaryotic AMPs, combining publicly available metagenomes and high-quality isolated microbial genomes.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (123,'ANA','THANATOS','http://thanatos.biocuckoo.org/','GET','Cell death especially Programmed cell-death (or PCD) is critical for development and health of multicellular organisms. Previously, apoptosis is identified to be the primary mechanism while cells are eliminated physiologically in metazoan organisms or plants (Kerr et al., 1972). Recently, in contrast to traditionally consideration as a simple way to die, necrosis has emerged as an alternate form of programmed cell death (Proskuryakov et al., 2003). Furthermore, besides its functions as a survival strategy under stress, autophagy was considered to be another programmed cell death (Tsujimoto and Shimizu et al., 2005). During the last several decades, numerous studies were contributed to characterize these biological processes, especially apoptosis, which was previously considerd to be an anti-cancer mechanism (Hickman et al., 1992). Recent studies suggested that necrosis and autophagy might also be implicated in tumor supression (Proskuryakov et al., 2003; Maycotte and Thorburnet al., 2011), while defect of these cell death processes usually lead to cancer (Hickman et al., 1992; Edinger and Thompsonet al., 2003). From the literatures in PubMed, we have curated the experimentally identified proteins which regulate apoptosis, necrosis and/or autophagy (THANATOS) from S. cerevisiae, C. elegans, D. melanogaster, M. musculus , R. norvegicus, D. rerio, A. thaliana, and H. sapiens. Furthermore, ortholog searches were performed in 164 eukaryotes. Then the integrated and searchable database THANATOS (THe Autophagy, Necrosis, ApopTosis OrchestratorS) was established. Currently, the THANATOS database was updated on May 07, 2017, containing 191,543 unique protein entries. The database will be updated routinely as new thanatos proteins are reported.','THe Autophagy, Necrosis, ApopTosis OrchestratorS',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (124,'Animal-SNPAtlas','Animal-SNPAtlas','http://gong_lab.hzau.edu.cn/Animal_SNPAtlas/','GET',NULL,'Animal-SNPAtlas: a comprehensive SNP database for multiple animals.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (125,'animalAPAdb','animalAPAdb','http://gong_lab.hzau.edu.cn/Animal-APAdb/','GET','A comprehensive animal alternative polyadenylation database','A comprehensive animal alternative polyadenylation database',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (126,'animaleRNAdb','animaleRNAdb','http://gong_lab.hzau.edu.cn/Animal-eRNAdb/','GET','A comprehensive animal enhancer RNA database','A comprehensive animal enhancer RNA database',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (127,'animaltfdb','AnimalTFDB','http://bioinfo.life.hust.edu.cn/AnimalTFDB4/','GET','AnimalTFDB is a comprehensive database including classification and annotation of genome-wide transcription factors (TFs) and transcription cofactors in 183 animal genomes. In AnimalTFDB v4.0, there are total 270k TFs which are further classified into 73 families and six categories based on their DNA-binding domain (DBD). Meanwhile, there are also 150k cofactors classified into 82 families and six categories.','Animal Transcription Factor Database',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (128,'bbcancer','BBCancer','http://bbcancer.renlab.org/','GET','BBCancer is a web-accessible and comprehensive open resource for providing the expression landscape of six type of RNAs, including messenger RNAs(mRNAs), Long non-coding RNAs(lncRNAs), microRNAs(miRNAs), circular RNAs(circRNAs), tRNA derived fragments(tRFRNAs) and Piwi-interacting RNAs(piRNAs) in 7184 samples including 5040 blood samples such as extracellular vesicles (EVs) and circulating tumor cells (CTCs) from normal persons or cancer patients of 15 cancer types.','BBCancer: an expression atlas of blood-based biomarkers in the early diagnosis of cancers',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (129,'cancersea','CancerSEA','http://biocc.hrbmu.edu.cn/CancerSEA/','GET','ScRNA-seq provides an unprecedented opportunity to explore the functional heterogeneity of cancer cells. CancerSEA is the first dedicated database that aims to comprehensively decode distinct functional states of cancer cells at single-cell resolution.','CancerSEA: a cancer single-cell state atlas',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (130,'cellmarker','CellMarker','http://xteam.xbio.top/CellMarker/','GET','One of the most fundamental questions in biology is which types of cells form different tissues and organs in a functionally coordinated fashion. Larger-scale single cell sequencing and biology experiment studies are now rapidly opening up new ways to track this question by revealing substantial cell markers for distinguishing different cell types in tissues. Here, we developed the CellMarker databases, aiming to provide a comprehensive and accurate resource of cell markers for various cell types in tissues of human and mouse.','CellMarker: a manually curated resource of cell markers in human and mouse.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (131,'cgdb','CGDB','http://cgdb.biocuckoo.org/','GET','CGDB (Circadian Gene DataBase) is an online resource containing over 72,800 genes in more than 148 organisms that exhibit (or may exhibit) daily oscillation at the transcript level.','Circadian Gene Database',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (132,'CGGA','CGGA','http://cgga.org.cn','GET','a user-friendly web application for data storage and analysis to explore brain tumors datasets over 2,000 samples from Chinese cohorts','Chinese Glioma Genome Atlas',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (133,'circAltas','circAltas','http://circaltas.biols.ac.cn','GET','An integrated resource of circRNAs in vertebrates.','circAtlas 2.0',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (134,'consrm','ConsRM','http://180.208.58.19/conservation/index.html','GET','A novel scoring framework, ConsRM, was devised to quantitatively measure the degree of conservation of individual m6A RNA methylation sites. ConsRM integrates positional mapping, tissue-specific mapping, support from multiple studies, sequence similarity, genome conservation and a positive-unlabeled learning model, which integrated 63 genomic features as well sequence features to trace epitranscriptome layer conservation.','Collection and large-scale prediction of the evolutionarily conserved RNA methylation sites, with implications for the functional epitranscriptome.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (135,'cplm','CPLM Database','https://cplm.biocuckoo.cn','GET','A comprehensive resource for Protein Lysine Modifications.','Compendium of Protein Lysine Modifications Database',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (136,'dbpaf','dbPAF','http://dbpaf.biocuckoo.org/','GET','The dbPAF (database of Phospho-sites in Animals and Fungi) is an online data resource specifically designed for protein phosphorylation in seven eukaryotic species, including H. sapiens, M. musculus, R. norvegicus, D. melanogaster, C. elegans, S. pombe and S. cerevisiae.','database of Phospho-sites in Animals and Fungi',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (137,'dbppt','dbPPT','http://dbppt.biocuckoo.org/','GET','As one of the most important and ubiquitous post-translational modifications (PTMs) in plants, the reversible phosphorylation catalyzed by protein kinases is involved in regulating a wide range of biological processes such as cellular metabolism, signal transduction and environmental response (Ranjeva et al., 1987; Mundy et al., 2002; Kusakina et al., 2012). Recently with the development of phosphopeptide enrichment techniques and high-throughput mass spectrometry (HTP-MS) technology, large scale phosphoproteomics data in plants have been emerged at a quick pace, stimulating the creation of multiple phosphorylation databases to store and organize them. However, a more comprehensive phosphorylation database of plants is still necessary and useful. In this work, we develop a database of dbPPT 1.0 (database of Phospho-sites in PlanTs), which contains large-scale phosphorylation sites (p-sites) based on mass spectrometry across 20 plant species. Most of the datasets in dbPPT 1.0 were manually curated from literature published before July, 2014. Moreover, we also integrated other phosphorylation resource into this database including PhosPhAt (Durek et al., 2010) and P3DB (Yao et al., 2014). Currently, dbPPT contains 82,175 p-sites in 31,012 proteins for 20 plant species.','database of Phospho-sites in PlanTs',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (138,'dbpsp','dbPSP','http://dbpsp.biocuckoo.cn/','GET','In prokaryotes, protein phosphorylation plays a critical role in regulating a broad spectrum of biological processes and occurs mainly on various amino acids, including serine (S), threonine (T), tyrosine (Y), arginine (R), aspartic acid (D), histidine (H) and cysteine (C) residues of protein substrates. Through literature curation and public database integration, here we reported an updated database of phosphorylation sites (p-sites) in prokaryotes (dbPSP 2.0) that contains 19,296 experimentally identified p-sites in 8,586 proteins from 200 prokaryotic organisms, which belong to 12 phyla of two kingdoms, bacteria and archaea. To carefully annotate these phosphoproteins and p-sites, we integrated the knowledge from 88 publicly available resources that covers 9 aspects, namely, taxonomy annotation, genome annotation, function annotation, transcriptional regulation, sequence and structure information, family and domain annotation, interaction, orthologous information and biological pathway. In contrast to version 1.0 (~30 MB), dbPSP 2.0 contains ~9 GB of data, with a 300-fold increased volume. We anticipate that dbPSP 2.0 can serve as a useful data resource for further investigating phosphorylation events in prokaryotes. dbPSP 2.0 is free for all users to access at: http://dbpsp.biocuckoo.cn.','database of Phosphorylation Sites in Prokaryotes',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (139,'deg','DEG','http://tubic.org/deg/','GET',NULL,'Database of Essential Genes',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (140,'directrmdb','directRMDB','http://www.rnamd.org/directRMDB/index.html','GET','The first ONT-based database of quantitative RNA modification profiles, DirectRMDB, which includes 16 types of modification and a total of 904,712 modification sites in 25 species identified from 39 independent studies. In addition to standard functions adopted by existing databases, such as gene annotations and post-transcriptional association analysis, we provide a fresh view of RNA modifications, which enables exploration of the epitranscriptome in an isoformspecific manner.','A ONT-based database of quantitative RNA modification profiles.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (141,'DiseaseEnhancer','DiseaseEnhancer','http://biocc.hrbmu.edu.cn/DiseaseEnhancer/','GET','Genetic alterations/variants of enhancers make an essential contribution to disease progression. And more than 3 million of enhancers generated by international consortiums indicated that disease-associated enhancers will open a brand new view of pathophysiology. DiseaseEnhancer provides a comprehensive map of manually curated disease-associated enhancers, which includes 1059 disease-associated enhancers in 167 human diseases, involving 896 unique enhancer-gene interactions. We also manually collected their dysregulated target genes and mechanistic-related information, such as the associated variant types (including single nucleotide variant, somatic mutation, indel and copy number alteration) and affected transcription factor bindings. Additional genome data were also integrated into DiseaseEnhancer to help characterize disease-associated enhancers.','DiseaseEnhancer: a resource of human disease-associated enhancer catalog.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (142,'DMS_AlphaMissense','DMS_AlphaMissense','https://idc.biosino.org/dms/dictionary/view/85','GET',NULL,'AlphaMissense achieves state-of-the-art missense pathogenicity predictions in clinical annotation, de novo disease variants, and experimental assay benchmarks without explicitly training on such data.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (143,'DMS_BV_BRC_bacteria','DMS_BV_BRC_bacteria','https://idc.biosino.org/dms/dictionary/view/92','GET',NULL,'The Bacterial and Viral Bioinformatics Resource Center (BV-BRC) is an information system designed to support research on bacterial and viral infectious diseases. BV-BRC combines two long-running BRCs: PATRIC, DMS_BV_BRC_bacteria is the bacterial system, and IRD/ViPR',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (144,'DMS_BV_BRC_viral','DMS_BV_BRC_viral','https://idc.biosino.org/dms/dictionary/view/93','GET',NULL,'The Bacterial and Viral Bioinformatics Resource Center (BV-BRC) is an information system designed to support research on bacterial and viral infectious diseases. BV-BRC combines two long-running BRCs, DMS_BV_BRC_viral is the viral system',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (145,'DMS_CEBIO','DMS_Chemical Entities of Biological Interest Ontology','https://idc.biosino.org/dms/dictionary/view/12','GET',NULL,'Chemical Entities of Biological Interest (ChEBI) is a freely available dictionary of molecular entities focused on ‘small’ chemical compounds. ',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (146,'DMS_ClinGen','DMS_ClinGen','https://idc.biosino.org/dms/dictionary/view/86','GET',NULL,'ClinGen is a National Institutes of Health (NIH)-funded resource dedicated to building a central resource that defines the clinical relevance of genes and variants for use in precision medicine and research.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (147,'DMS_Clinvar','DMS_ClinVar','https://idc.biosino.org/dms/dictionary/view/57','GET',NULL,'ClinVar aggregates information about genomic variation and its relationship to human health.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (148,'DMS_CMO','DMS_Clinical Measurement Ontology','https://idc.biosino.org/dms/dictionary/view/13','GET',NULL,'The Clinical Measurement Ontology is designed to be used to standardize morphological and physiological measurement records generated from clinical and model organism research and health programs.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (149,'DMS_COSMIC','DMS_COSMIC','https://idc.biosino.org/dms/dictionary/view/58','GET',NULL,'COSMIC, the Catalogue Of Somatic Mutations In Cancer, is the world''s largest and most comprehensive resource for exploring the impact of somatic mutations in human cancer.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (150,'DMS_DECIPHER','DMS_DECIPHER','https://idc.biosino.org/dms/dictionary/view/87','GET',NULL,'DECIPHER is used by the clinical community to share and compare phenotypic and genotypic data.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (151,'DMS_DiseaseOntology','DMS_DiseaseOntology','https://idc.biosino.org/dms/dictionary/view/49','GET',NULL,'The Disease Ontology has been developed as a standardized ontology for human disease with the purpose of providing the biomedical community with consistent, reusable and sustainable descriptions of human disease terms, phenotype characteristics and related medical vocabulary disease concepts through collaborative efforts of biomedical researchers, coordinated by the University of Maryland School of Medicine, Institute for Genome Sciences.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (152,'DMS_DoCM','DMS_DoCM','https://idc.biosino.org/dms/dictionary/view/84','GET',NULL,'DoCM is a curated repository that facilitates the aggregation of gene and variant information for variants with prognostic, diagnostic, predictive, or functional roles from these resources as well as from individually curated publications',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (153,'DMS_Drugbank','DMS_Drugbank','https://idc.biosino.org/dms/dictionary/view/41','GET',NULL,'a comprehensive, free-to-access, online database containing information on drugs and drug targets.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (154,'DMS_Drugtarget','DMS_Drugtarget','https://idc.biosino.org/dms/dictionary/view/25','GET',NULL,'Drug (i.e. chemical, pharmacological and pharmaceutical) data with comprehensive drug target (i.e. sequence, structure, and pathway) information.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (155,'DMS_Ecoli_gene','DMS_Ecoli_gene','https://idc.biosino.org/dms/dictionary/view/29','GET',NULL,'The EcoGene database provides a set of gene and protein sequences derived from the genome sequence of Escherichia coli K-12. ',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (156,'DMS_eLMSG','DMS_eLMSG','https://idc.biosinno.org/dms/dictionary/view/28','GET','The eLMSG database is intended to integrate microbial systematics, genomics and phenomics (polyphasic taxonomy related phenotypes). It will enclose information on taxonomy, ecology, morphology, physiology, and molecular biology, etc.',NULL,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (157,'DMS_Ensembl','DMS_Ensembl','https://idc.biosino.org/dms/dictionary/view/56','GET',NULL,'Ensembl supports research in comparative genomics, evolution, sequence variation and transcriptional regulation. Ensembl annotate genes, computes multiple alignments, predicts regulatory function and collects disease data.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (158,'DMS_EnvironmentOntology','DMS_EnvironmentOntology','https://idc.biosino.org/dms/dictionary/view/99','GET',NULL,'ENVO is a domain ontology concerned with "environments" of all kinds and aims to promote standardisation and interoperability of diverse data sets through the concise, controlled description of environment types across several levels of granularity',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (159,'DMS_GenCC','DMS_GenCC','https://idc.biosino.org/dms/dictionary/view/89','GET',NULL,'The GenCC DB provides information pertaining to the validity of gene-disease relationships, with a current focus on Mendelian diseases. ',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (160,'DMS_Gene4Denovo','DMS_Gene4Denovo','https://idc.biosino.org/dms/dictionary/view/83','GET',NULL,'Gene4Denovo provided a convenient interface for non-commercial users to freely search, browse, analysis, and download any data in the database. Most importantly, Gene4Denovo allows users to upload their genetic variants, identify co-segregated variants including DNMs, perform custom annotations, and prioritized pathogenetic variants and risk-genes. In summary, Gene4denovo bring great convenience to accelerate the interpretation of the pathogenicity and clinical implication of DNMs for geneticists, neurobiologists and clinicians.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (161,'DMS_Gene4MND','DMS_Gene4MND','https://idc.biosino.org/dms/dictionary/view/82','GET',NULL,'Motor neuron disease (MND) refers to several types of neurodegenerative disorders characterized by affecting upper and lower motor neurons, rapidly progressive weakness leading to paralysis and eventually death from respiratory failure. Gene4MND is a dedicated repository, platform and communication warehouse for MND that aims to accelerate genetic consulting, enhance the understanding of the diseases and facilitate MND research.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (162,'DMS_Gene4PD','DMS_Gene4PD','https://idc.biosino.org/dms/dictionary/view/81','GET',NULL,'Gene4PD, including following knowledge: (1) rare variants identified from PD patients, (2) copy-number variants (CNVs), (3) associated SNPs collected from GWAS, (4) differential expression genes, and (5) differential DNA methylation genes. Based on these different category data, Gene4PD prioritized a list of candidate genes with variant genetic evidences for further characterization.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (163,'DMS_GTDB','DMS_GTDB','https://idc.biosino.org/dms/dictionary/view/80','GET',NULL,'The Genome Taxonomy Database (GTDB) is an initiative to establish a standardised microbial taxonomy based on genome phylogeny, primarily funded by the Australian Research Council via a Laureate Fellowship (FL150100038), a Future Fellowship (FT170100213), and Discovery Project (DP220100900), with the welcome assistance of strategic funding from The University of Queensland.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (164,'DMS_HGNC','DMS_HGNC','https://idc.biosino.org/dms/dictionary/view/55','GET',NULL,'The HGNC is responsible for approving unique symbols and names for human loci, including protein coding genes, ncRNA genes and pseudogenes, to allow unambiguous scientific communication.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (165,'DMS_HPO','DMS_Human Phenotype Ontology','https://idc.biosino.org/dms/dictionary/view/2','GET',NULL,'The Human Phenotype Ontology (HPO) provides a standardized vocabulary of phenotypic abnormalities encountered in human disease. Each term in the HPO describes a phenotypic abnormality, such as Atrial septal defect. The HPO is currently being developed using the medical literature, Orphanet, DECIPHER, and OMIM. HPO currently contains over 13,000 terms and over 156,000 annotations to hereditary diseases. ',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (166,'DMS_ICD-10','DMS_ICD-10','https://idc.biosino.org/dms/dictionary/view/34','GET',NULL,'International Classification of Diseases 10th Revision. The global standard for diagnostic health information.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (167,'DMS_ICD-10-CM','DMS_ICD-10-CM','https://idc.biosino.org/dms/dictionary/view/35','GET',NULL,'An extended version of ICD-10-CM with selected ICD-9-CM (The International Classification of Diseases) diagnosis codes.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (168,'DMS_ICD-10-IN','DMS_ICD-10-IN','https://idc.biosino.org/dms/dictionary/view/38','GET',NULL,'International Classification of Diseases 10th Revision. The global standard for diagnostic health information.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (169,'DMS_ICD-10-PCS','DMS_ICD-10-PCS','https://idc.biosino.org/dms/dictionary/view/47','GET',NULL,'ICD-10-PCS is a totally new coding system designed to better accommodate the rapidly changing world of procedures. ICD-10-PCS provides a multi-axial design to the codes and is similar in design to Logical Observation Identifiers Names and Codes (LOINC).',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (170,'DMS_ICD-11','DMS_ICD-11','https://idc.biosino.org/dms/dictionary/view/48','GET',NULL,'International Classification of Diseases 11th Revision. The global standard for diagnostic health information.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (171,'DMS_ICD-9','DMS_ICD-9','https://idc.biosino.org/dms/dictionary/view/44','GET',NULL,'International Classification of Diseases 9th Revision. The global standard for diagnostic health information.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (172,'DMS_ICD-9-CM','DMS_ICD-9-CM','https://idc.biosino.org/dms/dictionary/view/45','GET',NULL,'The International Classification of Diseases, 9th Revision, Clinical Modification (ICD-9-CM) is based on the World Health Organization’s Ninth Revision, International Classification of Diseases (ICD-9). ICD-9-CM is the official system of assigning codes to diagnoses and procedures associated with hospital utilization in the United States.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (173,'DMS_ICD-9-IN','DMS_ICD-9-IN','https://idc.biosino.org/dms/dictionary/view/46','GET',NULL,'International Classification of Diseases 9th Revision. The global standard for diagnostic health information.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (174,'DMS_KEGG-Otholog','DMS_KEGG-Otholog','https://idc.biosino.org/dms/dictionary/view/59','GET',NULL,'The KO (KEGG Orthology) database is a database of molecular functions represented in terms of functional orthologs.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (175,'DMS_mc3','DMS_mc3','https://idc.biosino.org/dms/dictionary/view/21','GET',NULL,'Multi-Center Mutation Calling in TCGA Multiple Cancers project',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (176,'DMS_Medgen','DMS_Medgen','https://idc.biosino.org/dms/dictionary/view/90','GET',NULL,'MedGen is NCBI''s portal to information about conditions and phenotypes related to Medical Genetics. Terms from the NIH Genetic Testing Registry (GTR), UMLS, HPO, Orphanet, ClinVar and other sources are aggregated into concepts, each of which is assigned a unique identifier and a preferred name and symbol. The core content of the record may include names, identifiers used by other databases, mode of inheritance, clinical features, and map location of the loci affecting the disorder. ',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (177,'DMS_MeSH','DMS_MeSH','https://idc.biosino.org/dms/dictionary/view/54','GET',NULL,'MeSH (Medical Subject Headings) is the NLM controlled vocabulary thesaurus used for indexing articles for PubMed.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (178,'DMS_OMIM','DMS_OMIM','https://idc.biosino.org/dms/dictionary/view/60','GET',NULL,'Online Mendelian Inheritance in Man is a continuously updated catalog of human genes and genetic disorders and traits, with particular focus on the molecular relationship between genetic variation and phenotypic expression.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (179,'DMS_Ontobee','DMS_Ontobee','https://idc.biosino.org/dms/dictionary/view/100','GET',NULL,'Ontobee is a linked ontology data server that stores ontology information using RDF triple store technology and supports query, visualization and linkage of ontology terms and is also the default linked data server for publishing and browsing biomedical ontologies in the Open Biological Ontology (OBO) Foundry (OBO) library.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (180,'DMS_PMO','DMS_PMO','https://idc.biosino.org/dms/dictionary/view/43','GET',NULL,'a standardized ontology for human precision medicine with consistent, reusable and sustainable descriptions of human disease terms, genomic molecular, phenotype characteristics and related medical vocabulary disease concepts through collaborative efforts of researchers at Institute of Medical Information, Chinese Academy of Medical Sciences.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (181,'DMS_ProteinOntology','DMS_ProteinOntology','https://idc.biosino.org/dms/dictionary/view/11','GET',NULL,'PRO provides an ontological representation of protein-related entities by explicitly defining them and showing the relationships between them. Each PRO term represents a distinct class of entities (including specific modified forms, orthologous isoforms, and protein complexes) ranging from the taxon-neutral to the taxon-specific (e.g. the entity representing all protein products of the human SMAD2 gene is described in PR:Q15796; one particular human SMAD2 protein form, phosphorylated on the last two serines of a conserved C-terminal SSxS motif is defined by PR:000025934).',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (182,'DMS_PubChem_BioAssays','DMS_PubChem_BioAssays','https://idc.biosino.org/dms/dictionary/view/73','GET',NULL,'PubChem BioAssay contains small-molecule and RNAi screening data along with associated annotation information from contributing organizations. BioAssay contains a collection of bioactivity and toxicity data that has greatly supported research in fields such as medicinal chemistry, drug discovery, pharmaceutical genomics and informatics research. ',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (183,'DMS_PubChem_Compounds','DMS_PubChem_Compounds','https://idc.biosino.org/dms/dictionary/view/75','GET',NULL,'pubChem is an open archive accepting information from many sources about a given molecule, it is imperative to provide the end-user with an aggregated view of all that is known for a single chemical structure.  PubChem Compound records are derived summaries that give users access to a rich set of related content.  Compound records contain unique chemical structures extracted from contributed Substance records through a process called ‘standardization’.  Each Compound record points to at least one Substance record.  In contrast, a Substance record might have no derived Compound record if the structure cannot be standardized or is missing.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (184,'DMS_PubChem_Substance','DMS_PubChem_Substance','https://idc.biosino.org/dms/dictionary/view/74','GET',NULL,'PubChem Substance is the primary archive for community-provided information about chemical entities.  A Substance record can contain any combination of chemical structures, synonyms, registration IDs, descriptions, related URLs, patent identifiers, database cross-references to PubMed, protein 3D structures, and biological screening results to name a few.  ',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (185,'DMS_SFARI','DMS_SFARI','https://idc.biosino.org/dms/dictionary/view/79','GET',NULL,'SFARI Gene is an evolving database for the autism research community that is centered on genes implicated in autism susceptibility.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (186,'DMS_SnomedCT_International','DMS_SnomedCT_International','https://idc.biosino.org/dms/dictionary/view/37','GET',NULL,'SNOMED International determines global standards for health terms, an essential part of improving the health of humankind. We are committed to maintaining and growing our leadership as the global experts in healthcare terminology, ensuring SNOMED CT is the global language for clinical terms.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (187,'DMS_SnomedCT_US','DMS_SnomedCT_US','https://idc.biosino.org/dms/dictionary/view/36','GET',NULL,'The SNOMED CT United States (US) Edition is the official source of SNOMED CT for use in US healthcare systems. The US Edition is a standalone release that combines the content of both the US Extension and the International releases of SNOMED CT.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (188,'DMS_Swissprot','DMS_Swissprot','https://idc.biosino.org/dms/dictionary/view/19','GET',NULL,'UniProtKB/Swiss-Prot is the expertly curated component of UniProtKB (produced by the UniProt consortium). It contains hundreds of thousands of protein descriptions, including function, domain structure, subcellular location, post-translational modifications and functionally characterized variants.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (189,'DMS_VirusHostDB','DMS_VirusHostDB','https://idc.biosino.org/dms/dictionary/view/91','GET',NULL,'Virus-Host DB organizes data about the relationships between viruses and their hosts, represented in the form of pairs of NCBI taxonomy IDs for viruses and their hosts. Virus-Host DB covers viruses with complete genomes stored in 1) NCBI/RefSeq and 2) GenBank whose accession numbers are listed in EBI Genomes or INPHARED. The host information is collected from RefSeq, GenBank (in free text format), UniProt, ViralZone, and manually curated with additional information obtained by literature surveys.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (190,'DNAbcM','Common Microbial DNA Barcode Reference Library','https://mdc.im.ac.cn/microxiandao/dnabar','GET',NULL,'The Common Microbial DNA Barcode Reference Database curates microbial DNA barcode sequences along with their taxonomic information. Each record links a sequence to a clear taxonomic hierarchy that includes sample ID, species, family, and class. The platform enables advanced retrieval (by keywords, sample ID, lineage, etc.) and batch downloading of raw sequences.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (191,'doric','DoriC','http://tubic.org/doric/','GET',NULL,'Database of Replication Origins',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (192,'drllps','Drllps Database','https://llps.biocuckoo.cn','GET','A data resource of liquid-liquid phase separation in eukaryotes.','Liquid-liquid phase separation in eukaryotes Database',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (193,'ekpd','EKPD','http://ekpd.biocuckoo.org/','GET','The EKPD 1.1 contained 61,729 unique protein entries including 50,433 protein kinases and 11,296 protein phosphatases.','Eukaryotic Kinase and Phosphatase Database',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (194,'epsd','EPSD','http://epsd.biocuckoo.cn/','GET','The Eukaryotic Phosphorylation Site Database (EPSD) is a comprehensive data resource updated from two databases of dbPPT (Cheng, et al., 2014) and dbPAF (Ullah, et al., 2016), which contained 82,175 p-sites of 20 plants and 483,001 p-sites of 7 animals and fungi, respectively. EPSD contains 1,616,804 experimentally identified p-sites in 209,326 phosphoproteins from 68 eukaryotes.','Eukaryotic Phosphorylation Site Database',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (195,'EVEA','Extracellular Vesicle Atlas','http://bioinfo.life.hust.edu.cn/EVAtlas/','GET','EVAtlas provides four functional modules: (i) browse and compare the distribution of ncRNAs in EVs from 24 conditions and eight sources (plasma, serum, saliva, urine, sperm, breast milk, primary cell and cell line ); (ii) prioritize candidate ncRNAs in condition related tissues based on their expression; (iii) explore the specifically expressed ncRNAs in EVs from 24 conditions; (iv) investigate ncRNA functions, related drugs, target genes and EVs isolation methods.','In EVAtlas, we performed a unified read dynamic assignment algorithm (RDAA) considering mismatch and multi-mapping reads to quantify the expression profiles of seven ncRNA types (miRNA, snoRNA, piRNA, snRNA, rRNA, tRNA and Y RNA) in more than 2,030 high-quality small RNA-seq datasets of EV samples from 24 human tissues of different conditions (disease and normal).',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (196,'evmirna','EVmiRNA','http://bioinfo.life.hust.edu.cn/EVmiRNA/','GET','Extracellular vesicles (EVs) released by living cells include exosomes and microvesicles (MVs), which contain various molecules from parental cells and are potential sources for disease diagnostic and therapeutic biomarkers. miRNA is the most well-studied molecule type in EVs because of its important functions and biomarker properties. Thus, we build the Extracellular Vesicles miRNA database (EVmiRNA) to collect comprehensive miRNA expression profiles in EVs. In EVmiRNA database, we analyzed 462 smRNA sequencing datasets of EVs from 17 tissues/diseases. The miRNA expression profiles, miRNA regulated pathways, miRNA function, miRNA related drugs and publications are showed to support the miRNA biomarker discovery.','EVmiRNA is a database of miRNA profiling in extracellular vesicles',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (197,'genekang','VarClear','https://www.varclear.com','GET','VarClear锛屼腑鏂囧悕锛氭竻鐐癸紝鏄叧鑱斿熀鍥犲彉寮備笌瑙ｈ璇佹嵁鐨勪氦浜掑紡鏁版嵁搴撱�佺煡璇嗗簱銆�','Gene Variation Interpretation Database',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (198,'gentree','GenTree','http://gentree.ioz.ac.cn/','GET',' GenTree is designed to enable users to evaluate when and how a gene arises and what type of function it may have. For now, GenTree is the only systematical resource for new gene origination mainly in human and several other species. Ages of genes were inferred across species through a synteny-based pipeline. In human, Gene origination mechanism were also inferred and functional genomic data for new genes were complied.','GenTree, the time tree of genes along the evolutionary history',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (199,'gmsc','GMSC','https://gmsc.big-data-biology.org/','GET','The global microbial smORF catalogue (GMSC) is an integrated, consistently-processed, smORFs catalogue of the microbial world, combining publicly available metagenomes and high-quality isolated microbial genomes.A total of non-redundant ~965 million 100AA ORFs were predicted from 63,410 metagenomes from global habitats and 87,920 high-quality isolated microbial genomes from the ProGenomes database. The smORFs were clustered at 90% amino acid identity resulting in ~288 million 90AA smORFs families.','The global microbial smORF catalogue (GMSC) is an integrated, consistently-processed, smORFs catalogue of the microbial world, combining publicly available metagenomes and high-quality isolated microbial genomes.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (200,'hgmt','HGMT','https://mai.fudan.edu.cn/hgmt','GET','HGMT is a comprehensive database of the multi-kingdom gut microbiota from pan-tumor patients, which contains a rich collection of tumor-related biomarker taxa. Our efforts have led to the standardized processing of 16,195 treatment-naive human fecal samples, encompassing 35 WGS, 67 16S, and 3 ITS from 99 projects of 32 tumor types.','HGMT: deciphering the landscape of human gut microbiota in pan-tumor',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (201,'HGNC','HGNC','https://idc.biosinno.org/dms/dictionary/view/55','GET',NULL,'The HGNC is responsible for approving unique symbols and names for human loci, including protein coding genes, ncRNA genes and pseudogenes, to allow unambiguous scientific communication.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (202,'hPEA','Platelets expression atlas','http://bioinfo.life.hust.edu.cn/PEA/','GET','PEA provides a comprehensive repertoire of gene and miRNA expression profiles and advanced analysis results of each dataset: 1) Expression profiles of platelet in different diseases; 2) Average expression of a specified gene (miRNA) in health and various diseases; 3) Differential expression analysis, including functional enrichment of DEGs and protein-protein interaction network; 4) Platelet specifically expressed genes analysis.','Platelet Expression Atlas (PEA) is a comprehensive expression resource and functional analysis platform for human platelets',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (203,'hTFtarget','hTFtarget','http://bioinfo.life.hust.edu.cn/hTFtarget/','GET','Transcription factors (TFs) are key regulators in gene expression from DNA to mRNA by binding to specific DNA sequences on promoters and enhancers to activate or repress specific gene expressions. They play key roles in biological processes and disease occurrence by controlling the spatial and temporal-specific expression of genes. Thus identifying the target genes of TFs is very important in the study of gene expression regulation, development and disease pathogenesis. In this hTFtarget database, we collected comprehensive human TF ChIP-Seq data and customized an analysis workflow to identify reliable TF targets with taking epigenomic states into account.','In this hTFtarget database, we collected comprehensive human TF ChIP-Seq data and customized an analysis workflow to identify reliable TF targets with taking epigenomic states into account',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (204,'icellomics','iCellomics','https://ngdc.cncb.ac.cn/icellomics/','GET',NULL,'iCellOmics is an open-access, multi-omics resource for industrially relevant cell lines. Currently, iCellOmics integrates 6 data categories across 17 cell lines, including reference genome annotations, genomic variation, bulk and single-cell transcriptomics profiles, chromatin accessibility maps, and gene–phenotype relationships curated from the literature. ',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (205,'iekpd','iEKPD','http://iekpd.biocuckoo.org/','GET','The database iEKPD (integrated annotations for Eukaryotic protein Kinases, protein Phosphatases & phosphoprotein-binding Domains, ver 2.0) contained 197,348 phosphorylation regulators, including 109,912 protein kinases, 23,294 protein phosphatases and 68,748 PPBD-containing proteins in 164 eukaryotic species. Moreover, iEKPD provided rich annotations for the regulators of eight model organisms, especially humans, by compiling and integrating the knowledge from 100 widely used public databases that cover 13 aspects, including cancer mutations, genetic variations, disease-associated information, mRNA expression, DNA & RNA elements, DNA methylation, molecular interactions, drug-target relations, protein 3D structures, post-translational modifications, protein expressions/proteomics, subcellular localizations and protein functional annotations.','Integrated annotations for Eukaryotic protein Kinases, protein Phosphatases & phosphoprotein-binding Domains',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (206,'imp','IMP','https://www.bic.ac.cn/IMP','GET',NULL,'Intergrated Medicinal Plantomics',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (207,'ipangolin','iPangolin','https://ngdc.cncb.ac.cn/ipangolin/','GET',NULL,'iPangolin is the first integrated, multi-dimensional database dedicated to pangolins, the world’s most trafficked and critically endangered mammalian group. ',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (208,'ipcd','iPCD','http://ipcd.biocuckoo.cn/','GET','Programmed cell death (PCD) is an essential biological process involved in many human pathologies. According to the continuous discovery of new PCD forms, a large number of proteins have been found to regulate PCD. However, an integrative resource has yet to be established for maintaining these regulatory proteins. Here, we briefly summarize the mainstream PCD forms, as well as the current progress in the development of public databases to collect, curate and annotate PCD proteins. Also, we developed a comprehensive database, integrated annotations for programmed cell death (iPCD), which contained 1,091,014 regulatory proteins involved in 30 PCD forms across 562 eukaryotic species. From the scientific literature, we manually collected 6,493 experimentally identified PCD proteins, and an orthologous search was then conducted to computationally identify more potential PCD proteins. Additionally, we provided an in-depth annotation of PCD proteins in 8 model organisms, by integrating the knowledge from 102 additional resources that covered 16 aspects, including genetic variation and mutation, functional annotation, structural annotation, physicochemical property, functional domain, post-translational modification, disease-associated information, protein-protein interaction, drug-target relation, orthologous information, biological pathway, transcriptional regulator, mRNA expression, protein expression/proteomics, subcellular localization and DNA & RNA element. With a data volume of 125 GB, we anticipate that iPCD can serve as a highly useful resource for further analysis of PCD in eukaryotes.','database of PCD regulators',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (209,'iuucd','iUUCD','http://iuucd.biocuckoo.org/','GET','The released iUUCD (integrated annotations for Ubiquitin and Ubiquitin-like Conjugation Database, ver 2.0) is an updated systematic resource for ubiquitin and ubiquitin-like conjugations. 27 E1s, 109 E2s, 1,153 E3s, 164 DUBs, 396 UBDs and 183 ULDs were collected from scientific literatures and classified into 1, 4, 23, 8, 27, 11 families, respectively. The newly release added 6 new families for E2, E3 and DUB enzymes, as well as a hierarchical classification for UBD and ULD families. Specially, detailed annotations for all these proteins were integrated from additional 68 public databases in 11 aspects as follows: (i) Cancer Mutation, including ICGC, COSMIC, TCGA, CGAP and IntOGen; (ii) Single Nucleotide Polymorphism (SNP), such as dbSNP; (iii) mRNA Expression, including GEO, ArrayExpress, GXD, FFGED, TCGA, ICGC, COSMIC, HUMAN PROTEOME MAP and The Human Protein Atlas; (iv) DNA & RNA Element, including UTRdb, AREsite, JASPAR CORE, circBase, circRNADb, CircNet, Circ2Traits, miRTarBase, microRNA.org, TRANSFAC, miRWalk, TargetScan, miRecords, RepTar, miRNAMap, SomamiR DB 2.0, miRcode, RAID v2.0 and LncRNADisease; (v) Protein-protein Interaction, including IID, iRefIndex, PINA, HINT, Mentha, SZDB and InWeb_IM; (vi) Protein 3D Structure, including PDB, MMDB and SCOP; (vii) Disease-associated Variation, including ClinVar, OMIM, GWASdb and GWAS CENTRAL; (viii) Drug-target Relation, including DrugBank, TTD, KPID, CARLSBAD, SuperTarget, GRAC and PDTD; (ix) Post-translational Modifications (PTMs), including CPLM, dbPAF, dbPPT, phosSNP, PhosphositePlus, Phospho.ELM, dbPTM, PHOSIDA, BioGRID, HPRD, UniProt, O-GlycBase, PhosphoBase and mUbiSiDa; (x) DNA Methylation, including MethyCancer, TCGA, ICGC and COSMIC; (xi) Protein Expression/Proteomics, including The Human Protein Atlas, Human Proteome Map and GPMDB. All in all, from 148 eukaryotic species, 136,512 proteins were identified and annotated as unique entries in iUUCD.','integrated annotations for Ubiquitin and Ubiquitin-like Conjugation Database',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (210,'LeukemiaDB','LeukemiaDB','http://bioinfo.life.hust.edu.cn/LeukemiaDB/','GET','In detail, there are 14 leukemia types, 53 leukemia cell lines, and 92 normal samples. Through analysis by unique pipeline, we obtained comprehensive information for transcriptomes of human leukemia, including: expression for protein-coding genes, long non-coding RNAs, and circular RNAs, as well as events for gene fusion and alternative splicing. Additionally, we processed TCGA AML data (TCGA-LAML) for survival and drug response analysis. Users can browse the database by modules / diseases / cell lines and search gene on each page.','LeukemiaDB collects 3068 samples in 188 leukemia-associated RNA-seq datasets from NCBI GEO and SRA. ',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (211,'lncar','lnCAR','https://lncar.renlab.org/','GET','lnCAR is a comprehensive database that specifically dedicated to display differential expression profiles and prognostic landscape in human cancers by re-annotating microarray probes. At present, there are 10 cancer types and more than 54,000 samples collected in lnCAR (bladder cancer, breast cancer, cervical cancer, colorectal cancer, esophageal tumor, gastric cancer, liver cancer, lung cancer, ovarian cancer and prostatic cancer). Differential expression analysis, survival analysis, co-expression analysis, KEGG pathway enrichment analysis, ceRNA analysis and meta-analysis were integrated to explore the function of interested lncRNAs (including annotated lncRNAs or any user-defined ones). In addition to basic transcript information, structure and conservative score, we also integrated low-throughput data, such as real-time PCR and northern blot, into lnCAR as validation datasets. Furthermore, multiple statistical diagrams are also embedded in the web server for visualizing the analysis results.','lnCAR | A comprehensive resource for lncRNAs from Cancer Arrays',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (212,'lncbook','LncBook','https://bigd.big.ac.cn/lncbook','GET','LncBook is a curated knowledgebase of human lncRNAs that features a comprehensive collection of human lncRNAs and systematic curation of lncRNAs by multi-omics data integration, functional annotation and disease association. The current implementation of LncBook houses a large number of 270,044 lncRNAs and includes 1,867 featured lncRNAs with 3,762 lncRNA-function associations. It also integrates an abundance of multi-omics data from expression, methylation, genome variation and lncRNA-miRNA interaction. In addition, LncBook includes 3,772 experimentally validated lncRNA-disease associations and identifies a total of 97,998 lncRNAs that are putatively disease-associated. To facilitate online analysis, a series of useful tools such as coding potential prediction, sequence search, etc., are deployed in LncBook.','A curated knowledgebase of human long non-coding RNAs.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (213,'lncrnadisease','LncRNADisease','http://www.rnanut.net/lncrnadisease/','GET','Long noncoding RNAs (lncRNAs) represent the RNAs that have a size of >200 nucleotides and lack the capability of protein-coding. Although lncRNAs are among one of the least well-understood molecules, emerging studies have revealed that lncRNAs play critical roles in a broad range of biological processes and are associated with a number of diseases, i.e. cancer, cardiovascular disease, and neurodegeneration disease. LncRNAs are becoming critically important for the understanding of life sciences, especially diseases. The LncRNADisease database is not only a resource that curated the experimentally supported lncRNA-disease association data but also a platform that integrated tool(s) for predicting novel lncRNA-disease associatons. In addition, LncRNADisease also curated lncRNA interactions in various levels, including protein, RNA, miRNA, and DNA.','LncRNA diseases interaction database.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (214,'lncRNASNP v3','lncRNASNP v3','http://gong_lab.hzau.edu.cn/lncRNASNP3/','GET',NULL,'lncRNASNP v3: a comprehensive resources for functional variants in long non-coding RNAs.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (215,'lncrnasnp2','lncRNASNP2','http://bioinfo.life.hust.edu.cn/lncRNASNP2','GET',NULL,NULL,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (216,'m5catlas','m5C-Atlas','http://180.208.58.19/m5c-atlas/index.html','GET','The database contains 166,540 m5C sites in 13 species identified from 5 base-resolution epitranscriptome profiling technologies. Moreover, condition-specific methylation levels are quantified from 351 RNA bisulfite sequencing samples gathered from 22 different studies via an integrative pipeline. The database also presents several novel features, such as the evolutionary conservation of a m5C locus, its association with SNPs, and any relevance to RNA secondary structure.','A database for comprehensive collection and annotation of RNA 5-methylcytosine.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (217,'m6Aatlas2','m6A-Atlas v2.0','http://rnamd.org/m6a/index.php','GET','m6A-Atlas v2.0 was expanded to include 797,091 reliable m6A sites among 7 species, with 13 high-resolution technologies and 109 conditions. Additionally, sites derived from single-cell technique were presented for the first time. Besides high-resolution data, 16,868,200 m6A enriched regions were recorded in the updated version from 2,712 MeRIP-seq samples.','A comprehensive knowledgebase for unraveling the N6-methyladenosine (m6A) epitranscriptome.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (218,'m6AConquer','m6AConquer','https://rnamd.org/m6aconquer/','GET','m6AConquer integrates 10 sequencing technologies with unified quantification, orthogonal IDR-based validation, and multi-omics integration including transcriptomics, splicing and m6A QTLs.','A consistently quantified and orthogonally validated database for the m6A epitranscriptome.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (219,'m6atshub','m6A-TSHub','http://180.208.58.19/tshub/index.html','GET','We present here a comprehensive online platform, m6A-TSHub, for unveiling the context-specific m6A methylation and genetic mutations that potentially regulate m6A epigenetic mark.  m6A-TSHub consists of four core components, including (1) m6A-TSDB, a comprehensive database of 184,554 functionally annotated m6A sites derived from 23 human tissues and 499,369 m6A sites from 25 tumor conditions, respectively;  (2) m6A-TSFinder, a web server for high-accuracy prediction of m6A methylation sites within a specific tissue from RNA sequences, which was constructed using multi-instance deep neural networks with gated attention;  (3) m6A-TSVar, a web server for assessing the impact of genetic variants on tissue-specific m6A RNA modifications;  and (4) m6A-CAVar, a database of 587,983 The Cancer Genome Atlas (TCGA) cancer mutations (derived from 27 cancer types) that were predicted to affect m6A modifications in the primary tissue of cancers.','Unveiling thedynamics of the N6-methyladenosine(m6A) epitranscriptome.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (220,'m7ghub2','m7GHub V2.0','http://www.rnamd.org/m7GHub2/index.html','GET','The four main components presented in the first release have all been expanded: an m7GDB database containing 430,898 putative m7G sites identified in 23 species, collected from both widely applied next-generation sequencing (NGS) and the emerging Oxford Nanopore direct RNA sequencing (ONT) techniques; an m7GDiseaseDB hosting 156,206 m7G-associated variants (involving addition or removal of an m7G site), including 3,238 disease-relevant m7G-SNPs that may function through epitranscriptome disturbance; and two enhanced analysis modules to perform interactive analyses on the collections of m7G sites (m7GFinder) and functional variants (m7GSNPer). We expect that m7Ghub v2.0 should serve as a valuable centralized resource for studying m7G modification.','An updated resource for a comprehensive collection of m7G modifications in various types of RNAs across multiple species.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (221,'MCK','MiCroKiTS','http://microkit.biocuckoo.org/','GET','During cell cycle, numerous proteins temporally and spatially localized in distinct sub-cellular regions including centrosome (spindle pole in budding yeast), kinetochore/centromere, cleavage furrow/midbody (related or homolog structures in plants and budding yeast called as phragmoplast and bud neck, respectively), telomere and spindle spatially and temporally. These sub-cellular regions play important roles in various biological processes. In this work, we have collected all proteins identified to be localized on kinetochore, centrosome, midbody, telomere and spindle from two fungi (S. cerevisiae and S. pombe) and five animals, including C. elegans, D. melanogaster, X. laevis, M. musculus and H. sapiens based on the rationale of Seeing is believing (Bloom K et al., 2005). Through ortholog searches, the proteins potentially localized at these sub-cellular regions were detected in 144 eukaryotes. Then the integrated and searchable database MiCroKiTS - Midbody, Centrosome, Kinetochore, Telomere and Spindle has been established. Currently, the MiCroKiTS 4.0 database was updated on Sep. 6, 2014, containing 87,983 unique protein entries. The database will be updated routinely as new microkits proteins are reported.','Midbody, Centrosome, Kinetochore, Telomere and Spindle',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (222,'methbankCrm','Methbank CRMs','https://bigd.big.ac.cn/methbank/crms/','GET','450K data from GEO and TCGA, Consensus Reference Methylomes (CRMs)','Methbank, Consensus Reference Methylomes (CRMs)',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (223,'methbankSrm','MethBank SRMs','https://bigd.big.ac.cn/methbank/srms/','GET','Single-base Resolution Methylomes (SRMs)','Methbank, Single-base Resolution Methylomes (SRMs)',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (224,'mirnasnp','miRNASNP-v3','http://bioinfo.life.hust.edu.cn/miRNASNP/','GET','In miRNASNP-v3, 46,826 SNPs in human 1,897 pre-miRNAs (2,624 mature miRNAs) and 7,115,796  SNPs in 3''UTRs of 18,151 genes were characterized. Besides, 505,417 disease-related variations (DRVs) from GWAS, ClinVar and COSMIC were identified in miRNA and gene 3''UTR. Gene enrichment of target gain/loss by variations in miRNA seed region was provided.','miRNASNP-v3 is a comprehensive database for SNPs and disease-related variations in miRNAs and miRNA targets',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (225,'mmdb','MMDB','http://bigd.big.ac.cn/mmdb','GET','China is a large agricultural country, sustainable and stable agricultural products production has a very important strategic significance for ensuring food security in China. The seed is the source of food production. With the rapid development of life sciences, biotechnological breeding has become an inevitable choice for the development of modern seed industry. The status of breeding technology in China had put forward the concept of "designer breeding by molecular modules", the development construction of“innovation systems of designer breeding by molecular modules”could lead to a revolution in biotechnological breeding.
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (226,'mmge','mMGE','https://mai.fudan.edu.cn/mgedb/client/index.html#/','GET','mMGE integrates extrachromosomal mobile genetic elements(eMGEs) derived from more than 66,425 human metagenomic samples.','mMGE: Human metagenomic eMGE database',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (227,'ncRNA-eQTL','ncRNA-eQTL','http://ibi.hzau.edu.cn/ncRNA-eQTL/','GET',NULL,'A database to evaluate the effects of SNPs on ncRNA expression',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (228,'node','NODE','https://www.biosino.org/node/index','GET','NODE (The National Omics Data Encyclopedia) provides an integrated, compatible, comparable, and scalable multi-omics resource platform that supports flexible data management and effective data release. ','The National Omics Data Encyclopedia',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (229,'nucbank_nuc','Genbase Nucleotide','https://ngdc.cncb.ac.cn/nucbank/','GET','a collection of sequences from several sources, including GenBank. Genome, gene and transcript sequence data provide the foundation for biomedical research and discovery.','a collection of nucleotide sequences from several sources',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (230,'nucbank_pro','Genbase Protein','https://ngdc.cncb.ac.cn/nucbank/','GET','a collection of sequences from several sources, including GenBank. Genome, gene and transcript sequence data provide the foundation for biomedical research and discovery.','a collection of protein sequences from several sources',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (231,'openac4c','OpenAc4C','https://www.rnamd.org/ac4cportal/','GET','OpenAc4C is an integrated resource for ac4C RNA modification. It includes NGS acRIP-seq regions, NGS high-resolution sites, direct RNA sequencing-derived putative ac4C sites, ac4C-associated variants, and web-based analysis tools.','A gateway to decode the landscape, regulation and pathogenesis of N4-acetylcytidine (ac4C) epitranscriptome.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (232,'padsarsenal','PADS Arsenal','https://bigd.big.ac.cn/padsarsenal','GET','PADS (Prokaryotic Antiviral Defense System) Arsenal is a database of prokaryotic antiviral defense system, which archived genes that are associated with 18 distinctive categories of defense systems. It is dedicated to gathering, storing, analyzing and visualizing prokaryotic defense gene datasets. It also provides the function of multiple sequence alignment and conservative analysis for these defense genes in various species from pan-genome insights.','PADS Arsenal is a database of prokaryotic antiviral defense system',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (233,'pahg','PAHG: The Database of Human Multi-gene Families','https://www.pahgncb.com/genomedb/public/','GET','PAHG compiles human multi-gene families, unifies family definitions, and links to literature and external resources.','Curated human multi-gene families and their members.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (234,'pancan_mnvqtldb','Pancan-MNVQTLdb','http://gong_lab.hzau.edu.cn/mnvQTLdb','GET','A database to evaluate the effects of MNVs on multiple molecular phenotypes','A database to evaluate the effects of MNVs on multiple molecular phenotypes',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (235,'pancanmeqtl','Pancan-meQTL','http://gong_lab.hzau.edu.cn/Pancan-meQTL/','GET','Pancan-meQTL is a database to provide a comprehensive resource of methylation quantitative trait loci (meQTLs) for 23 human cancer types in TCGA with sample size larger than 100.','A database to evaluate the effects of SNPs on methylation.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (236,'pancanqtl','PancanQTL','http://gong_lab.hzau.edu.cn/PancanQTL/','GET','PancanQTL is a database to provide a comprehensive resource of expression quantitative loci (eQTLs) across 33 human cancer types.','A database to systematically identify cis-eQTLs and trans-eQTLs in 33 cancer types.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (237,'pcerbase','PceRBase','http://bis.zju.edu.cn/pcernadb','GET',NULL,'Plant competing endogenous RNA Database',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (238,'piRNAdb','piRNAdb','http://bigdata.ibp.ac.cn/piRBase/','GET',NULL,NULL,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (239,'Plant-ImputeDB','Plant-ImputeDB','http://gong_lab.hzau.edu.cn/Plant_imputeDB/','GET',NULL,'Plant-ImputeDB: an integrated multiple plant reference panel database for genotype imputation',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (240,'PlantTFDB','PlantTFDB','http://planttfdb.cbi.pku.edu.cn/','GET','Plant transcription factor database, a portal for the functional and evolutionary study of plant transcription factors','Plant transcription factor database, a portal for the functional and evolutionary study of plant transcription factors',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (241,'plmd','PLMD','http://plmd.biocuckoo.org/','GET','PLMD (Protein Lysine Modifications Database) is an online data resource specifically designed for protein lysine modifications (PLMs) including 284,780 modification events in 53,501 proteins across 176 eukaryotes and prokaryotes for up to 20 types of PLMs.','Protein Lysine Modifications Database',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (242,'poxvirus','MPoxVR','https://ngdc.cncb.ac.cn/gwh/poxvirus','GET','The Monkeypox Virus Resource (MPoxVR) is a one-stop monkeypox virus (MPXV) resource and portal that features virus genome sequences, genomic variations, related literatures, raw sequencing data and online tools.','The Monkeypox Virus Resource (MPoxVR) is a one-stop monkeypox virus (MPXV) resource and portal',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (243,'propan','ProPan','https://ngdc.cncb.ac.cn/propan/','GET','ProPan is a comprehensive prokaryotic pan-genome database toward understanding genomic dynamics','Prokaryotic Pan-genome',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (244,'ptmd','PTMD Database','https://ptmd.biocuckoo.cn','GET','A comprehensive resource for PTM-disease associations.','Post-Translational Modification Disease Database',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (245,'pwas atlas','PWAS Atlas','https://ngdc.cncb.ac.cn/pwas/','GET',NULL,'PWAS Atlas (https://ngdc.cncb.ac.cn/pwas/) is a comprehensive knowledgebase that systematically integrates publicly available proteome-wide association study (PWAS) findings with large-scale standardized analyses. ',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (246,'rhesusbaseGenes','RhesusBase Genes','http://rhesusbase.com','GET',NULL,NULL,TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (247,'rmdisease2','RMDisease V2.0','http://www.rnamd.org/rmdisease2/index.html','GET','An updated database with expanded coverage. Using deep learning models and from 873,819 experimentally-validated RNA modification sites, we identified a total of 1,366,252 RNA modification (RM)-associated variants that may affect (add or remove RM site) 16 different types of RNA modification (m6A, m5C, m1A, m5U, <ce><a8>, m6Am, m7G, A-to-I, ac4C, Am, Cm, Um, Gm, hm5C, D and f5C) in 20 organisms (human, mouse, rat, zebrafish, maize, fruit fly, yeast, fission yeast, Arabidopsis, rice, chicken, goat, sheep, pig, cow, rhesus monkey, tomato, chimpanzee, green monkey and COVID-19).','An updated database of genetic variants that affect RNA modifications with disease and trait implication',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (248,'rmvar_v2','RMVar v2.0','https://rmvar.renlab.cn/','GET',NULL,'Database of functional variants involved in RNA modifications',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (249,'scrapdb','ScRAPdb','https://evomicslab.org/db/ScRAPdb/','GET','Telomere-to-Telomere (T2T) Saccharomyces cerevisiae reference assemblies and population-scale pan-omics data','Saccharomyces cerevisiae Reference Assembly Panel Database',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (250,'SEECancer','SEECancer','http://biocc.hrbmu.edu.cn/SEECancer/','GET','Cancer is driven by accumulating somatic alterations which confer normal cells fitness advantage to evolve from a premalignant status to malignant tumor. The SEECancer database presents the comprehensive cancer evolutionary stage-specific somatic events (including early-specific, late-specific, relapse-specific, metastasis-specific, drug-resistant and drug-induced genomic events) and their temporal orders.','SEECancer: a resource for somatic events in evolution of cancer genome.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (251,'SEGreg','SEGreg','http://bioinfo.life.hust.edu.cn/SEGreg','GET','The specifically expressed genes (SEGs) only expressed in unique or a small number of tissues/conditions provide important clues about the gene and tissue-specific biological functions. SEGs may serve as potential biomarkers for disease diagnosis and treatment. The identification of SEGs will be helpful to globally and dynamically understand the gene functions and their roles in biological processes. However, the mechanisms of their specifically high or low expression remain to be revealed and explained urgently. SEGreg is a comprehensive database containing SEGs identified by our SEGtool from four high-throughput datasets of different cancers/tissues/cell lines (TCGA, BodyMap, CCLE and GTEx), along with their corresponding miRNA and TF regulations collected from several databases. SEGreg will provide useful clues to reveal the functions and regulations of SEGs','Database of specifically expressed genes and regulation',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (252,'semimags','SemiMAGs','https://semimags.netlify.app/','GET','SemiMAGs is an online resource for Metagenome-Assembled Genomes (MAGs) based on PacBio HiFi sequencing technology.','SemiMAGs is an online resource for Metagenome-Assembled Genomes (MAGs) based on PacBio HiFi sequencing technology.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (253,'sesbaniaomics','SesbaniaOmics','https://ngdc.cncb.ac.cn/sesbaniaomics','GET',NULL,'SesbaniaOmics is a specialized multi-omics database for Sesbania plants, integrating genomic, transcriptomic, proteomic, epigenomic, and phenotypic data. This resource supports research on salt-tolerance mechanisms, enabling genetic improvement and molecular breeding of stress-resistant crops. By providing comprehensive biological data, SesbaniaOmics facilitates sustainable agriculture in saline-affected regions, addressing global soil salinization challenges.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (254,'SNP2APA','SNP2APA','http://gong_lab.hzau.edu.cn/SNP2APA/','GET','A database to evaluate the effects of SNPs on APA events.','A database to evaluate the effects of SNPs on APA events',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (255,'spencer','SPENCER','https://spencer.renlab.org/','GET','SPENCER is a catalog of small peptides encoded by ncRNAs. The ncRNA encoding peptides were derived from re-annotation of public mass spectrometry data from over 1,700 patient samples spanning diverse cancers. SPENCER enables the users to simply and clearly explore differential expression of ncRNA peptides of interest in different cancer patients. In addition, SPENCER is also a powerful platform for querying the immunogenicity of peptides encoded by ncRNAs.','A comprehensive database for small peptides encoded by ncRNA in cancer patients',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (256,'Taxonomy','Taxonomy','https://www.ncbi.nlm.nih.gov/taxonomy','GET',NULL,'The Taxonomy Database is a curated classification and nomenclature for all of the organisms in the public sequence databases. This currently represents about 10% of the described species of life on the planet.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (257,'vcgdb','VCG','http://vcg.cbi.ac.cn/','GET','VCGDB is a big data solution based on public data released by 1000 Genomes Project.','Virtual Chinese Genome Database is a dynamic genome database of Chinese population.',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (258,'vfdb','VFDB','http://www.mgc.ac.cn/VFs/','GET','VFDB is a comprehensive knowledge base and a versatile analysis platform for bacterial virulence factors.','Virulence Factor Database',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (259,'weram','WERAM','http://weram.biocuckoo.org/','GET','WERAM 1.0 is a comprehensive Eukaryotic Writers, Erasers and Readers protein of Histone Acetylation and Methylation system Database for 148 eukaryotic species. Totally, WERAM database contained more than 20 thousand nonredundant histone regulators from 148 eukaryotes. The detailed annotations and classification information of histone regulators were provided, together with site-specific histone substrates if available.','Eukaryotic Writers, Erasers and Readers protein of Histone Acetylation and Methylation system Database',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (260,'ZCURVE_CoVdb','ZCURVE_CoVdb','http://tubic.tju,edu.cn/CoVdb/','GET',NULL,'Database of Essential Genes',TRUE,'ENABLED','SYSTEM','SYSTEM');
INSERT INTO database_resource(id,db_id,name,db_url,http_method,db_en_description,db_en_title,is_visible,status,create_by,update_by) VALUES (261,'π-omicskit','π-OmicsKit','https://ngdc.cncb.ac.cn/piomicskit/home','GET',NULL,'π-OmicsKit  is an expert-curated resource for reproducible primary processing of omics data. It currently provides 80 ready-to-run kits covering DNA-, RNA- and protein-level measurements across bulk, single-cell, long-read and spatial assays. ',TRUE,'ENABLED','SYSTEM','SYSTEM');
